window.THERAPEUTICS_DATA = {"sources":["Mental Health Study Guide (PED / NMS coursework)","Respiratory Therapeutics quizzes — midterm and final","Environmental Medicine lecture: Mold & Mycotoxins, Dr. Sabrina Koperski, ND","Mayan Abdominal Massage assignment","EKG Assessment assignment #2","Naturopathic Treatment Protocols (40 conditions)","Medication Suffixes study cards","Pelvic Therapy Reflection","Orthopedics Final Study Guide","Review of Systems intake form"],"pharmClasses":["Acid neutralisation","Acid suppression","Alpha-1 antagonist","Analgesic","Analgesic / anti-inflammatory","Anti-inflammatory","Anti-inflammatory + bronchodilator","Antianginal","Antibacterial","Anticoagulant","Antidepressant","Antidepressant / hypnotic","Antidepressant / smoking cessation","Antidiarrhoeal","Antiemetic","Antifibrinolytic","Antifibrotic","Antifungal","Antihistamine","Antihyperglycaemic","Antihypertensive","Antihypertensive / antianginal","Antihyperuricaemic","Antimigraine","Antimigraine / anticonvulsant","Antiparasitic","Antiplatelet","Antipsychotic","Antiresorptive","Antiviral","Anxiolytic","Anxiolytic / sedative","Anxiolytic antihistamine","Bile acid","Bronchodilator","Combination antibacterial","Comedolytic","Diuretic","Diuretic / antiandrogen","Fertility","Hormonal","Immunomodulator","Laxative","Lipid-lowering","Mitochondrial / MAOI","Monoclonal antibody","Mood stabiliser","Motility","Mucoactive","Mucosal protectant","NMDA antagonist","Neuromodulator","Non-absorbed antibiotic","Opioid antagonist","Retinoid","Sedative","Skeletal muscle relaxant","Smoking cessation","Smooth muscle relaxant","Sympathomimetic","Thyroid","Thyroid hormone","Urological"],"pharmGroups":["Respiratory & allergy","Mental health","Gastrointestinal","Cardiometabolic","Pain, MSK & immune","Urogenital & hormonal","Skin & infection","Smoking cessation"],"suppGroups":["Vitamins & minerals","Fatty acids & cofactors","Botanicals","Gut & binders","Amino acids & other"],"labKinds":["blood","urine","stool","micro","imaging","function","screen","procedure","specialty"],"therapyKinds":["Detoxification","Device","Environmental","Lifestyle","Manual therapy","Mind-body","Nutrition","Physical medicine","Physical therapy","Procedure","Psychosocial","Psychotherapy","Rehabilitation","Topical"],"pharmaceuticals":[{"id":"saba","name":"Short-acting β2 agonist (SABA)","cls":"Bronchodilator","use":"Rescue relief of acute bronchospasm; the reliever, not the controller.","examples":"albuterol/salbutamol, levalbuterol","caution":"Rising reliever use is the clearest sign asthma control is failing — escalate the controller, do not just refill.","grp":"Respiratory & allergy","conditions":["Asthma","Bronchiectasis","Bronchitis","Chronic obstructive pulmonary disease","Cough","Cystic fibrosis","Pneumonia","Respiratory failure and ARDS"]},{"id":"laba","name":"Long-acting β2 agonist (LABA)","cls":"Bronchodilator","use":"Maintenance bronchodilation in asthma and COPD.","examples":"salmeterol, formoterol, vilanterol","caution":"Never as monotherapy in asthma — always paired with an inhaled corticosteroid.","grp":"Respiratory & allergy","conditions":["Asthma","Bronchiectasis","Chronic obstructive pulmonary disease"]},{"id":"lama","name":"Long-acting muscarinic antagonist (LAMA)","cls":"Bronchodilator","use":"First-line maintenance in COPD; add-on in severe asthma.","examples":"tiotropium, umeclidinium, glycopyrronium","caution":"Caution in narrow-angle glaucoma and bladder outlet obstruction.","grp":"Respiratory & allergy","conditions":["Asthma","Chronic obstructive pulmonary disease"]},{"id":"sama","name":"Short-acting muscarinic antagonist (SAMA)","cls":"Bronchodilator","use":"Acute bronchospasm, often combined with a SABA in exacerbations.","examples":"ipratropium","caution":null,"grp":"Respiratory & allergy","conditions":["Chronic obstructive pulmonary disease"]},{"id":"ics","name":"Inhaled corticosteroid (ICS)","cls":"Anti-inflammatory","use":"Long-term control of persistent asthma — recommended for every patient with persistent asthma.","examples":"fluticasone, budesonide, beclomethasone","caution":"Rinse and spit to prevent oral candidiasis and dysphonia. In COPD reserved for frequent exacerbators or an eosinophilic phenotype — it raises pneumonia risk.","grp":"Respiratory & allergy","conditions":["Asthma","Bronchiectasis","Chronic obstructive pulmonary disease"]},{"id":"icslaba","name":"ICS/LABA combination inhaler","cls":"Anti-inflammatory + bronchodilator","use":"Maintenance, and in asthma also reliever therapy where a formoterol combination is used.","examples":"budesonide/formoterol, fluticasone/salmeterol","caution":null,"grp":"Respiratory & allergy","conditions":["Asthma"]},{"id":"ltra","name":"Leukotriene receptor antagonist","cls":"Anti-inflammatory","use":"Add-on in asthma, especially with allergic rhinitis or exercise-induced symptoms.","examples":"montelukast, zafirlukast","caution":"Boxed warning for serious neuropsychiatric events — ask directly about mood, sleep and suicidal thoughts.","grp":"Respiratory & allergy","conditions":["Allergic rhinitis","Asthma"]},{"id":"pde4","name":"PDE4 inhibitor","cls":"Anti-inflammatory","use":"Severe COPD with chronic bronchitis and repeated exacerbations.","examples":"roflumilast","caution":"Weight loss, diarrhoea and psychiatric effects are common reasons for stopping.","grp":"Respiratory & allergy","conditions":["Chronic obstructive pulmonary disease"]},{"id":"theoph","name":"Methylxanthine","cls":"Bronchodilator","use":"Third-line bronchodilation where inhaled therapy is not enough.","examples":"theophylline","caution":"Narrow therapeutic index — levels needed; many interactions.","grp":"Respiratory & allergy","conditions":["Asthma","Chronic obstructive pulmonary disease"]},{"id":"sysster","name":"Systemic corticosteroid","cls":"Anti-inflammatory","use":"Short bursts for asthma and COPD exacerbations, and for sarcoidosis and autoimmune flares.","examples":"prednisone, prednisolone, methylprednisolone","caution":"Hyperglycaemia, bone loss, adrenal suppression and mood change with repeated or prolonged courses.","grp":"Pain, MSK & immune","conditions":["Asthma","Autoimmune conditions","COVID-19","Chronic obstructive pulmonary disease","Gout","Hepatitis","Idiopathic pulmonary fibrosis","Inflammatory bowel disease","Multiple sclerosis","Osteoarthritis","Pneumonia","Pulmonary nodules and lung cancer","Respiratory failure and ARDS","Rheumatoid arthritis","Sarcoidosis"]},{"id":"biologic_resp","name":"Respiratory biologics","cls":"Monoclonal antibody","use":"Severe asthma not controlled on inhaled therapy, targeted by phenotype.","examples":"omalizumab (anti-IgE), mepolizumab/benralizumab (anti-IL5), dupilumab (anti-IL4R)","caution":"Specialist-initiated; phenotype (IgE, eosinophils) decides the agent.","grp":"Respiratory & allergy","conditions":["Asthma"]},{"id":"antifib","name":"Antifibrotics","cls":"Antifibrotic","use":"Slowing decline in idiopathic pulmonary fibrosis.","examples":"pirfenidone, nintedanib","caution":"LFT monitoring; photosensitivity with pirfenidone, diarrhoea with nintedanib.","grp":"Respiratory & allergy","conditions":["Idiopathic pulmonary fibrosis"]},{"id":"varen","name":"Varenicline","cls":"Smoking cessation","use":"Partial nicotine receptor agonist for smoking cessation — the single highest-yield intervention in COPD.","examples":null,"caution":"Active suicidal ideation is a contraindication. Screen mood before prescribing and at follow-up.","grp":"Smoking cessation","conditions":["Chronic obstructive pulmonary disease"]},{"id":"nrt","name":"Nicotine replacement therapy","cls":"Smoking cessation","use":"Patch for background craving with a short-acting form for breakthrough.","examples":"patch, gum, lozenge, inhaler","caution":null,"grp":"Smoking cessation","conditions":["Chronic obstructive pulmonary disease"]},{"id":"bupropion","name":"Bupropion","cls":"Antidepressant / smoking cessation","use":"Smoking cessation, and depression where sexual side effects or sedation are unwanted.","examples":null,"caution":"Lowers the seizure threshold — avoid in seizure disorder, bulimia and anorexia. Can worsen anxiety.","grp":"Mental health","conditions":["Attention deficit disorder","Depression"]},{"id":"muco","name":"Mucolytics and expectorants","cls":"Mucoactive","use":"Loosening tenacious secretions.","examples":"guaifenesin, hypertonic saline, dornase alfa (cystic fibrosis)","caution":null,"grp":"Respiratory & allergy","conditions":["Bronchiectasis","Bronchitis","Cough","Cystic fibrosis"]},{"id":"abx_resp","name":"Respiratory antibiotics","cls":"Antibacterial","use":"Bacterial pneumonia, bacterial sinusitis, and COPD exacerbations with purulent sputum.","examples":"amoxicillin, amoxicillin-clavulanate, doxycycline, azithromycin, respiratory fluoroquinolones","caution":"Not for uncomplicated viral URI or acute bronchitis — both are clinical diagnoses and usually viral.","grp":"Respiratory & allergy","conditions":["Bronchiectasis","Bronchitis","Burns","Chronic obstructive pulmonary disease","Cystic fibrosis","Gingivitis","Mold and mycotoxin illness","Otitis media","Pleural disease","Pneumonia","Respiratory failure and ARDS","Sinusitis","Sore throat","Tuberculosis"]},{"id":"oselt","name":"Neuraminidase inhibitor","cls":"Antiviral","use":"Influenza, best within 48 hours of onset; consider in high-risk groups.","examples":"oseltamivir, baloxavir","caution":null,"grp":"Respiratory & allergy","conditions":["Influenza","Pneumonia"]},{"id":"covid_av","name":"COVID-19 antivirals","cls":"Antiviral","use":"Early treatment in patients at risk of progression.","examples":"nirmatrelvir/ritonavir, remdesivir","caution":"Nirmatrelvir/ritonavir has extensive CYP3A4 interactions — screen the whole medication and supplement list.","grp":"Respiratory & allergy","conditions":["COVID-19"]},{"id":"antihist2","name":"Second-generation antihistamine","cls":"Antihistamine","use":"Allergic rhinitis, urticaria and the histamine component of atopy.","examples":"cetirizine, loratadine, fexofenadine","caution":"Far less sedating than first-generation agents; preferred for daytime use.","grp":"Respiratory & allergy","conditions":["Allergic rhinitis","Conjunctivitis","Sinusitis"]},{"id":"antihist1","name":"First-generation antihistamine","cls":"Antihistamine","use":"Short-term itch and sleep where sedation is acceptable.","examples":"diphenhydramine, hydroxyzine","caution":"Anticholinergic — avoid in older adults, and with glaucoma or urinary retention.","grp":"Respiratory & allergy","conditions":["Anxiety","Bronchitis","Common cold","Cough","Eczema","Insomnia","Interstitial cystitis","Nausea and vomiting","Sore throat","Vertigo"]},{"id":"inasal","name":"Intranasal corticosteroid","cls":"Anti-inflammatory","use":"First-line for persistent allergic rhinitis and an adjunct in sinusitis.","examples":"fluticasone, mometasone, budesonide nasal","caution":"Aim away from the septum to avoid epistaxis; takes days to work.","grp":"Respiratory & allergy","conditions":["Allergic rhinitis","Cough","Sinusitis"]},{"id":"decong","name":"Decongestants","cls":"Sympathomimetic","use":"Short-term relief of nasal congestion.","examples":"pseudoephedrine, oxymetazoline","caution":"Topical agents cause rebound congestion beyond 3 days; oral agents raise blood pressure.","grp":"Respiratory & allergy","conditions":["Allergic rhinitis","Common cold","Influenza","Otitis media","Sinusitis"]},{"id":"ampho_nasal","name":"Compounded antifungal nasal spray","cls":"Antifungal","use":"Fungal sinus colonisation in mould-exposed and treatment-resistant patients.","examples":"amphotericin B nasal spray","caution":"Compounded; from your mould lecture — well tolerated, including in children.","grp":"Respiratory & allergy","conditions":["Mold and mycotoxin illness","Sinusitis"]},{"id":"ssri","name":"SSRI","cls":"Antidepressant","use":"First-line drug therapy in depression, GAD, panic, OCD and PTSD.","examples":"sertraline, escitalopram, fluoxetine, paroxetine","caution":"Serotonin syndrome risk with St John's wort, tramadol, triptans, MAOIs and methylene blue. Activation and suicidality warning in under-25s; taper on stopping.","grp":"Mental health","conditions":["Adjustment disorder","Anxiety","Attention deficit disorder","Chronic fatigue syndrome","Cognitive decline","Depression","Irritable bowel syndrome","Menopause","Parkinson's disease","Post-traumatic stress disorder","Premenstrual syndrome"]},{"id":"snri","name":"SNRI","cls":"Antidepressant","use":"Depression and GAD, and useful where neuropathic pain or fibromyalgia coexist.","examples":"venlafaxine, duloxetine","caution":"Dose-dependent blood pressure rise with venlafaxine; marked discontinuation syndrome.","grp":"Mental health","conditions":["Anxiety","Chronic pain","Depression","Fibromyalgia","Menopause","Post-traumatic stress disorder"]},{"id":"mirtaz","name":"Mirtazapine","cls":"Antidepressant","use":"Depression with insomnia and poor appetite or weight loss.","examples":null,"caution":"Sedation and appetite gain are strongest at low doses.","grp":"Mental health","conditions":["Depression","Insomnia"]},{"id":"trazodone","name":"Trazodone","cls":"Antidepressant / hypnotic","use":"Low dose for sleep onset; higher doses for depression.","examples":null,"caution":"Orthostatic hypotension; priapism is rare but urgent.","grp":"Mental health","conditions":["Insomnia"]},{"id":"tca","name":"Tricyclic antidepressant","cls":"Antidepressant","use":"Migraine prophylaxis, neuropathic pain, fibromyalgia; less used now for depression.","examples":"amitriptyline, nortriptyline","caution":"Anticholinergic and cardiotoxic in overdose — caution where suicide risk is present.","grp":"Mental health","conditions":["Chronic pain","Fibromyalgia","Interstitial cystitis","Irritable bowel syndrome","Migraine"]},{"id":"buspirone","name":"Buspirone","cls":"Anxiolytic","use":"Generalised anxiety without the dependence risk of benzodiazepines.","examples":null,"caution":"Slow onset — weeks, not hours.","grp":"Mental health","conditions":["Anxiety"]},{"id":"benzo","name":"Benzodiazepine","cls":"Anxiolytic / sedative","use":"Short-term crisis anxiety and panic; alcohol withdrawal.","examples":"lorazepam, clonazepam, alprazolam","caution":"Not recommended in PTSD — they interfere with extinction learning, the goal of trauma therapy, and carry a high dependence risk. Additive with alcohol and opioids.","grp":"Mental health","conditions":["Anxiety","Post-traumatic stress disorder","Seizure disorder","Vertigo"]},{"id":"zdrug","name":"Non-benzodiazepine hypnotic","cls":"Sedative","use":"Short-term insomnia.","examples":"zolpidem, eszopiclone","caution":"Complex sleep behaviours carry a boxed warning; tolerance builds quickly.","grp":"Mental health","conditions":["Insomnia"]},{"id":"lithium","name":"Lithium carbonate","cls":"Mood stabiliser","use":"Bipolar disorder — the strongest anti-suicide evidence of any psychotropic.","examples":null,"caution":"Narrow therapeutic index. Levels, renal and thyroid function needed. NSAIDs, ACE inhibitors and thiazides raise levels; dehydration is dangerous.","grp":"Mental health","conditions":["Bipolar disorder"]},{"id":"moodstab","name":"Anticonvulsant mood stabilisers","cls":"Mood stabiliser","use":"Bipolar maintenance and mania; lamotrigine favours the depressed pole.","examples":"lamotrigine, valproate, carbamazepine","caution":"Lamotrigine needs slow titration for Stevens-Johnson risk. Valproate and carbamazepine are teratogenic; carbamazepine is a strong enzyme inducer.","grp":"Mental health","conditions":["Bipolar disorder","Seizure disorder"]},{"id":"atypical","name":"Second-generation antipsychotic","cls":"Antipsychotic","use":"Acute mania, bipolar depression, and augmentation in resistant depression.","examples":"quetiapine, aripiprazole, olanzapine, lurasidone","caution":"Metabolic syndrome, weight gain and QT prolongation — monitor weight, glucose and lipids.","grp":"Mental health","conditions":["Bipolar disorder","Depression"]},{"id":"ketamine","name":"Ketamine / esketamine","cls":"NMDA antagonist","use":"Treatment-resistant depression and suicidality; rapid onset, given as IV infusion or intranasal esketamine.","examples":null,"caution":"NMDA receptor antagonist that rapidly raises BDNF and promotes synaptogenesis. Dissociation and blood pressure rise require monitored administration.","grp":"Mental health","conditions":["Bipolar disorder","Depression","Post-traumatic stress disorder"]},{"id":"prazosin","name":"Prazosin","cls":"Alpha-1 antagonist","use":"PTSD-related nightmares and sleep disturbance.","examples":null,"caution":"First-dose orthostatic hypotension — start low, at night.","grp":"Mental health","conditions":["Post-traumatic stress disorder"]},{"id":"methblue","name":"Methylene blue","cls":"Mitochondrial / MAOI","use":"Studied as an adjunct to exposure therapy — enhances mitochondrial electron transport and helps consolidate fear-extinction memories.","examples":null,"caution":"Has MAOI properties. Avoid or use with extreme caution alongside SSRIs, SNRIs or any serotonergic agent — serotonin syndrome risk.","grp":"Mental health","conditions":["Post-traumatic stress disorder"]},{"id":"naltrexone_ld","name":"Low-dose naltrexone","cls":"Opioid antagonist","use":"Off-label for fibromyalgia, chronic pain, sarcoidosis and autoimmune conditions.","examples":null,"caution":"Blocks opioid analgesia; stop before procedures needing opioids.","grp":"Pain, MSK & immune","conditions":["Autoimmune conditions","Chronic fatigue syndrome","Chronic pain","Fibromyalgia","Multiple sclerosis","Sarcoidosis"]},{"id":"ppi","name":"Proton pump inhibitor","cls":"Acid suppression","use":"GERD, erosive oesophagitis, peptic ulcer, H. pylori regimens.","examples":"omeprazole, pantoprazole, esomeprazole","caution":"Aim for the shortest effective course. Long-term use is linked to B12, magnesium and iron malabsorption, C. difficile and fracture risk; rebound acid on abrupt stopping — taper.","grp":"Gastrointestinal","conditions":["Cough","Dyspepsia","GERD","Gastritis"]},{"id":"h2ra","name":"H2 receptor antagonist","cls":"Acid suppression","use":"Milder or intermittent reflux, and night-time breakthrough on a PPI.","examples":"famotidine","caution":"Tolerance develops within weeks.","grp":"Gastrointestinal","conditions":["Dyspepsia","GERD","Gastritis"]},{"id":"antacid","name":"Antacids and alginates","cls":"Acid neutralisation","use":"On-demand symptomatic relief; alginate rafts suit postprandial and night reflux.","examples":null,"caution":"Separate from other medicines by two hours — they impair absorption.","grp":"Gastrointestinal","conditions":["Dyspepsia","GERD"]},{"id":"sucral","name":"Sucralfate","cls":"Mucosal protectant","use":"Ulcer and mucosal protection; coats the ulcer base.","examples":null,"caution":"Binds other drugs — dose apart.","grp":"Gastrointestinal","conditions":["GERD","Gastritis"]},{"id":"prokin","name":"Prokinetics","cls":"Motility","use":"Gastroparesis and refractory reflux with delayed emptying.","examples":"metoclopramide, domperidone","caution":"Metoclopramide carries a tardive dyskinesia boxed warning — limit to 12 weeks.","grp":"Gastrointestinal","conditions":["Bloating and gas","Constipation","Dyspepsia","GERD","Nausea and vomiting","Small intestinal bacterial overgrowth"]},{"id":"antispas","name":"Antispasmodics","cls":"Smooth muscle relaxant","use":"Cramping pain in irritable bowel syndrome.","examples":"dicyclomine, hyoscyamine","caution":"Anticholinergic burden; avoid in older adults.","grp":"Gastrointestinal","conditions":["Bloating and gas","Irritable bowel syndrome"]},{"id":"rifax","name":"Rifaximin","cls":"Non-absorbed antibiotic","use":"IBS with diarrhoea and small intestinal bacterial overgrowth.","examples":null,"caution":"Poorly absorbed, so systemic effects are few; relapse is common.","grp":"Gastrointestinal","conditions":["Bloating and gas","Diarrhea","Irritable bowel syndrome","Small intestinal bacterial overgrowth"]},{"id":"loperamide","name":"Loperamide","cls":"Antidiarrhoeal","use":"Symptomatic control of non-infectious diarrhoea.","examples":null,"caution":"Avoid where there is fever or bloody stool — it prolongs invasive infection. QT prolongation at high doses.","grp":"Gastrointestinal","conditions":["Bloating and gas","Diarrhea","Irritable bowel syndrome"]},{"id":"laxative","name":"Laxatives","cls":"Laxative","use":"Constipation — osmotic agents first, stimulants for rescue.","examples":"polyethylene glycol, lactulose, magnesium, senna, docusate","caution":"Stimulant laxatives are for short-term use. Correct fibre, fluid and thyroid status first.","grp":"Gastrointestinal","conditions":["Constipation","Hemorrhoids","Irritable bowel syndrome"]},{"id":"ondan","name":"Ondansetron","cls":"Antiemetic","use":"Nausea and vomiting.","examples":null,"caution":"QT prolongation; constipation.","grp":"Gastrointestinal","conditions":["Nausea and vomiting","Vertigo"]},{"id":"mesalamine","name":"5-aminosalicylates","cls":"Anti-inflammatory","use":"Inflammatory bowel disease, mainly ulcerative colitis.","examples":"mesalamine, sulfasalazine","caution":"Monitor renal function.","grp":"Gastrointestinal","conditions":["Inflammatory bowel disease"]},{"id":"ursodiol","name":"Ursodeoxycholic acid","cls":"Bile acid","use":"Dissolving small cholesterol gallstones and in cholestatic liver disease.","examples":null,"caution":"Only works on small, non-calcified stones and takes months; recurrence is common.","grp":"Gastrointestinal","conditions":["Gallstones"]},{"id":"hpylori","name":"H. pylori eradication regimen","cls":"Combination antibacterial","use":"Confirmed H. pylori gastritis or ulcer.","examples":"PPI + amoxicillin + clarithromycin, or bismuth quadruple therapy","caution":"Test-of-cure at least 4 weeks after finishing, off PPI.","grp":"Gastrointestinal","conditions":["Dyspepsia","Gastritis"]},{"id":"antiparasitic","name":"Antiparasitics","cls":"Antiparasitic","use":"Confirmed intestinal parasites, chosen by organism.","examples":"albendazole, ivermectin, metronidazole, nitazoxanide, praziquantel","caution":"Treat on a positive stool test, not on suspicion alone.","grp":"Gastrointestinal","conditions":["Diarrhea","Parasites, intestinal"]},{"id":"statin","name":"Statin","cls":"Lipid-lowering","use":"Cardiovascular risk reduction in atherosclerosis and diabetes.","examples":"atorvastatin, rosuvastatin","caution":"Myalgia is common and usually reversible; check CK if severe. Interacts with grapefruit and red yeast rice — never combine the two.","grp":"Cardiometabolic","conditions":["Abdominal aortic aneurysm","Atherosclerosis","Diabetes mellitus, type 2","Erectile dysfunction","Hepatic steatosis","Statin-associated muscle symptoms"]},{"id":"acei","name":"ACE inhibitor","cls":"Antihypertensive","use":"Hypertension, heart failure, and renal protection in diabetic kidney disease.","examples":"lisinopril, ramipril","caution":"Dry cough (up to 20%) and angio-oedema. Contraindicated in pregnancy. Check potassium and creatinine after starting.","grp":"Cardiometabolic","conditions":["Abdominal aortic aneurysm","Atherosclerosis","Chronic kidney disease","Congestive heart failure","Diabetes mellitus, type 2","Erectile dysfunction","Hypertension"]},{"id":"arb","name":"Angiotensin receptor blocker","cls":"Antihypertensive","use":"As for ACE inhibitors, and the usual substitute when cough intervenes.","examples":"losartan, valsartan","caution":"Contraindicated in pregnancy; same potassium and renal monitoring.","grp":"Cardiometabolic","conditions":["Chronic kidney disease","Congestive heart failure","Hypertension"]},{"id":"ccb","name":"Calcium channel blocker","cls":"Antihypertensive","use":"Hypertension, and dihydropyridines for Raynaud's and vasospasm.","examples":"amlodipine, nifedipine, diltiazem, verapamil","caution":"Ankle oedema and constipation. Non-dihydropyridines are negatively inotropic — avoid in reduced ejection fraction.","grp":"Cardiometabolic","conditions":["Atrial fibrillation","Edema","Hypertension","Pulmonary hypertension","Raynaud's phenomenon"]},{"id":"thiazide","name":"Thiazide diuretic","cls":"Antihypertensive","use":"First-line hypertension; reduces calcium excretion in stone formers.","examples":"hydrochlorothiazide, chlorthalidone","caution":"Hyponatraemia, hypokalaemia, raised urate and glucose. Raises lithium levels.","grp":"Cardiometabolic","conditions":["Hypertension","Kidney stones"]},{"id":"bblocker","name":"Beta blocker","cls":"Antihypertensive / antianginal","use":"Heart failure with reduced ejection fraction, post-infarct, rate control, migraine prophylaxis, performance anxiety.","examples":"metoprolol, bisoprolol, carvedilol, propranolol","caution":"Avoid abrupt withdrawal. Caution in asthma and in Raynaud's, where they worsen vasospasm.","grp":"Cardiometabolic","conditions":["Abdominal aortic aneurysm","Atherosclerosis","Atrial fibrillation","Congestive heart failure","Hypertension","Hyperthyroidism","Migraine"]},{"id":"loop","name":"Loop diuretic","cls":"Diuretic","use":"Fluid overload in heart failure, and oedema from renal or hepatic causes.","examples":"furosemide, torsemide","caution":"Electrolyte loss, dehydration, ototoxicity at high doses. Daily weights guide the dose.","grp":"Cardiometabolic","conditions":["Chronic kidney disease","Congestive heart failure","Edema","Pulmonary hypertension"]},{"id":"mra","name":"Mineralocorticoid antagonist","cls":"Diuretic / antiandrogen","use":"Heart failure, resistant hypertension; and the androgenic features of PCOS and acne.","examples":"spironolactone, eplerenone","caution":"Hyperkalaemia — monitor potassium, and avoid combining with potassium supplements or ACE inhibitors without checking.","grp":"Cardiometabolic","conditions":["Acne","Congestive heart failure","Edema","Hypertension","Polycystic ovary syndrome"]},{"id":"nitrate","name":"Nitrates","cls":"Antianginal","use":"Angina relief and prophylaxis.","examples":"glyceryl trinitrate, isosorbide mononitrate","caution":"Absolutely contraindicated with PDE5 inhibitors — profound hypotension.","grp":"Cardiometabolic","conditions":["Atherosclerosis"]},{"id":"aspirin","name":"Low-dose aspirin","cls":"Antiplatelet","use":"Secondary prevention after a cardiovascular event.","examples":null,"caution":"GI bleeding risk. Avoid in children and teenagers with a viral illness — Reye's syndrome.","grp":"Cardiometabolic","conditions":["Atherosclerosis"]},{"id":"anticoag","name":"Anticoagulants","cls":"Anticoagulant","use":"Atrial fibrillation, venous thromboembolism, pulmonary embolism.","examples":"apixaban, rivaroxaban, warfarin, heparins","caution":"Bleeding risk. Warfarin interacts with vitamin K, many herbs and foods; DOACs have fewer but real interactions. Never start a supplement affecting platelets without checking.","grp":"Cardiometabolic","conditions":["Atrial fibrillation","COVID-19","Deep vein thrombosis","Pulmonary embolism","Pulmonary hypertension"]},{"id":"metformin","name":"Metformin","cls":"Antihyperglycaemic","use":"First-line in type 2 diabetes; also used in PCOS for insulin resistance.","examples":null,"caution":"GI upset; B12 depletion over years — check it. Hold around contrast imaging and in acute illness.","grp":"Cardiometabolic","conditions":["Diabetes mellitus, type 2","Hepatic steatosis","Obesity","Polycystic ovary syndrome"]},{"id":"glp1","name":"GLP-1 receptor agonist","cls":"Antihyperglycaemic","use":"Type 2 diabetes with obesity; substantial weight loss.","examples":"semaglutide, liraglutide, tirzepatide","caution":"Nausea, delayed gastric emptying; pancreatitis and thyroid C-cell warnings.","grp":"Cardiometabolic","conditions":["Diabetes mellitus, type 2","Hepatic steatosis","Obesity","Polycystic ovary syndrome"]},{"id":"sglt2","name":"SGLT2 inhibitor","cls":"Antihyperglycaemic","use":"Type 2 diabetes with cardiovascular or renal disease; heart failure independent of diabetes.","examples":"empagliflozin, dapagliflozin","caution":"Genital mycotic infection, volume depletion, and euglycaemic ketoacidosis.","grp":"Cardiometabolic","conditions":["Chronic kidney disease","Congestive heart failure","Diabetes mellitus, type 2","Hepatic steatosis","Obesity"]},{"id":"sulfonyl","name":"Sulfonylureas","cls":"Antihyperglycaemic","use":"Type 2 diabetes where cost governs.","examples":"glipizide, glimepiride","caution":"Hypoglycaemia and weight gain.","grp":"Cardiometabolic","conditions":["Diabetes mellitus, type 2"]},{"id":"insulin","name":"Insulin","cls":"Antihyperglycaemic","use":"Type 1 diabetes and advanced type 2.","examples":null,"caution":"Hypoglycaemia; needs structured education and monitoring.","grp":"Cardiometabolic","conditions":["Diabetes mellitus, type 2"]},{"id":"levothyrox","name":"Levothyroxine","cls":"Thyroid hormone","use":"Hypothyroidism.","examples":null,"caution":"Take fasted, and separate by four hours from calcium, iron, magnesium and coffee. Recheck TSH 6–8 weeks after any change.","grp":"Cardiometabolic","conditions":["Fertility and preconception","Hypothyroidism"]},{"id":"antithyroid","name":"Antithyroid drugs","cls":"Thyroid","use":"Hyperthyroidism and Graves' disease.","examples":"methimazole, propylthiouracil","caution":"Agranulocytosis — any sore throat or fever needs an urgent white cell count. Propylthiouracil is preferred in the first trimester.","grp":"Cardiometabolic","conditions":["Hyperthyroidism"]},{"id":"nsaid","name":"NSAIDs","cls":"Analgesic / anti-inflammatory","use":"Inflammatory and nociceptive pain, gout flares, dysmenorrhoea.","examples":"ibuprofen, naproxen, indomethacin, celecoxib","caution":"GI bleeding, renal impairment, blood pressure rise, and raised lithium levels. Avoid in chronic kidney disease and heart failure.","grp":"Pain, MSK & immune","conditions":["Back pain","Burns","Chronic pain","Dysmenorrhea","Endometriosis","Gout","Kidney stones","Migraine","Neck and shoulder pain","Osteoarthritis","Pleural disease","Premenstrual syndrome","Prostatitis","Rheumatoid arthritis","Urinary tract infection","Varicose veins"]},{"id":"acetamin","name":"Acetaminophen / paracetamol","cls":"Analgesic","use":"First-line simple analgesia, including where NSAIDs are unsafe.","examples":null,"caution":"Hepatotoxic in overdose and at lower doses with alcohol or fasting; count every combination product.","grp":"Pain, MSK & immune","conditions":["Back pain","Burns","Chronic pain","Common cold","Influenza","Neck and shoulder pain","Osteoarthritis","Otitis media","Sore throat"]},{"id":"colchicine","name":"Colchicine","cls":"Anti-inflammatory","use":"Acute gout, and prophylaxis when starting urate-lowering therapy.","examples":null,"caution":"Diarrhoea is dose-limiting; reduce in renal impairment; interacts with statins and CYP3A4 inhibitors.","grp":"Pain, MSK & immune","conditions":["Gout"]},{"id":"uratelower","name":"Urate-lowering therapy","cls":"Antihyperuricaemic","use":"Recurrent gout, tophi, or urate stones.","examples":"allopurinol, febuxostat","caution":"Can precipitate a flare when started — cover with prophylaxis. Allopurinol hypersensitivity is rare but severe.","grp":"Pain, MSK & immune","conditions":["Gout"]},{"id":"dmard","name":"Conventional DMARDs","cls":"Immunomodulator","use":"Rheumatoid arthritis, psoriatic disease, sarcoidosis, and other autoimmune conditions.","examples":"methotrexate, hydroxychloroquine, sulfasalazine, leflunomide","caution":"Methotrexate needs weekly dosing with folate, and CBC and LFT monitoring; it is teratogenic. Hydroxychloroquine needs annual retinal screening.","grp":"Pain, MSK & immune","conditions":["Autoimmune conditions","Inflammatory bowel disease","Multiple sclerosis","Psoriasis","Rheumatoid arthritis","Sarcoidosis"]},{"id":"biologic_imm","name":"Immunologic biologics","cls":"Monoclonal antibody","use":"Moderate to severe rheumatoid arthritis, psoriasis and inflammatory bowel disease.","examples":"TNF inhibitors, IL-17 and IL-23 inhibitors, rituximab","caution":"Screen for latent tuberculosis and hepatitis B before starting; infection risk throughout.","grp":"Pain, MSK & immune","conditions":["Autoimmune conditions","Eczema","Inflammatory bowel disease","Multiple sclerosis","Psoriasis","Rheumatoid arthritis","Sarcoidosis"]},{"id":"gabapentinoid","name":"Gabapentinoids","cls":"Neuromodulator","use":"Neuropathic pain, fibromyalgia, restless legs.","examples":"gabapentin, pregabalin","caution":"Sedation, dizziness, oedema; dose-reduce in renal impairment; misuse potential.","grp":"Pain, MSK & immune","conditions":["Back pain","Chronic pain","Fibromyalgia","Interstitial cystitis","Multiple sclerosis","Parkinson's disease"]},{"id":"musclerelax","name":"Muscle relaxants","cls":"Skeletal muscle relaxant","use":"Short courses for acute muscle spasm in neck and back pain.","examples":"cyclobenzaprine, methocarbamol, tizanidine","caution":"Sedation and anticholinergic effects; not for long-term use.","grp":"Pain, MSK & immune","conditions":["Back pain","Neck and shoulder pain"]},{"id":"triptan","name":"Triptans","cls":"Antimigraine","use":"Acute migraine, taken early in the attack.","examples":"sumatriptan, rizatriptan","caution":"Contraindicated in uncontrolled hypertension and coronary disease; serotonin syndrome risk with SSRIs. Limit to under 10 days a month to avoid medication-overuse headache.","grp":"Pain, MSK & immune","conditions":["Migraine"]},{"id":"cgrp","name":"CGRP-targeted therapies","cls":"Antimigraine","use":"Migraine prevention, and gepants for acute treatment.","examples":"erenumab, fremanezumab, rimegepant, ubrogepant","caution":"Constipation with some agents; specialist-initiated.","grp":"Pain, MSK & immune","conditions":["Migraine"]},{"id":"topiramate","name":"Topiramate","cls":"Antimigraine / anticonvulsant","use":"Migraine prophylaxis.","examples":null,"caution":"Cognitive slowing, paraesthesia, kidney stones, weight loss; teratogenic.","grp":"Pain, MSK & immune","conditions":["Migraine"]},{"id":"bisphos","name":"Bisphosphonates","cls":"Antiresorptive","use":"Osteoporosis and fracture prevention.","examples":"alendronate, risedronate, zoledronic acid","caution":"Take upright, fasted, with water. Correct vitamin D and calcium first. Rare osteonecrosis of the jaw and atypical femoral fracture.","grp":"Pain, MSK & immune","conditions":["Osteoporosis"]},{"id":"denosumab","name":"Denosumab","cls":"Antiresorptive","use":"Osteoporosis where bisphosphonates are unsuitable or renal function is poor.","examples":null,"caution":"Rebound vertebral fracture on stopping — never discontinue without a follow-on agent.","grp":"Pain, MSK & immune","conditions":["Osteoporosis"]},{"id":"alphablock","name":"Alpha-1 blocker","cls":"Urological","use":"Benign prostatic hyperplasia — fastest symptom relief.","examples":"tamsulosin, alfuzosin","caution":"Orthostatic hypotension and retrograde ejaculation; tell the ophthalmologist before cataract surgery.","grp":"Urogenital & hormonal","conditions":["Benign prostatic hyperplasia","Erectile dysfunction","Kidney stones","Prostatitis","Urinary incontinence"]},{"id":"fivear","name":"5-alpha reductase inhibitor","cls":"Urological","use":"Larger prostates — shrinks the gland over months.","examples":"finasteride, dutasteride","caution":"Halves the PSA — double the measured value when interpreting. Sexual side effects may persist.","grp":"Urogenital & hormonal","conditions":["Benign prostatic hyperplasia"]},{"id":"oab","name":"Overactive bladder agents","cls":"Urological","use":"Urgency incontinence after pelvic floor training.","examples":"oxybutynin, solifenacin, mirabegron","caution":"Anticholinergics add to cognitive burden in older adults; mirabegron raises blood pressure.","grp":"Urogenital & hormonal","conditions":["Benign prostatic hyperplasia","Urinary incontinence"]},{"id":"abx_uti","name":"Urinary antibiotics","cls":"Antibacterial","use":"Uncomplicated cystitis and pyelonephritis, guided by local resistance.","examples":"nitrofurantoin, trimethoprim-sulfamethoxazole, fosfomycin, cephalexin","caution":"Nitrofurantoin does not treat pyelonephritis and needs adequate renal function. Fluoroquinolones carry tendon and neuropathy warnings.","grp":"Urogenital & hormonal","conditions":["Sexually transmitted infection","Urinary tract infection"]},{"id":"abx_prostate","name":"Prostate-penetrating antibiotics","cls":"Antibacterial","use":"Bacterial prostatitis — long courses are needed to penetrate the gland.","examples":"fluoroquinolones, trimethoprim-sulfamethoxazole","caution":"4–6 weeks in chronic disease.","grp":"Urogenital & hormonal","conditions":["Prostatitis"]},{"id":"ocp","name":"Combined oral contraceptive","cls":"Hormonal","use":"Cycle control in PCOS, dysmenorrhoea, endometriosis and acne.","examples":null,"caution":"Thrombosis risk, raised in smokers over 35 and with migraine with aura. St John's wort reduces effectiveness.","grp":"Urogenital & hormonal","conditions":["Acne","Amenorrhea","Dysmenorrhea","Endometriosis","Menopause","Polycystic ovary syndrome","Premenstrual syndrome"]},{"id":"progestin","name":"Progestins and hormonal IUD","cls":"Hormonal","use":"Endometriosis, heavy menstrual bleeding, endometrial protection.","examples":"levonorgestrel IUD, norethindrone, dienogest","caution":"Irregular bleeding early on.","grp":"Urogenital & hormonal","conditions":["Amenorrhea","Dysmenorrhea","Endometriosis"]},{"id":"hrt","name":"Menopausal hormone therapy","cls":"Hormonal","use":"Vasomotor symptoms, and vaginal oestrogen for genitourinary syndrome of menopause.","examples":null,"caution":"Systemic therapy needs an individual risk discussion; unopposed oestrogen is unsafe with a uterus. Vaginal oestrogen is minimally absorbed.","grp":"Urogenital & hormonal","conditions":["Menopause","Osteoporosis","Urinary incontinence"]},{"id":"ovulation","name":"Ovulation induction","cls":"Fertility","use":"Anovulatory infertility, mainly in PCOS — letrozole is first-line.","examples":"letrozole, clomiphene","caution":"Multiple pregnancy risk; needs monitoring.","grp":"Urogenital & hormonal","conditions":["Amenorrhea","Fertility and preconception","Polycystic ovary syndrome"]},{"id":"gnrh","name":"GnRH agonists and antagonists","cls":"Hormonal","use":"Endometriosis pain unresponsive to first-line therapy.","examples":"leuprolide, elagolix","caution":"Induces a hypo-oestrogenic state — bone loss; add-back therapy is usual.","grp":"Urogenital & hormonal","conditions":["Endometriosis"]},{"id":"tranexamic","name":"Tranexamic acid","cls":"Antifibrinolytic","use":"Heavy menstrual bleeding, taken only on bleeding days.","examples":null,"caution":"Avoid with a thrombosis history.","grp":"Urogenital & hormonal","conditions":["Dysmenorrhea"]},{"id":"topster","name":"Topical corticosteroid","cls":"Anti-inflammatory","use":"Eczema and psoriasis flares, matched in potency to the site.","examples":null,"caution":"Skin atrophy with prolonged use; use the lowest effective potency on the face and flexures.","grp":"Skin & infection","conditions":["Burns","Eczema","Hemorrhoids","Psoriasis","Wound healing"]},{"id":"topcalc","name":"Topical calcineurin inhibitors","cls":"Immunomodulator","use":"Eczema on the face, eyelids and flexures, sparing steroids.","examples":"tacrolimus, pimecrolimus","caution":"Transient burning on application.","grp":"Skin & infection","conditions":["Eczema","Psoriasis"]},{"id":"topretin","name":"Topical retinoid","cls":"Comedolytic","use":"Acne — the core of any comedonal regimen.","examples":"tretinoin, adapalene","caution":"Irritation and photosensitivity; contraindicated in pregnancy.","grp":"Skin & infection","conditions":["Acne"]},{"id":"bpo","name":"Benzoyl peroxide","cls":"Antibacterial","use":"Acne, and pairing it with any topical antibiotic limits resistance.","examples":null,"caution":"Bleaches fabric; drying.","grp":"Skin & infection","conditions":["Acne"]},{"id":"acne_abx","name":"Acne antibiotics","cls":"Antibacterial","use":"Inflammatory acne, always alongside benzoyl peroxide or a retinoid, not alone.","examples":"doxycycline, clindamycin topical","caution":"Doxycycline causes photosensitivity and oesophagitis — take upright with water.","grp":"Skin & infection","conditions":["Acne"]},{"id":"isotret","name":"Isotretinoin","cls":"Retinoid","use":"Severe nodulocystic or scarring acne.","examples":null,"caution":"Absolutely contraindicated in pregnancy — pregnancy prevention programme required. LFT and lipid monitoring; mood change.","grp":"Skin & infection","conditions":["Acne"]},{"id":"antifungal","name":"Antifungals","cls":"Antifungal","use":"Candidiasis, tinea and onychomycosis.","examples":"fluconazole, terbinafine, nystatin, topical azoles","caution":"Azoles inhibit CYP3A4 — check interactions. Terbinafine and oral azoles need LFT awareness.","grp":"Skin & infection","conditions":["Candidiasis","Sexually transmitted infection"]},{"id":"antiviral_hsv","name":"Herpes antivirals","cls":"Antiviral","use":"Herpes simplex and zoster — episodic or suppressive.","examples":"acyclovir, valacyclovir","caution":"Start within 72 hours; adjust for renal function.","grp":"Skin & infection","conditions":["Herpes simplex","Sexually transmitted infection","Warts"]},{"id":"abx_topical_eye","name":"Topical ocular antibiotics","cls":"Antibacterial","use":"Bacterial conjunctivitis.","examples":"erythromycin ointment, polymyxin-trimethoprim","caution":"Most conjunctivitis is viral and self-limiting; a contact-lens wearer needs urgent review.","grp":"Skin & infection","conditions":["Conjunctivitis"]},{"id":"hepser_tx","name":"Hepatitis antivirals","cls":"Antiviral","use":"Chronic hepatitis B and C, chosen by genotype and stage.","examples":"tenofovir, entecavir, sofosbuvir-based regimens","caution":"Specialist-directed; direct-acting antivirals cure most hepatitis C. Screen before immunosuppression.","grp":"Skin & infection","conditions":["Hepatitis"]},{"id":"hydroxyzine","name":"Hydroxyzine","cls":"Anxiolytic antihistamine","use":"Short-term anxiety and itch without dependence risk.","examples":null,"caution":"Sedating and anticholinergic; QT prolongation at high doses.","grp":"Mental health","conditions":["Anxiety","Eczema"]}],"supplements":[{"id":"omega3","name":"Omega-3 fatty acids (EPA/DHA)","dose":"1–3 g EPA+DHA daily","mech":"Anti-inflammatory and neuroprotective; lowers triglycerides. Your mental health notes give 1–3 g for depression, bipolar and PTSD.","caution":"Additive with anticoagulants and antiplatelets at higher doses. Choose a tested product for oxidation and heavy metals.","also":null,"conditions":["Abdominal aortic aneurysm","Acne","Anxiety","Asthma","Atherosclerosis","Atrial fibrillation","Attention deficit disorder","Autoimmune conditions","Bipolar disorder","Bronchiectasis","Chronic kidney disease","Chronic obstructive pulmonary disease","Chronic pain","Cognitive decline","Deep vein thrombosis","Depression","Diabetes mellitus, type 2","Dysmenorrhea","Eczema","Endometriosis","Erectile dysfunction","Fertility and preconception","Gingivitis","Gout","Hepatic steatosis","Hepatitis","Hypertension","Inflammatory bowel disease","Lactation support","Menopause","Migraine","Multiple sclerosis","Neck and shoulder pain","Obesity","Obstructive sleep apnea","Osteoarthritis","Parkinson's disease","Pleural disease","Polycystic ovary syndrome","Post-traumatic stress disorder","Premenstrual syndrome","Psoriasis","Pulmonary embolism","Pulmonary nodules and lung cancer","Raynaud's phenomenon","Rheumatoid arthritis","Sarcoidosis","Seizure disorder","Statin-associated muscle symptoms"]},{"id":"magglyc","name":"Magnesium glycinate","dose":"200–400 mg elemental daily","mech":"Calming; cofactor in over 300 reactions. Your notes name the glycinate form specifically for absorption and neurological support.","caution":"Citrate and oxide forms are more laxative. Reduce in renal impairment.","also":"magnesium bisglycinate","conditions":["Adjustment disorder","Anxiety","Asthma","Atrial fibrillation","Attention deficit disorder","Back pain","Bipolar disorder","Chronic fatigue syndrome","Chronic pain","Congestive heart failure","Constipation","Depression","Diabetes mellitus, type 2","Dysmenorrhea","Edema","Endometriosis","Fatigue and low energy","Fibromyalgia","Gout","Hypertension","Hyperthyroidism","Insomnia","Interstitial cystitis","Kidney stones","Menopause","Migraine","Nausea and vomiting","Neck and shoulder pain","Obstructive sleep apnea","Osteoporosis","Parkinson's disease","Post-traumatic stress disorder","Premenstrual syndrome","Raynaud's phenomenon","Seizure disorder","Urinary incontinence","Vertigo"]},{"id":"vitd","name":"Vitamin D3","dose":"1000–5000 IU daily, titrated to level","mech":"Immune modulation, bone health, mood. Deficiency is itself associated with sleep apnoea severity.","caution":"Test rather than guess; take with fat and with vitamin K2 when dosing high.","also":"cholecalciferol","conditions":["Allergic rhinitis","Amenorrhea","Asthma","Autoimmune conditions","Back pain","Bronchiectasis","COVID-19","Celiac disease","Central sleep apnea","Chronic fatigue syndrome","Chronic kidney disease","Chronic obstructive pulmonary disease","Chronic pain","Cognitive decline","Common cold","Cystic fibrosis","Depression","Diabetes mellitus, type 2","Dysmenorrhea","Eczema","Endometriosis","Fatigue and low energy","Fertility and preconception","Fibromyalgia","Gingivitis","Hepatitis","Herpes simplex","Hypothyroidism","Idiopathic pulmonary fibrosis","Inflammatory bowel disease","Influenza","Lactation support","Menopause","Mold and mycotoxin illness","Multiple sclerosis","Obesity","Obstructive sleep apnea","Osteoarthritis","Osteoporosis","Otitis media","Parkinson's disease","Pneumonia","Polycystic ovary syndrome","Psoriasis","Pulmonary nodules and lung cancer","Respiratory failure and ARDS","Rheumatoid arthritis","Seizure disorder","Statin-associated muscle symptoms","Tuberculosis","Urinary incontinence","Vertigo"]},{"id":"bcomplex","name":"B-complex (B6, B9, B12)","dose":"Activated forms preferred","mech":"Cofactors for neurotransmitter synthesis and methylation. B6 as P5P is the cofactor for GABA synthesis.","caution":"High-dose B6 over long periods causes peripheral neuropathy. Check B12 before folate to avoid masking deficiency.","also":"P5P, methylfolate, methylcobalamin","conditions":["Anxiety","Attention deficit disorder","Bipolar disorder","Chronic fatigue syndrome","Cognitive decline","Depression","Fatigue and low energy","Lactation support","Multiple sclerosis","Nausea and vomiting","Post-traumatic stress disorder","Premenstrual syndrome","Seizure disorder"]},{"id":"lithorotate","name":"Lithium orotate","dose":"5–20 mg daily","mech":"Low-dose lithium for mood and anxiety; crosses the blood-brain barrier more readily than the carbonate form.","caution":"Not a substitute for prescription lithium in bipolar I. Your notes give the 5–20 mg range.","also":null,"conditions":["Bipolar disorder"]},{"id":"cbd","name":"Cannabidiol (CBD)","dose":"Varies widely by product","mech":"5-HT1A agonism, FAAH inhibition raising anandamide, and reduced amygdala reactivity — the three mechanisms in your notes.","caution":"Inhibits CYP3A4 and CYP2C19 — check interactions. Legal status varies.","also":null,"conditions":["Anxiety","Post-traumatic stress disorder"]},{"id":"ashwagandha","name":"Ashwagandha (Withania somnifera)","dose":"300–600 mg standardised extract","mech":"Adaptogen; modulates the HPA axis and lowers cortisol.","caution":"Avoid in hyperthyroidism — it raises thyroid hormones. Rare hepatotoxicity. Nightshade family.","also":null,"conditions":["Adjustment disorder","Anxiety","Post-traumatic stress disorder"]},{"id":"saffron","name":"Saffron (Crocus sativus)","dose":"30 mg daily","mech":"Raises serotonin; trials show efficacy comparable to fluoxetine in mild to moderate depression. Your notes give 30 mg.","caution":"Additive with serotonergic drugs.","also":null,"conditions":["Depression"]},{"id":"ltheanine","name":"L-theanine","dose":"200–400 mg daily","mech":"Promotes alpha brain waves and enhances GABA — anxiolytic without sedation.","caution":"Well tolerated; may lower blood pressure.","also":null,"conditions":["Adjustment disorder","Anxiety","Insomnia"]},{"id":"lavender","name":"Lavender (Silexan)","dose":"80 mg oral extract daily","mech":"Modulates GABA receptors; trial evidence in anxiety comparable to low-dose anxiolytics.","caution":"Eructation with a lavender taste.","also":null,"conditions":["Anxiety","Post-traumatic stress disorder"]},{"id":"chamomile","name":"Chamomile (Matricaria)","dose":"220–1100 mg extract, or as tea","mech":"Mild sedative; apigenin binds benzodiazepine receptors.","caution":"Asteraceae allergy.","also":null,"conditions":["Anxiety","Insomnia"]},{"id":"same","name":"SAMe","dose":"400–1600 mg daily","mech":"Methyl donor used in depression and osteoarthritis.","caution":"AVOID IN BIPOLAR — can induce mania or hypomania through serotonergic and methylation effects. Serotonergic interactions.","also":null,"conditions":["Depression"]},{"id":"sjw","name":"St John's wort (Hypericum)","dose":"300 mg standardised, three times daily","mech":"Mild to moderate depression.","caution":"AVOID IN BIPOLAR — documented to trigger mania and cycling. A potent CYP3A4 inducer: do not combine with SSRIs (serotonin syndrome), oral contraceptives, or anticoagulants.","also":null,"conditions":["Depression"]},{"id":"rhodiola","name":"Rhodiola rosea","dose":"200–400 mg standardised","mech":"Stimulating adaptogen for fatigue and stress resilience.","caution":"AVOID IN BIPOLAR — as a stimulating adaptogen it may worsen agitation or induce hypomania. Can disturb sleep if taken late.","also":null,"conditions":["Chronic fatigue syndrome","Fatigue and low energy"]},{"id":"ginseng","name":"Panax ginseng","dose":"200–400 mg standardised","mech":"Stimulating adaptogen for fatigue and cognition.","caution":"Caution in bipolar disorder — stimulating botanicals risk mood destabilisation. Raises blood pressure in some.","also":null,"conditions":["Cognitive decline","Fatigue and low energy"]},{"id":"nac","name":"N-acetyl cysteine (NAC)","dose":"600–1800 mg daily","mech":"Mucolytic and glutathione precursor. Named in your respiratory quizzes as the mucolytic of choice in COPD, and in the mould lecture as the gentler glutathione alternative in sensitive patients.","caution":"Nausea at higher doses. In active mould exposure your notes prefer NAC over glutathione, which can mobilise toxins.","also":null,"conditions":["Asthma","Bronchiectasis","Bronchitis","COVID-19","Chronic obstructive pulmonary disease","Cough","Cystic fibrosis","Endometriosis","Hepatic steatosis","Hepatitis","Idiopathic pulmonary fibrosis","Mold and mycotoxin illness","Pneumonia","Respiratory failure and ARDS","Sarcoidosis","Sinusitis"]},{"id":"quercetin","name":"Quercetin","dose":"500–1000 mg daily","mech":"Mast-cell stabiliser and antihistamine-like flavonoid; anti-inflammatory in allergy and asthma.","caution":"Take with bromelain or as phytosome for absorption; inhibits CYP3A4.","also":null,"conditions":["Allergic rhinitis","Asthma","COVID-19","Eczema","Idiopathic pulmonary fibrosis","Interstitial cystitis","Prostatitis","Sinusitis"]},{"id":"resveratrol","name":"Resveratrol","dose":"150–500 mg daily","mech":"Anti-inflammatory and antithrombotic — your COVID quiz names it as the agent addressing both inflammation and thrombus formation.","caution":"Mild antiplatelet effect; caution with anticoagulants.","also":null,"conditions":["COVID-19"]},{"id":"vitc","name":"Vitamin C","dose":"500–2000 mg daily in divided doses","mech":"Antioxidant; supports immune function and collagen synthesis; shortens cold duration modestly.","caution":"Loose stool at bowel tolerance. Caution with a history of oxalate stones.","also":null,"conditions":["Abdominal aortic aneurysm","Allergic rhinitis","Anemia, iron deficiency","Bronchitis","Burns","COVID-19","Common cold","Conjunctivitis","Constipation","Gallstones","Gingivitis","Gout","Herpes simplex","Influenza","Pneumonia","Raynaud's phenomenon","Respiratory failure and ARDS","Sexually transmitted infection","Sinusitis","Sore throat","Urinary tract infection","Varicose veins","Warts","Wound healing"]},{"id":"zinc","name":"Zinc","dose":"15–30 mg daily","mech":"Immune function, wound healing, taste and smell; lozenges shorten colds when started early.","caution":"Take with food; over 40 mg long-term depletes copper — pair or cycle.","also":null,"conditions":["Acne","Attention deficit disorder","Benign prostatic hyperplasia","Bronchitis","Burns","COVID-19","Candidiasis","Celiac disease","Common cold","Conjunctivitis","Diarrhea","Eczema","Erectile dysfunction","Gastritis","Herpes simplex","Hypothyroidism","Influenza","Mold and mycotoxin illness","Otitis media","Pneumonia","Polycystic ovary syndrome","Prostatitis","Psoriasis","Sexually transmitted infection","Sore throat","Tuberculosis","Warts","Wound healing"]},{"id":"elderberry","name":"Elderberry (Sambucus nigra)","dose":"Standardised extract or syrup","mech":"Antiviral support in colds and influenza.","caution":"Use cooked or standardised preparations; raw berries are emetic.","also":null,"conditions":["Bronchitis","Common cold","Cough","Influenza","Sore throat"]},{"id":"propolis","name":"Bee propolis","dose":"Standardised extract or throat spray","mech":"Antimicrobial and soothing in upper respiratory infection and sore throat.","caution":"Avoid with bee product allergy.","also":null,"conditions":["Bronchitis","Common cold","Cough","Herpes simplex","Influenza","Otitis media","Pneumonia","Sinusitis","Sore throat","Warts"]},{"id":"garlic","name":"Garlic (Allium sativum)","dose":"Aged extract or fresh clove","mech":"Antimicrobial, mild antihypertensive and lipid-lowering.","caution":"Antiplatelet effect — stop before surgery.","also":null,"conditions":["Atherosclerosis","Bronchitis","Candidiasis","Common cold","Hypertension","Parasites, intestinal","Warts"]},{"id":"boswellia","name":"Boswellia serrata","dose":"300–500 mg standardised, three times daily","mech":"5-LOX inhibitor; anti-inflammatory in arthritis, IBD and asthma.","caution":"Generally well tolerated; mild GI upset.","also":null,"conditions":["Asthma","Back pain","Chronic pain","Inflammatory bowel disease","Neck and shoulder pain","Rheumatoid arthritis"]},{"id":"curcumin","name":"Curcumin","dose":"500–1000 mg of an absorption-enhanced form","mech":"Broad anti-inflammatory acting on NF-κB.","caution":"Poor absorption unless formulated. Mild antiplatelet effect; may worsen reflux in some.","also":null,"conditions":["Autoimmune conditions","Back pain","Chronic obstructive pulmonary disease","Chronic pain","Dysmenorrhea","Endometriosis","Fibromyalgia","Inflammatory bowel disease","Neck and shoulder pain","Osteoarthritis","Pleural disease","Psoriasis","Pulmonary nodules and lung cancer","Rheumatoid arthritis","Sarcoidosis"]},{"id":"nattokinase","name":"Nattokinase","dose":"2000–4000 FU daily","mech":"Fibrinolytic enzyme used for circulation and clot burden.","caution":"Additive with anticoagulants and antiplatelets — do not combine without supervision.","also":null,"conditions":["Atherosclerosis","Deep vein thrombosis","Idiopathic pulmonary fibrosis","Pulmonary hypertension"]},{"id":"serrapeptase","name":"Serrapeptase","dose":"10–60 mg on an empty stomach","mech":"Proteolytic enzyme used for mucus and fibrin.","caution":"Same bleeding caution as other systemic enzymes.","also":null,"conditions":["Idiopathic pulmonary fibrosis"]},{"id":"glutathione","name":"Glutathione (liposomal or inhaled)","dose":"Varies by route","mech":"Master antioxidant; inhaled forms studied as an asthma adjunct.","caution":"Your mould lecture warns against glutathione, liver sauce and NAD+ during ACTIVE exposure — they mobilise toxins and cause redistribution. Inhaled glutathione is not safe for every asthma patient — sulphite-sensitive patients can bronchospasm.","also":null,"conditions":["Mold and mycotoxin illness"]},{"id":"pectasol","name":"PectaSol (modified citrus pectin)","dose":"Start ¼ tsp, increase as tolerated","mech":"The binder used in nearly all patients in your mould lecture: breaks biofilms, binds mycotoxins, lowers inflammatory cytokines.","caution":"Safe during exposure and in pregnancy, and well tolerated in infants — one of the few binders your notes allow during ongoing exposure.","also":null,"conditions":["Mold and mycotoxin illness"]},{"id":"ultrabinder","name":"Ultra Binder","dose":"Per product, away from food and medicines","mech":"Broad-spectrum binder covering charcoal, clay and more.","caution":"Binds nutrients and drugs — separate by at least two hours. Do not use with unmanaged constipation.","also":null,"conditions":["Mold and mycotoxin illness"]},{"id":"sboulardii","name":"Saccharomyces boulardii","dose":"5–20 billion CFU daily","mech":"Binds mycotoxins and helps candida; protects against antibiotic-associated and travellers' diarrhoea.","caution":"Avoid in central line patients and severe immunocompromise — fungaemia risk.","also":null,"conditions":["Candidiasis","Diarrhea","Irritable bowel syndrome","Mold and mycotoxin illness","Parasites, intestinal"]},{"id":"biocidin","name":"Biocidin","dose":"Titrate from a low drop count","mech":"Broad botanical antimicrobial used for gut treatment; your mould lecture uses it especially in children.","caution":"Start very low — die-off reactions are common.","also":null,"conditions":["Candidiasis","Mold and mycotoxin illness","Parasites, intestinal","Small intestinal bacterial overgrowth"]},{"id":"probiotic","name":"Probiotics","dose":"10–50 billion CFU daily, strain-specific","mech":"Restoring flora after antibiotics; strain-specific benefit in IBS, atopy and vaginal health.","caution":"Match the strain to the indication. Caution in severe immunocompromise.","also":"Lactobacillus, Bifidobacterium blends","conditions":["Acne","Allergic rhinitis","Autoimmune conditions","Bloating and gas","Bronchiectasis","Candidiasis","Celiac disease","Constipation","Diarrhea","Eczema","Food intolerance","Gingivitis","Inflammatory bowel disease","Irritable bowel syndrome","Mold and mycotoxin illness","Multiple sclerosis","Nausea and vomiting","Otitis media","Parasites, intestinal","Parkinson's disease","Prostatitis","Psoriasis","Rheumatoid arthritis","Sexually transmitted infection","Small intestinal bacterial overgrowth","Urinary tract infection"]},{"id":"lsakei","name":"Lactobacillus sakei","dose":"Per product, intranasal or oral","mech":"Resets the sinus microbiome after sinus treatment — the step your mould lecture puts last.","caution":null,"also":"Lanto Health","conditions":["Mold and mycotoxin illness","Sinusitis"]},{"id":"iron","name":"Iron","dose":"Elemental iron, often alternate-day","mech":"Iron deficiency with or without anaemia.","caution":"Alternate-day dosing absorbs better than daily. Take with vitamin C, away from calcium, coffee and thyroid medication. Constipation is common.","also":"ferrous bisglycinate, ferrous sulfate","conditions":["Amenorrhea","Anemia, iron deficiency","Attention deficit disorder","Celiac disease","Chronic fatigue syndrome","Chronic kidney disease","Fatigue and low energy","Fertility and preconception","Hypothyroidism","Inflammatory bowel disease","Lactation support","Mold and mycotoxin illness"]},{"id":"b12","name":"Vitamin B12","dose":"1000 mcg daily oral, or injection","mech":"Deficiency from metformin, PPIs, gastric surgery, vegan diets, or pernicious anaemia.","caution":"Check before starting folate. Methylcobalamin or hydroxocobalamin preferred.","also":null,"conditions":["Anemia, iron deficiency","Celiac disease","Cognitive decline","Diabetes mellitus, type 2","Fatigue and low energy","Hypothyroidism","Mold and mycotoxin illness","Vertigo"]},{"id":"folate","name":"Folate","dose":"400–800 mcg daily","mech":"Methylation, red cell production, preconception neural tube protection.","caution":"Never before excluding B12 deficiency — it masks the anaemia while the neuropathy progresses.","also":"methylfolate, 5-MTHF","conditions":["Anemia, iron deficiency","Celiac disease","Fertility and preconception"]},{"id":"iodine","name":"Iodine","dose":"150–300 mcg daily unless directed otherwise","mech":"Thyroid hormone synthesis; deficiency is one of the nutrient gaps corrected first in your mould protocol.","caution":"Excess can trigger or worsen thyroid autoimmunity — do not dose high in Hashimoto's without monitoring.","also":null,"conditions":["Hypothyroidism","Mold and mycotoxin illness"]},{"id":"selenium","name":"Selenium","dose":"100–200 mcg daily","mech":"Cofactor for thyroid hormone conversion; lowers thyroid antibodies in Hashimoto's.","caution":"Narrow window — over 400 mcg daily is toxic.","also":null,"conditions":["Autoimmune conditions","Hyperthyroidism","Hypothyroidism"]},{"id":"calcium","name":"Calcium","dose":"500–600 mg elemental, once or twice daily","mech":"Bone health where dietary intake is short.","caution":"Split doses absorb better; take with vitamin D and K2. Separate from iron and thyroid medication.","also":null,"conditions":["Celiac disease","Lactation support","Menopause","Osteoporosis","Premenstrual syndrome"]},{"id":"vitk2","name":"Vitamin K2 (MK-7)","dose":"100–200 mcg daily","mech":"Directs calcium to bone rather than arteries; pairs with vitamin D.","caution":"Interacts with warfarin — keep intake steady and tell the prescriber.","also":null,"conditions":["Atherosclerosis","Cystic fibrosis","Kidney stones","Menopause","Osteoporosis"]},{"id":"coq10","name":"Coenzyme Q10","dose":"100–300 mg daily","mech":"Mitochondrial support; migraine prophylaxis; replaces what statins deplete.","caution":"Ubiquinol form absorbs better with age. Mild blood-pressure lowering.","also":null,"conditions":["Atherosclerosis","Atrial fibrillation","Central sleep apnea","Chronic fatigue syndrome","Chronic obstructive pulmonary disease","Cognitive decline","Congestive heart failure","Erectile dysfunction","Fatigue and low energy","Fertility and preconception","Fibromyalgia","Gingivitis","Hypertension","Migraine","Multiple sclerosis","Parkinson's disease","Pulmonary hypertension","Statin-associated muscle symptoms"]},{"id":"riboflavin","name":"Riboflavin (B2)","dose":"400 mg daily","mech":"Migraine prophylaxis at this specific high dose; takes 2–3 months.","caution":"Turns urine bright yellow — expected.","also":null,"conditions":["Migraine"]},{"id":"melatonin","name":"Melatonin","dose":"0.5–3 mg, 1–2 hours before bed","mech":"Circadian phase shifting rather than sedation; lower doses often work better than higher.","caution":"Vivid dreams and morning grogginess at higher doses.","also":null,"conditions":["COVID-19","Fibromyalgia","Insomnia","Migraine"]},{"id":"fivehtp","name":"5-HTP","dose":"50–200 mg daily","mech":"Serotonin precursor for mood and sleep.","caution":"Do not combine with SSRIs, SNRIs or MAOIs — serotonin syndrome.","also":null,"conditions":["Depression"]},{"id":"glycine","name":"Glycine","dose":"3 g before bed","mech":"Improves sleep quality and lowers core temperature; also a phase II conjugation substrate.","caution":"Well tolerated.","also":null,"conditions":["Insomnia"]},{"id":"valerian","name":"Valerian (Valeriana officinalis)","dose":"300–600 mg extract before bed","mech":"Sleep onset; GABAergic.","caution":"Paradoxical stimulation in a minority; additive with sedatives.","also":null,"conditions":["Insomnia"]},{"id":"passionflower","name":"Passionflower (Passiflora incarnata)","dose":"Extract or tea","mech":"Anxiety and sleep; gentle GABAergic.","caution":"Additive sedation.","also":null,"conditions":["Anxiety","Insomnia"]},{"id":"berberine","name":"Berberine","dose":"500 mg two or three times daily","mech":"Lowers blood glucose and lipids comparably to metformin in trials; antimicrobial in gut dysbiosis.","caution":"Inhibits CYP3A4 — many interactions. Avoid in pregnancy and in infants (kernicterus risk).","also":null,"conditions":["Atherosclerosis","Candidiasis","Diabetes mellitus, type 2","Hepatic steatosis","Obesity","Parasites, intestinal","Polycystic ovary syndrome","Small intestinal bacterial overgrowth"]},{"id":"alphalipoic","name":"Alpha-lipoic acid","dose":"300–600 mg daily","mech":"Diabetic neuropathy and insulin sensitivity; antioxidant regenerating other antioxidants.","caution":"Can lower glucose — watch with hypoglycaemic drugs. Thiamine depletion with long use.","also":null,"conditions":["Diabetes mellitus, type 2","Multiple sclerosis"]},{"id":"chromium","name":"Chromium picolinate","dose":"200–1000 mcg daily","mech":"Insulin sensitivity and glycaemic control.","caution":"Modest effect; caution with hypoglycaemics.","also":null,"conditions":["Diabetes mellitus, type 2","Obesity"]},{"id":"inositol","name":"Myo-inositol","dose":"2–4 g twice daily","mech":"PCOS — improves ovulation, insulin sensitivity and androgen profile; also used in anxiety and OCD at higher doses.","caution":"Best evidence with a 40:1 myo- to D-chiro-inositol ratio. GI upset at high doses.","also":null,"conditions":["Amenorrhea","Diabetes mellitus, type 2","Fertility and preconception","Obesity","Polycystic ovary syndrome"]},{"id":"nadh","name":"NAD+ / nicotinamide riboside","dose":"250–500 mg daily","mech":"Mitochondrial and energy support.","caution":"Your mould lecture says avoid NAD+ during active exposure — it mobilises toxins.","also":null,"conditions":["Bipolar disorder","Chronic fatigue syndrome"]},{"id":"dgl","name":"Deglycyrrhizinated liquorice (DGL)","dose":"380–760 mg chewed before meals","mech":"Mucosal healing in gastritis, ulcer and reflux without the blood-pressure effect of whole liquorice.","caution":"Whole liquorice raises blood pressure and lowers potassium — DGL is the form to use long-term.","also":null,"conditions":["Dyspepsia","GERD","Gastritis"]},{"id":"slipperyelm","name":"Slippery elm / marshmallow root","dose":"As a demulcent tea or capsule","mech":"Coats and soothes irritated mucosa in reflux, gastritis and IBS.","caution":"Take away from medicines — it can slow absorption.","also":null,"conditions":["Cough","Dyspepsia","GERD","Gastritis","Sore throat"]},{"id":"pepomint","name":"Enteric-coated peppermint oil","dose":"180–225 mg two or three times daily","mech":"Antispasmodic with good trial evidence in IBS.","caution":"Must be enteric-coated or it worsens reflux; relaxes the lower oesophageal sphincter.","also":null,"conditions":["Bloating and gas","Irritable bowel syndrome","Small intestinal bacterial overgrowth"]},{"id":"psyllium","name":"Psyllium husk","dose":"5–10 g daily with plenty of water","mech":"Soluble fibre — helps both constipation and diarrhoea, and lowers LDL.","caution":"Introduce slowly with fluid; separate from medicines by two hours.","also":null,"conditions":["Bloating and gas","Constipation","Diarrhea","Hemorrhoids","Irritable bowel syndrome"]},{"id":"digenzyme","name":"Digestive enzymes","dose":"With meals","mech":"Bloating and incomplete digestion; pancreatic insufficiency needs prescription-strength enzymes.","caution":"Not a substitute for investigating persistent symptoms.","also":null,"conditions":["Bloating and gas","Celiac disease","Cystic fibrosis","Dyspepsia","Food intolerance","GERD","Irritable bowel syndrome","Small intestinal bacterial overgrowth"]},{"id":"betaine","name":"Betaine HCl","dose":"With protein meals, titrated","mech":"Hypochlorhydria contributing to bloating and poor mineral absorption.","caution":"Never with active ulcer, gastritis, or on a PPI or NSAID.","also":null,"conditions":["Bloating and gas","Dyspepsia","Food intolerance","Small intestinal bacterial overgrowth"]},{"id":"glutamine","name":"L-glutamine","dose":"5 g one to three times daily","mech":"Fuel for enterocytes; used for intestinal barrier repair.","caution":"Caution in cirrhosis and in active malignancy.","also":null,"conditions":["Autoimmune conditions","Bloating and gas","Burns","Celiac disease","Diarrhea","Food intolerance","Gastritis","Inflammatory bowel disease","Interstitial cystitis","Irritable bowel syndrome","Small intestinal bacterial overgrowth","Wound healing"]},{"id":"milkthistle","name":"Milk thistle (Silybum marianum)","dose":"200–400 mg silymarin daily","mech":"Hepatoprotective; used in hepatitis and fatty liver.","caution":"Generally safe; mild laxative effect.","also":null,"conditions":["Gallstones","Hepatic steatosis","Hepatitis"]},{"id":"melatonin_gerd","name":"Melatonin for reflux","dose":"3–6 mg at bedtime","mech":"Raises lower oesophageal sphincter tone; trial evidence as a reflux adjunct.","caution":"Daytime grogginess at higher doses.","also":null,"conditions":["GERD"]},{"id":"dmannose","name":"D-mannose","dose":"2 g daily for prevention","mech":"Prevents E. coli adhesion in recurrent urinary tract infection.","caution":"Not a treatment for established pyelonephritis.","also":null,"conditions":["Urinary incontinence","Urinary tract infection"]},{"id":"cranberry","name":"Cranberry (PACs)","dose":"36 mg proanthocyanidins daily","mech":"Recurrent UTI prevention; anti-adhesion rather than antibacterial.","caution":"Interacts with warfarin; sugar load in juices.","also":null,"conditions":["Urinary tract infection"]},{"id":"saw","name":"Saw palmetto (Serenoa repens)","dose":"320 mg standardised daily","mech":"Benign prostatic hyperplasia symptoms.","caution":"Trial results are mixed; mild antiplatelet effect.","also":null,"conditions":["Benign prostatic hyperplasia","Prostatitis"]},{"id":"betasito","name":"Beta-sitosterol","dose":"60–130 mg daily","mech":"Improves urinary flow in BPH with more consistent trial support than saw palmetto.","caution":"Well tolerated.","also":null,"conditions":["Benign prostatic hyperplasia","Prostatitis"]},{"id":"lycopene","name":"Lycopene","dose":"10–30 mg daily","mech":"Prostate health and antioxidant support.","caution":"Take with fat.","also":null,"conditions":["Benign prostatic hyperplasia"]},{"id":"vitex","name":"Vitex agnus-castus (chaste tree)","dose":"20–40 mg extract each morning","mech":"Luteal phase support, PMS, cyclical breast pain and irregular cycles; acts on dopamine and prolactin.","caution":"Takes three cycles. Interacts with dopaminergic drugs and hormonal contraception.","also":null,"conditions":["Amenorrhea","Dysmenorrhea","Premenstrual syndrome"]},{"id":"dim","name":"DIM / indole-3-carbinol","dose":"100–200 mg daily","mech":"Supports oestrogen metabolism toward the 2-hydroxy pathway.","caution":"Can cause headache and darkened urine.","also":null,"conditions":["Acne","Endometriosis","Polycystic ovary syndrome","Premenstrual syndrome"]},{"id":"blackcohosh","name":"Black cohosh (Actaea racemosa)","dose":"20–40 mg standardised twice daily","mech":"Vasomotor symptoms of menopause.","caution":"Rare hepatotoxicity — stop with any jaundice or dark urine.","also":null,"conditions":["Menopause"]},{"id":"maca","name":"Maca (Lepidium meyenii)","dose":"1.5–3 g daily","mech":"Libido, energy and menopausal symptoms without direct hormonal action.","caution":"Caution with thyroid disease — goitrogenic raw.","also":null,"conditions":["Amenorrhea","Erectile dysfunction","Fertility and preconception","Menopause"]},{"id":"glucosamine","name":"Glucosamine and chondroitin","dose":"1500 mg / 1200 mg daily","mech":"Osteoarthritis, especially of the knee; effect is modest and slow.","caution":"Shellfish-derived forms in allergy; may affect glucose control slightly.","also":null,"conditions":["Osteoarthritis"]},{"id":"collagen","name":"Collagen peptides","dose":"10–15 g daily","mech":"Joint, skin and connective tissue support; some trial support in osteoarthritis.","caution":"Take with vitamin C.","also":null,"conditions":["Burns","Osteoarthritis","Osteoporosis","Wound healing"]},{"id":"msm","name":"MSM","dose":"1–3 g daily","mech":"Sulphur donor used for joint pain and inflammation.","caution":"Mild GI upset.","also":null,"conditions":["Chronic pain","Osteoarthritis"]},{"id":"tarter","name":"Tart cherry","dose":"Concentrate or 500 mg extract","mech":"Lowers urate and eases gout flares; also studied for sleep.","caution":"Sugar load in juice form.","also":null,"conditions":["Gout"]},{"id":"bromelain","name":"Bromelain","dose":"500–1000 mg between meals","mech":"Proteolytic anti-inflammatory for sinusitis, injury and oedema; pairs with quercetin.","caution":"Antiplatelet effect; pineapple allergy.","also":null,"conditions":["Allergic rhinitis","Burns","Sinusitis","Wound healing"]},{"id":"astragalus","name":"Astragalus membranaceus","dose":"500–1000 mg daily","mech":"Immune tonic for recurrent infection; used long-term rather than acutely.","caution":"Traditionally avoided during an acute fever; theoretical interaction with immunosuppressants.","also":null,"conditions":["Chronic fatigue syndrome","Common cold","Influenza"]},{"id":"mushroom","name":"Medicinal mushrooms","dose":"Extract per product","mech":"Beta-glucan immune modulation in recurrent infection and immune dysregulation.","caution":"Choose fruiting-body extracts; caution with immunosuppressants.","also":"reishi, turkey tail, cordyceps","conditions":["Chronic fatigue syndrome","Common cold","Herpes simplex","Pulmonary nodules and lung cancer","Sexually transmitted infection","Warts"]},{"id":"licorice_dgl","name":"Liquorice (Glycyrrhiza glabra)","dose":"Standardised extract","mech":"Demulcent and antiviral; adrenal support in fatigue.","caution":"Whole liquorice raises blood pressure and lowers potassium — not for hypertension; use DGL for gut work.","also":null,"conditions":["Fatigue and low energy","Sore throat"]},{"id":"adaptogen_blend","name":"Adaptogen blends","dose":"Per product","mech":"HPA-axis support in fatigue and chronic stress.","caution":"Stimulating adaptogens destabilise mood in bipolar disorder — check the ingredient list.","also":"eleuthero, schisandra, holy basil","conditions":["Chronic fatigue syndrome","Fatigue and low energy"]},{"id":"creatine","name":"Creatine monohydrate","dose":"3–5 g daily","mech":"Muscle and cognitive support; emerging evidence in depression and fatigue.","caution":"Take with adequate fluid.","also":null,"conditions":["Cognitive decline","Depression","Parkinson's disease"]},{"id":"carnitine","name":"L-carnitine","dose":"1–2 g daily","mech":"Fatty acid transport into mitochondria; fatigue and male fertility.","caution":"Fishy odour at high doses; TMAO questions.","also":null,"conditions":["Chronic fatigue syndrome","Congestive heart failure","Erectile dysfunction","Fatigue and low energy","Fertility and preconception","Fibromyalgia","Hyperthyroidism","Multiple sclerosis","Parkinson's disease","Pulmonary hypertension"]},{"id":"dribose","name":"D-ribose","dose":"5 g up to three times daily","mech":"ATP substrate used in fibromyalgia and chronic fatigue.","caution":"Can lower blood glucose.","also":null,"conditions":["Chronic fatigue syndrome","Fibromyalgia"]},{"id":"phosphatidyl","name":"Phosphatidylserine","dose":"100–300 mg daily","mech":"Blunts an exaggerated cortisol response; cognition.","caution":"Take earlier in the day.","also":null,"conditions":["Anxiety","Attention deficit disorder","Chronic fatigue syndrome","Cognitive decline","Fatigue and low energy"]},{"id":"lionsmane","name":"Lion's mane (Hericium erinaceus)","dose":"500–1000 mg daily","mech":"Nerve growth factor support; cognition and mild mood benefit.","caution":"Rare skin reactions.","also":null,"conditions":["Attention deficit disorder","Cognitive decline"]},{"id":"ginkgo","name":"Ginkgo biloba","dose":"120–240 mg standardised daily","mech":"Cerebral and peripheral circulation; cognition; Raynaud's.","caution":"Antiplatelet effect — stop two weeks before surgery and avoid with anticoagulants.","also":null,"conditions":["Cognitive decline","Dysmenorrhea","Erectile dysfunction","Raynaud's phenomenon","Vertigo"]},{"id":"hawthorn","name":"Hawthorn (Crataegus)","dose":"300–1800 mg standardised daily","mech":"Mild heart failure and hypertension; improves exercise tolerance.","caution":"Potentiates digoxin and antihypertensives.","also":null,"conditions":["Congestive heart failure","Hypertension"]},{"id":"citrusflav","name":"Diosmin / hesperidin (citrus flavonoids)","dose":"500–1000 mg daily","mech":"Venous tone in varicose veins, haemorrhoids and chronic venous insufficiency — the best-supported oral agent.","caution":"GI upset; avoid in pregnancy.","also":null,"conditions":["Deep vein thrombosis","Edema","Hemorrhoids","Kidney stones","Varicose veins"]},{"id":"horsechest","name":"Horse chestnut seed extract","dose":"50 mg aescin twice daily","mech":"Chronic venous insufficiency and leg oedema.","caution":"Standardised extracts only — raw seed is toxic.","also":null,"conditions":["Edema","Hemorrhoids","Varicose veins"]},{"id":"butchers","name":"Butcher's broom (Ruscus)","dose":"Standardised extract","mech":"Venous tone and haemorrhoids.","caution":"Caution in hypertension.","also":null,"conditions":["Hemorrhoids","Varicose veins"]},{"id":"gotukola","name":"Gotu kola (Centella asiatica)","dose":"60–120 mg triterpenes daily","mech":"Connective tissue and venous integrity; wound healing; anxiolytic.","caution":"Rare hepatotoxicity with long use.","also":null,"conditions":["Burns","Varicose veins","Wound healing"]},{"id":"aloe","name":"Aloe vera (inner leaf)","dose":"Per product","mech":"Mucosal soothing in reflux and IBD; topical for burns and wounds.","caution":"Whole-leaf latex is a harsh stimulant laxative — use inner-leaf preparations orally.","also":null,"conditions":["Burns","Dyspepsia","GERD","Gastritis","Inflammatory bowel disease","Interstitial cystitis"]},{"id":"vitaminA","name":"Vitamin A","dose":"5000–10000 IU daily short term","mech":"Epithelial integrity, immune function, wound healing.","caution":"Teratogenic — strict limits in pregnancy. Hepatotoxic long-term.","also":null,"conditions":["Acne","Burns","Cystic fibrosis","Tuberculosis","Warts","Wound healing"]},{"id":"vite","name":"Vitamin E (mixed tocopherols)","dose":"200–400 IU daily","mech":"Antioxidant; membrane protection.","caution":"Antiplatelet at higher doses; use mixed tocopherols, not alpha alone.","also":null,"conditions":["Cystic fibrosis","Hepatic steatosis"]},{"id":"nacetylglu","name":"Colostrum / immunoglobulins","dose":"Per product","mech":"Gut barrier and mucosal immunity.","caution":"Dairy-derived — avoid in milk protein allergy.","also":null,"conditions":["Food intolerance","Irritable bowel syndrome"]},{"id":"hepavit","name":"Choline and inositol (lipotropics)","dose":"Per product","mech":"Fat mobilisation in fatty liver and cholestasis.","caution":"GI upset; fishy odour with high choline.","also":null,"conditions":["Gallstones","Hepatic steatosis"]},{"id":"taurine","name":"Taurine","dose":"500–2000 mg daily","mech":"Bile conjugation, cardiac and neuronal stability.","caution":"Well tolerated.","also":null,"conditions":["Atrial fibrillation","Congestive heart failure","Edema","Gallstones","Hepatic steatosis","Hepatitis","Hypertension","Pulmonary hypertension","Seizure disorder"]}],"therapies":[{"id":"mayanmassage","name":"Mayan abdominal massage","kind":"Manual therapy","what":"Non-invasive external massage of the abdomen that repositions abdominal and pelvic organs to relieve pain, increasing blood flow, moving lymph and restoring nerve signalling. Your coursework names dysmenorrhoea, endometriosis, irritable bowel syndrome and infertility as the conditions it may help.","caution":"Requires training in anatomy, physiology and the traditional technique. Avoid over an IUD without training, in pregnancy, and over acute inflammation or a known mass. Self-massage handouts make a good take-home practice.","conditions":["Bloating and gas","Constipation","Dysmenorrhea","Endometriosis","Fertility and preconception","Irritable bowel syndrome","Small intestinal bacterial overgrowth"]},{"id":"sauna","name":"Sauna and induced sweating","kind":"Detoxification","what":"One of the safest routes of elimination — it does not load the liver or kidneys. Any sweating counts: sauna, exercise or a sweatsuit. Start at 5 minutes and build; replete minerals before and after.","caution":"Shower immediately afterwards with Castile soap to prevent reabsorption. Avoid shared or smelly saunas — aerosolised toxins from other users can be absorbed.","conditions":["Mold and mycotoxin illness"]},{"id":"lymphatic","name":"Lymphatic drainage","kind":"Manual therapy","what":"Vibration plates, dry brushing, and the “Big 6” sequence — clavicles, behind the ears, axillae, stomach, back, groin and behind the knees. Done daily in the shower while soaping up.","caution":"Often overlooked; open drainage before mobilising anything.","conditions":["Mold and mycotoxin illness"]},{"id":"binderprotocol","name":"Binder push-pull protocol","kind":"Detoxification","what":"The mould detox base from your lecture: AM/PM push-pull, 5 days on and 2 days off, over 4–6 months before retesting. Start at ¼ teaspoon and increase as tolerated. Keep the binder even if only one dose is taken.","caution":"Do not detox during known ongoing exposure, active colonisation, severe constipation, or extreme sensitivity. Poor tolerance is a signal, not a reason to push.","conditions":["Mold and mycotoxin illness"]},{"id":"remediation","name":"Environmental remediation","kind":"Environmental","what":"Inspection with heat-signature technology by a certified inspector, separate HVAC assessment, and mould dogs where available. HEPA filtration where relocation is not possible. Check crawl spaces, cars, and items brought from a mouldy home.","caution":"Standard mould inspectors are not licensed for HVAC. Belongings can carry the exposure to a new home.","conditions":["Allergic rhinitis","Asthma","Fertility and preconception","Inflammatory bowel disease","Mold and mycotoxin illness","Sinusitis"]},{"id":"sinusrinse","name":"Sinus irrigation and antimicrobial sprays","kind":"Topical","what":"Colloidal silver with herbs (RNA/ACS) first line for up to 12 weeks; xylitol with grapefruit seed extract where biofilm is a factor; compounded antifungal or antibacterial sprays where needed. Reset afterwards with Lactobacillus sakei.","caution":"Treat sinuses last — oral and IV routes do not reliably reach them. Your lecture rates colloidal silver above BEG spray for MARCONS on cost, tolerability and resistance.","conditions":["Candidiasis","Mold and mycotoxin illness","Sinusitis"]},{"id":"cpap","name":"CPAP / BiPAP","kind":"Device","what":"Positive airway pressure — the mainstay for obstructive sleep apnoea, and BiPAP in type 2 respiratory failure.","caution":"Adherence is the whole battle: mask fit, humidification and desensitisation determine success.","conditions":["Central sleep apnea","Obstructive sleep apnea","Respiratory failure and ARDS"]},{"id":"mad","name":"Mandibular advancement device","kind":"Device","what":"Jaw repositioning appliance for mild to moderate obstructive sleep apnoea, or where CPAP is not tolerated.","caution":"Needs a dentist experienced in sleep appliances; can shift the bite over time.","conditions":["Obstructive sleep apnea"]},{"id":"posturaltherapy","name":"Positional therapy","kind":"Lifestyle","what":"Lateral decubitus sleeping improves obstructive sleep apnoea; supine makes it worse.","caution":"Simple, free, and worth trying in every positional apnoea.","conditions":["Obstructive sleep apnea"]},{"id":"uas","name":"Upper airway stimulation","kind":"Procedure","what":"Implanted stimulation of the hypoglossal nerve to advance the tongue base during sleep.","caution":"For selected CPAP-intolerant patients; the hypoglossal nerve is the structure stimulated, not the genioglossus directly.","conditions":["Obstructive sleep apnea"]},{"id":"uppp","name":"Airway surgery","kind":"Procedure","what":"Uvulopalatopharyngoplasty, tonsillectomy or adenoidectomy where anatomy is the obstruction — often the answer in children.","caution":"Adult results are variable; assess anatomy before offering.","conditions":["Obstructive sleep apnea"]},{"id":"o2","name":"Supplemental oxygen","kind":"Device","what":"Long-term oxygen in severe COPD with resting hypoxaemia; acute use in respiratory failure.","caution":"Nasal cannula flow starts around 1 L/min. Use the minimum effective concentration — 60–100% risks oxygen toxicity. SpO2 92% or less needs more advanced care; 88% or less needs the emergency department.","conditions":["COVID-19","Chronic obstructive pulmonary disease","Idiopathic pulmonary fibrosis","Pneumonia","Pulmonary hypertension","Respiratory failure and ARDS"]},{"id":"pulmrehab","name":"Pulmonary rehabilitation","kind":"Rehabilitation","what":"Supervised exercise, breathing retraining and education — one of the few interventions that improves quality of life and admissions in COPD.","caution":"An FEV1/FVC around 40% is too low to start unsupervised exercise; refer to a programme instead.","conditions":["Asthma","Bronchiectasis","Chronic obstructive pulmonary disease","Cystic fibrosis","Idiopathic pulmonary fibrosis","Pneumonia","Pulmonary hypertension","Respiratory failure and ARDS","Sarcoidosis"]},{"id":"breathing","name":"Breathing retraining","kind":"Mind-body","what":"Buteyko, diaphragmatic and pursed-lip breathing for asthma, COPD and anxious hyperventilation.","caution":"Adjunct to, not a replacement for, controller therapy.","conditions":["Asthma","Bronchiectasis","Bronchitis","COVID-19","Chronic obstructive pulmonary disease","Cough","Idiopathic pulmonary fibrosis","Pleural disease","Pneumonia","Respiratory failure and ARDS"]},{"id":"airwayclear","name":"Airway clearance","kind":"Physical therapy","what":"Postural drainage, percussion, oscillating PEP devices and nebulised hypertonic saline to mobilise secretions in bronchiectasis and cystic fibrosis.","caution":"Daily and lifelong in bronchiectasis — the single most important measure.","conditions":["Bronchiectasis","Cystic fibrosis"]},{"id":"smokingcess","name":"Smoking cessation programme","kind":"Lifestyle","what":"Behavioural support with pharmacotherapy — the only intervention that changes the slope of decline in COPD.","caution":"Combine counselling with NRT or varenicline; screen mood before varenicline.","conditions":["Abdominal aortic aneurysm","Atherosclerosis","Bronchitis","Chronic obstructive pulmonary disease","Erectile dysfunction","Idiopathic pulmonary fibrosis","Pulmonary nodules and lung cancer","Raynaud's phenomenon"]},{"id":"cpt_therapy","name":"Cognitive Processing Therapy (CPT)","kind":"Psychotherapy","what":"First-line trauma therapy targeting distorted beliefs and “stuck points” — guilt and shame — after trauma.","caution":"Psychotherapy, not medication, is first-line in PTSD.","conditions":["Post-traumatic stress disorder"]},{"id":"pe_therapy","name":"Prolonged Exposure (PE)","kind":"Psychotherapy","what":"Gradual, repeated imaginal and in vivo exposure to trauma cues to reduce avoidance and allow habituation.","caution":"Benzodiazepines interfere with the extinction learning this depends on.","conditions":["Post-traumatic stress disorder"]},{"id":"emdr","name":"EMDR","kind":"Psychotherapy","what":"Bilateral stimulation, such as guided eye movements, while recalling the trauma, to reprocess and integrate fragmented memories.","caution":"First-line for PTSD alongside CPT and PE.","conditions":["Post-traumatic stress disorder"]},{"id":"cbt","name":"Cognitive behavioural therapy","kind":"Psychotherapy","what":"First-line psychological treatment for depression, anxiety, insomnia (CBT-I) and chronic pain.","caution":"CBT-I outperforms hypnotics for chronic insomnia and its gains last.","conditions":["Adjustment disorder","Anxiety","Attention deficit disorder","Back pain","Bipolar disorder","Chronic pain","Depression","Endometriosis","Fibromyalgia","Insomnia","Interstitial cystitis","Irritable bowel syndrome","Menopause","Obesity","Premenstrual syndrome"]},{"id":"mindfulness","name":"Mindfulness and yoga","kind":"Mind-body","what":"Manages hyperarousal by engaging the parasympathetic nervous system and vagal tone, and downregulating the amygdala.","caution":"Trauma-informed instruction matters — body-focused practice can be activating early in PTSD.","conditions":["Adjustment disorder","Anxiety","Autoimmune conditions","Chronic pain","Fibromyalgia","Gastritis","Herpes simplex","Hyperthyroidism","Inflammatory bowel disease","Interstitial cystitis","Irritable bowel syndrome","Multiple sclerosis","Post-traumatic stress disorder","Prostatitis","Psoriasis"]},{"id":"medi_diet","name":"Anti-inflammatory / Mediterranean diet","kind":"Nutrition","what":"Whole foods, vegetables and fruit, whole grains, lean protein, olive oil, avocado and fatty fish. Lowers the pro-inflammatory cytokines raised in depression and bipolar disorder.","caution":"The dietary pattern with the broadest evidence across the conditions in this index.","conditions":["Acne","Amenorrhea","Anemia, iron deficiency","Atherosclerosis","Autoimmune conditions","Bipolar disorder","Burns","Celiac disease","Chronic fatigue syndrome","Chronic kidney disease","Cognitive decline","Congestive heart failure","Constipation","Depression","Diabetes mellitus, type 2","Diarrhea","Erectile dysfunction","Fatigue and low energy","Fertility and preconception","Food intolerance","Gallstones","Gastritis","Gingivitis","Gout","Hemorrhoids","Hepatic steatosis","Hepatitis","Hypertension","Hypothyroidism","Inflammatory bowel disease","Kidney stones","Lactation support","Menopause","Mold and mycotoxin illness","Multiple sclerosis","Obesity","Osteoporosis","Parasites, intestinal","Parkinson's disease","Polycystic ovary syndrome","Premenstrual syndrome","Psoriasis","Rheumatoid arthritis","Wound healing"]},{"id":"elimdiet","name":"Elimination diet","kind":"Nutrition","what":"Structured removal and reintroduction to identify food triggers; your mental health notes name gluten and wheat specifically for anxiety and depression.","caution":"Time-limited and supervised — indefinite restriction causes its own harm.","conditions":["Allergic rhinitis","Anxiety","Asthma","Attention deficit disorder","Autoimmune conditions","Bloating and gas","Candidiasis","Celiac disease","Diarrhea","Dyspepsia","Eczema","Endometriosis","Food intolerance","GERD","Gastritis","Inflammatory bowel disease","Interstitial cystitis","Irritable bowel syndrome","Migraine","Parasites, intestinal","Seizure disorder","Small intestinal bacterial overgrowth"]},{"id":"glycemic","name":"Blood sugar stabilisation","kind":"Nutrition","what":"Removing refined sugar and eating regularly. Panic attacks arriving before meals point at blood glucose rather than at anxiety.","caution":"Ask about meal timing before escalating an anxiolytic.","conditions":["Acne","Anxiety","Attention deficit disorder","Candidiasis","Diabetes mellitus, type 2","Dyspepsia","Fatigue and low energy","Hepatic steatosis","Migraine","Nausea and vomiting","Polycystic ovary syndrome","Premenstrual syndrome"]},{"id":"caffeine_cut","name":"Caffeine reduction","kind":"Lifestyle","what":"Caffeine directly raises anxiety, disturbs sleep and can destabilise mood.","caution":"Taper rather than stop abruptly to avoid withdrawal headache.","conditions":["Anxiety","Atrial fibrillation","Insomnia","Premenstrual syndrome","Urinary incontinence"]},{"id":"sleephyg","name":"Sleep hygiene and circadian work","kind":"Lifestyle","what":"Fixed wake time, morning daylight, evening light restriction, and a wind-down routine.","caution":"Fixing the wake time matters more than fixing the bedtime.","conditions":["Attention deficit disorder","Autoimmune conditions","Bipolar disorder","COVID-19","Chronic fatigue syndrome","Cognitive decline","Common cold","Depression","Dyspepsia","Fatigue and low energy","Fibromyalgia","GERD","Herpes simplex","Hypertension","Hypothyroidism","Influenza","Insomnia","Menopause","Migraine","Obesity","Seizure disorder","Sore throat"]},{"id":"pelvicfloor","name":"Pelvic floor therapy","kind":"Physical therapy","what":"Relaxes and strengthens the muscles and ligaments of the pelvic floor in men and women to reduce pain and the symptoms that follow conditions such as the postpartum period. Your reflection names urinary incontinence and frequency in male patients, endometriosis and chronic pelvic pain in female patients, and constipation among the digestive complaints it helps. Supervised training beats unguided Kegels.","caution":"An overactive pelvic floor needs downtraining, not strengthening; assess before prescribing exercises.","conditions":["Constipation","Endometriosis","Interstitial cystitis","Prostatitis","Sexually transmitted infection","Urinary incontinence","Urinary tract infection"]},{"id":"diaphbreath","name":"Diaphragmatic breathing","kind":"Mind-body","what":"Breathing with awareness of how the belly moves on the inhale and exhale. It reduces stress, builds awareness around breathing, and improves circulation to the abdomen and pelvis. To teach it: have the patient find a quiet place, sit or lie down, and rest one hand on the chest and one on the abdomen; a slow deep breath in as the belly inflates, then a slow exhale as the belly relaxes and flattens.","caution":"The foundation of pelvic floor work — an overactive floor will not release while the breath is held high in the chest.","conditions":["Anxiety","Asthma","Constipation","Endometriosis","Interstitial cystitis","Prostatitis","Urinary incontinence"]},{"id":"exercise","name":"Structured exercise","kind":"Lifestyle","what":"Aerobic and resistance work — first-line or co-equal in depression, type 2 diabetes, hypertension, osteoporosis, chronic pain and fatigue.","caution":"Start below capacity in post-exertional malaise; graded exercise can harm in ME/CFS.","conditions":["Abdominal aortic aneurysm","Adjustment disorder","Amenorrhea","Anxiety","Asthma","Atherosclerosis","Atrial fibrillation","Attention deficit disorder","Back pain","Benign prostatic hyperplasia","Bipolar disorder","Bloating and gas","Chronic kidney disease","Chronic obstructive pulmonary disease","Chronic pain","Cognitive decline","Congestive heart failure","Constipation","Cystic fibrosis","Deep vein thrombosis","Depression","Diabetes mellitus, type 2","Dysmenorrhea","Edema","Erectile dysfunction","Fatigue and low energy","Fibromyalgia","Gout","Hemorrhoids","Hepatic steatosis","Hepatitis","Hypertension","Hypothyroidism","Insomnia","Irritable bowel syndrome","Kidney stones","Menopause","Migraine","Multiple sclerosis","Neck and shoulder pain","Obesity","Obstructive sleep apnea","Osteoarthritis","Osteoporosis","Parkinson's disease","Polycystic ovary syndrome","Post-traumatic stress disorder","Premenstrual syndrome","Pulmonary embolism","Pulmonary hypertension","Pulmonary nodules and lung cancer","Raynaud's phenomenon","Rheumatoid arthritis","Sarcoidosis","Small intestinal bacterial overgrowth","Statin-associated muscle symptoms","Urinary incontinence","Varicose veins"]},{"id":"weightmgmt","name":"Weight management","kind":"Lifestyle","what":"The most effective single measure in obstructive sleep apnoea, type 2 diabetes, knee osteoarthritis and fatty liver.","caution":"Obesity is the most common risk factor for obstructive sleep apnoea.","conditions":["Atherosclerosis","Atrial fibrillation","Benign prostatic hyperplasia","Central sleep apnea","Chronic kidney disease","Congestive heart failure","Diabetes mellitus, type 2","Edema","Erectile dysfunction","Fertility and preconception","GERD","Gallstones","Gout","Hepatic steatosis","Hepatitis","Hypertension","Obesity","Obstructive sleep apnea","Osteoarthritis","Osteoporosis","Polycystic ovary syndrome","Psoriasis","Urinary incontinence","Varicose veins"]},{"id":"physio","name":"Physical therapy and manual medicine","kind":"Physical therapy","what":"Graded loading, manipulation and mobilisation for back, neck and joint pain.","caution":"Imaging first only where red flags are present.","conditions":["Back pain","Chronic pain","Multiple sclerosis","Neck and shoulder pain","Osteoarthritis","Parkinson's disease","Pleural disease","Rheumatoid arthritis","Vertigo"]},{"id":"hydrotherapy","name":"Constitutional hydrotherapy","kind":"Physical medicine","what":"Alternating hot and cold applications to modulate circulation, immune function and vagal tone.","caution":"Avoid extremes in cardiovascular instability and neuropathy.","conditions":["Back pain","Burns","Chronic pain","Dysmenorrhea","Fibromyalgia","Neck and shoulder pain","Osteoarthritis","Rheumatoid arthritis","Vertigo","Wound healing"]},{"id":"acupuncture","name":"Acupuncture","kind":"Physical medicine","what":"Evidence in chronic pain, migraine prophylaxis, chemotherapy-induced nausea and hot flushes.","caution":"Choose a practitioner using single-use needles and clean technique.","conditions":["Back pain","Chronic pain","Dysmenorrhea","Endometriosis","Fibromyalgia","Menopause","Migraine","Nausea and vomiting","Neck and shoulder pain","Osteoarthritis"]},{"id":"phototherapy","name":"Light therapy","kind":"Device","what":"10,000 lux for 20–30 minutes on waking in seasonal and non-seasonal depression and circadian disorder.","caution":"Can trigger mania in bipolar disorder — introduce carefully and monitor.","conditions":["Depression"]},{"id":"nasalrinse","name":"Saline nasal irrigation","kind":"Topical","what":"High-volume, low-pressure rinsing for sinusitis and allergic rhinitis — one of the highest-yield simple measures.","caution":"Distilled or previously boiled water only, never straight from the tap.","conditions":["Allergic rhinitis","Common cold","Cough","Otitis media","Sinusitis"]},{"id":"steam","name":"Steam inhalation and humidification","kind":"Physical medicine","what":"Loosens secretions and eases upper airway irritation.","caution":"Scald risk, especially with children.","conditions":["Bronchitis","Common cold","Cough","Influenza","Otitis media","Pneumonia","Sinusitis","Sore throat"]},{"id":"compression","name":"Compression therapy","kind":"Device","what":"Graduated compression stockings for varicose veins, venous insufficiency and oedema.","caution":"Check the ankle-brachial index before compressing a limb with suspected arterial disease.","conditions":["Deep vein thrombosis","Edema","Pulmonary embolism","Varicose veins"]},{"id":"sitzbath","name":"Sitz baths and topical care","kind":"Physical medicine","what":"Warm sitz baths for haemorrhoids, fissure and post-partum perineal pain.","caution":"Pat dry; avoid prolonged soaking.","conditions":["Hemorrhoids","Prostatitis","Urinary tract infection"]},{"id":"dermcare","name":"Barrier skin care","kind":"Topical","what":"Emollients, lukewarm short showers, soap substitutes — the base every eczema regimen is built on.","caution":"Apply within minutes of bathing to trap moisture.","conditions":["Acne","Burns","Conjunctivitis","Eczema","Psoriasis","Warts","Wound healing"]},{"id":"wetwrap","name":"Wet wrap therapy","kind":"Topical","what":"Damp occlusive layers over emollient or topical steroid for severe eczema flares.","caution":"Short courses under guidance.","conditions":["Eczema"]},{"id":"uvb","name":"Narrowband UVB phototherapy","kind":"Device","what":"Moderate to severe psoriasis and refractory eczema.","caution":"Cumulative dose and skin cancer risk are tracked.","conditions":["Eczema","Psoriasis"]},{"id":"counselling","name":"Counselling and psychosocial support","kind":"Psychotherapy","what":"Adjustment disorder, grief, chronic illness adaptation, and the psychosocial layer of every chronic condition.","caution":"Adjustment disorder resolves within six months of the stressor ending — that timeline is the diagnosis.","conditions":["Adjustment disorder","Amenorrhea","Attention deficit disorder","Bipolar disorder","Celiac disease","Chronic fatigue syndrome","Depression","Erectile dysfunction","Fatigue and low energy","Fertility and preconception","Hyperthyroidism","Lactation support","Mold and mycotoxin illness","Multiple sclerosis","Parkinson's disease","Polycystic ovary syndrome","Pulmonary nodules and lung cancer","Seizure disorder","Sexually transmitted infection","Tuberculosis"]},{"id":"groupsupport","name":"Peer and group support","kind":"Psychosocial","what":"Chronic illness, addiction and caregiver burden.","caution":"Complements rather than replaces individual care.","conditions":["Adjustment disorder","Cognitive decline","Lactation support","Parkinson's disease","Pulmonary nodules and lung cancer"]},{"id":"vagal","name":"Vagal tone work","kind":"Mind-body","what":"Slow paced breathing, humming, cold exposure and heart rate variability training.","caution":"The mechanism behind much of the benefit of yoga and mindfulness in hyperarousal.","conditions":["Anxiety","Chronic fatigue syndrome","Hypertension","Insomnia","Post-traumatic stress disorder","Raynaud's phenomenon","Vertigo"]}],"labs":[{"id":"cbc","name":"CBC with differential","kind":"blood","why":"The first-line screen in fatigue, infection, bleeding and before most drug therapy.","interpret":"Microcytic anaemia points at iron deficiency or thalassaemia; macrocytic at B12, folate, alcohol or hypothyroidism. Neutrophilia suggests bacterial infection, lymphocytosis viral, eosinophilia atopy or parasites.","conditions":["Allergic rhinitis","Amenorrhea","Anemia, iron deficiency","Anxiety","Atrial fibrillation","Attention deficit disorder","Autoimmune conditions","Bipolar disorder","Bronchiectasis","Burns","COVID-19","Celiac disease","Chronic fatigue syndrome","Chronic kidney disease","Cognitive decline","Congestive heart failure","Constipation","Cystic fibrosis","Deep vein thrombosis","Depression","Diarrhea","Dysmenorrhea","Dyspepsia","Eczema","Endometriosis","Fatigue and low energy","Fibromyalgia","GERD","Gallstones","Gastritis","Gingivitis","Gout","Hemorrhoids","Hepatic steatosis","Hepatitis","Herpes simplex","Hyperthyroidism","Hypothyroidism","Inflammatory bowel disease","Influenza","Irritable bowel syndrome","Lactation support","Migraine","Mold and mycotoxin illness","Multiple sclerosis","Nausea and vomiting","Osteoporosis","Otitis media","Parasites, intestinal","Parkinson's disease","Pleural disease","Pneumonia","Post-traumatic stress disorder","Premenstrual syndrome","Pulmonary nodules and lung cancer","Raynaud's phenomenon","Respiratory failure and ARDS","Rheumatoid arthritis","Sarcoidosis","Seizure disorder","Sinusitis","Small intestinal bacterial overgrowth","Sore throat","Tuberculosis","Vertigo","Wound healing"]},{"id":"cmp","name":"Comprehensive metabolic panel","kind":"blood","why":"Electrolytes, glucose, renal and liver function — baseline before and during most drug therapy.","interpret":"Hyponatraemia raises Legionella, SIADH and paraneoplastic syndromes. A reversed albumin/globulin ratio appears in sarcoidosis.","conditions":["Anxiety","Atrial fibrillation","Autoimmune conditions","Bipolar disorder","Burns","COVID-19","Celiac disease","Chronic fatigue syndrome","Chronic kidney disease","Cognitive decline","Congestive heart failure","Constipation","Deep vein thrombosis","Depression","Diabetes mellitus, type 2","Diarrhea","Edema","Erectile dysfunction","Fatigue and low energy","Gallstones","Gout","Hepatitis","Hypertension","Inflammatory bowel disease","Kidney stones","Mold and mycotoxin illness","Multiple sclerosis","Nausea and vomiting","Osteoporosis","Parkinson's disease","Pneumonia","Pulmonary nodules and lung cancer","Respiratory failure and ARDS","Rheumatoid arthritis","Sarcoidosis","Seizure disorder","Tuberculosis","Vertigo","Wound healing"]},{"id":"tsh","name":"TSH with free T4","kind":"blood","why":"Any fatigue, weight change, mood change, menstrual disturbance, constipation or hair loss — and mandatory before attributing psychiatric symptoms to a primary psychiatric cause.","interpret":"High TSH with low free T4 is primary hypothyroidism; suppressed TSH with high free T4 is hyperthyroidism.","conditions":["Amenorrhea","Anxiety","Atrial fibrillation","Attention deficit disorder","Bipolar disorder","Bloating and gas","Chronic fatigue syndrome","Chronic pain","Cognitive decline","Congestive heart failure","Constipation","Depression","Erectile dysfunction","Fatigue and low energy","Fertility and preconception","Fibromyalgia","Hyperthyroidism","Hypothyroidism","Insomnia","Lactation support","Menopause","Migraine","Obesity","Osteoporosis","Parkinson's disease","Polycystic ovary syndrome","Post-traumatic stress disorder","Premenstrual syndrome","Raynaud's phenomenon","Small intestinal bacterial overgrowth","Statin-associated muscle symptoms"]},{"id":"thyroidab","name":"Thyroid antibodies (TPO, TG)","kind":"blood","why":"Distinguishing autoimmune thyroid disease from other causes.","interpret":"Positive TPO indicates Hashimoto's or Graves' autoimmunity.","conditions":["Autoimmune conditions","Fertility and preconception","Hyperthyroidism","Hypothyroidism"]},{"id":"t3rt3","name":"Free T3 and reverse T3","kind":"blood","why":"Conversion problems and persistent symptoms on adequate levothyroxine.","interpret":"High reverse T3 with low free T3 suggests impaired conversion under stress or illness.","conditions":["Hypothyroidism"]},{"id":"ferritin","name":"Ferritin with iron studies","kind":"blood","why":"Fatigue, hair loss, restless legs, heavy periods, and before iron supplementation.","interpret":"Ferritin under 30 ng/mL is deficiency even with a normal haemoglobin; it is an acute-phase reactant, so read it alongside CRP. Under 50 is often symptomatic in restless legs and hair loss.","conditions":["Anemia, iron deficiency","Attention deficit disorder","Celiac disease","Chronic fatigue syndrome","Chronic pain","Depression","Dysmenorrhea","Fatigue and low energy","Fibromyalgia","Hypothyroidism","Inflammatory bowel disease","Insomnia","Lactation support","Migraine","Premenstrual syndrome","Wound healing"]},{"id":"b12folate","name":"B12, folate and methylmalonic acid","kind":"blood","why":"Fatigue, neuropathy, cognitive change, macrocytosis, and anyone on metformin or a long-term PPI.","interpret":"Methylmalonic acid confirms functional B12 deficiency when serum B12 sits in the low-normal grey zone.","conditions":["Attention deficit disorder","Celiac disease","Chronic fatigue syndrome","Cognitive decline","Depression","Diabetes mellitus, type 2","Fatigue and low energy","Hypothyroidism","Multiple sclerosis","Parkinson's disease","Vertigo"]},{"id":"vitdlab","name":"25-hydroxyvitamin D","kind":"blood","why":"Fatigue, mood, bone health, autoimmune and respiratory conditions; sleep apnoea severity tracks with deficiency.","interpret":"25-hydroxy is the storage form to measure. Elevated 1,25-dihydroxy in someone not supplementing suggests granulomatous disease such as sarcoidosis.","conditions":["Attention deficit disorder","Autoimmune conditions","Celiac disease","Chronic fatigue syndrome","Chronic pain","Cognitive decline","Depression","Diabetes mellitus, type 2","Fatigue and low energy","Fibromyalgia","Lactation support","Multiple sclerosis","Osteoporosis","Sarcoidosis","Statin-associated muscle symptoms"]},{"id":"lipids","name":"Lipid panel","kind":"blood","why":"Cardiovascular risk assessment.","interpret":"Cholesterol that will not respond to diet and lifestyle may have an environmental toxicant component — one of the flags in your mould lecture.","conditions":["Abdominal aortic aneurysm","Atherosclerosis","Bipolar disorder","Diabetes mellitus, type 2","Erectile dysfunction","Gout","Hepatic steatosis","Hypertension","Hypothyroidism","Menopause","Obesity","Polycystic ovary syndrome","Psoriasis"]},{"id":"a1c","name":"HbA1c","kind":"blood","why":"Diagnosis and monitoring of type 2 diabetes; screening in obesity, PCOS and metabolic syndrome.","interpret":"5.7–6.4% is prediabetes, 6.5% or above is diabetes. Falsely low with shortened red cell survival.","conditions":["Acne","Atherosclerosis","Candidiasis","Chronic kidney disease","Diabetes mellitus, type 2","Erectile dysfunction","Fatigue and low energy","Fertility and preconception","Gingivitis","Gout","Hepatic steatosis","Hypertension","Menopause","Obesity","Obstructive sleep apnea","Polycystic ovary syndrome","Psoriasis","Urinary tract infection","Wound healing"]},{"id":"fastingins","name":"Fasting insulin and glucose (HOMA-IR)","kind":"blood","why":"Insulin resistance before HbA1c moves — PCOS, metabolic syndrome, fatty liver.","interpret":"Raised fasting insulin with normal glucose is early insulin resistance.","conditions":["Diabetes mellitus, type 2","Hepatic steatosis","Obesity","Polycystic ovary syndrome"]},{"id":"crp","name":"hs-CRP and ESR","kind":"blood","why":"Inflammatory burden; monitoring autoimmune and infectious disease.","interpret":"Very high ESR with headache and jaw claudication in an older patient means giant cell arteritis until excluded.","conditions":["Atherosclerosis","Autoimmune conditions","Back pain","COVID-19","Chronic pain","Endometriosis","Fibromyalgia","Inflammatory bowel disease","Neck and shoulder pain","Osteoarthritis","Pleural disease","Psoriasis","Raynaud's phenomenon","Rheumatoid arthritis","Sarcoidosis"]},{"id":"procalcitonin","name":"Procalcitonin","kind":"blood","why":"Separating bacterial from viral lower respiratory infection and guiding antibiotic decisions.","interpret":"Rises in typical bacterial pneumonia; stays low in viral pneumonia and in the atypicals — Legionella, Chlamydia, Mycoplasma and Bordetella.","conditions":["Bronchitis","Pneumonia"]},{"id":"ddimer","name":"D-dimer","kind":"blood","why":"The first diagnostic step in suspected pulmonary embolism of LOW clinical likelihood.","interpret":"A negative result in a low-probability patient excludes PE. It is non-specific — a positive result needs CT angiography.","conditions":["COVID-19","Deep vein thrombosis","Pulmonary embolism"]},{"id":"abg","name":"Arterial blood gases","kind":"blood","why":"Respiratory failure, severe exacerbation, and assessing ventilation.","interpret":"Type 1 failure is low oxygen with normal or low CO2; type 2 adds CO2 retention. PE classically gives low O2 with low CO2 from hyperventilation.","conditions":["Central sleep apnea","Chronic obstructive pulmonary disease","Idiopathic pulmonary fibrosis","Pneumonia","Pulmonary embolism","Respiratory failure and ARDS"]},{"id":"bnp","name":"BNP / NT-proBNP","kind":"blood","why":"Separating cardiac from pulmonary causes of breathlessness; heart failure diagnosis and monitoring.","interpret":"A normal value makes untreated heart failure unlikely.","conditions":["Central sleep apnea","Congestive heart failure","Edema","Pulmonary embolism","Pulmonary hypertension"]},{"id":"trop","name":"Troponin","kind":"blood","why":"Suspected acute coronary syndrome.","interpret":"Serial measurement; any rise with chest pain is an emergency.","conditions":["Pulmonary embolism"]},{"id":"aat","name":"Alpha-1 antitrypsin","kind":"blood","why":"COPD in a young patient, a non-smoker, or with a family history.","interpret":"Low levels allow unopposed elastase to destroy elastin — the mechanism of early emphysema.","conditions":["Chronic obstructive pulmonary disease"]},{"id":"ige","name":"Total and specific IgE, or skin prick testing","kind":"specialty","why":"Identifying allergic triggers in asthma, rhinitis and eczema.","interpret":"Guides both avoidance and biologic selection in severe asthma.","conditions":["Allergic rhinitis","Asthma","Eczema","Food intolerance","Sinusitis"]},{"id":"eos","name":"Blood eosinophil count","kind":"blood","why":"Phenotyping asthma and COPD — it decides who benefits from an inhaled corticosteroid or an anti-IL5 biologic.","interpret":"Read from the CBC differential.","conditions":["Allergic rhinitis","Asthma","Chronic obstructive pulmonary disease"]},{"id":"ana","name":"ANA with extractable antigens","kind":"blood","why":"Screening for systemic autoimmune disease when there are multi-system features.","interpret":"A positive ANA alone is common and non-diagnostic; the pattern, titre and specific antibodies carry the meaning.","conditions":["Autoimmune conditions","Multiple sclerosis","Psoriasis","Raynaud's phenomenon","Rheumatoid arthritis"]},{"id":"rf_ccp","name":"Rheumatoid factor and anti-CCP","kind":"blood","why":"Suspected rheumatoid arthritis.","interpret":"Anti-CCP is the more specific and predicts erosive disease.","conditions":["Rheumatoid arthritis"]},{"id":"urate","name":"Serum urate","kind":"blood","why":"Gout diagnosis and urate-lowering targets.","interpret":"Can be normal during an acute flare — recheck two weeks later. Target under 6 mg/dL, or under 5 with tophi.","conditions":["Gout","Kidney stones","Osteoarthritis"]},{"id":"ck","name":"Creatine kinase","kind":"blood","why":"Muscle pain on a statin, and myopathy.","interpret":"Marked elevation with weakness needs the statin stopped.","conditions":["Statin-associated muscle symptoms"]},{"id":"lft","name":"Liver enzymes and bilirubin","kind":"blood","why":"Hepatitis, fatty liver, and monitoring hepatotoxic drugs and botanicals.","interpret":"An ALT above AST suggests fatty liver; AST above ALT in a 2:1 ratio suggests alcohol.","conditions":["Gallstones","Hepatic steatosis","Hepatitis","Hyperthyroidism","Obesity","Psoriasis","Statin-associated muscle symptoms"]},{"id":"hepser","name":"Viral hepatitis serology","kind":"blood","why":"Suspected or confirmed hepatitis; before immunosuppression.","interpret":"Hepatitis B must be excluded before starting a biologic.","conditions":["Chronic fatigue syndrome","Hepatic steatosis","Hepatitis","Rheumatoid arthritis"]},{"id":"hpylori_t","name":"H. pylori testing","kind":"specialty","why":"Dyspepsia, gastritis and ulcer.","interpret":"Urea breath test or stool antigen; stop PPIs two weeks and antibiotics four weeks before testing or it will read falsely negative.","conditions":["Anemia, iron deficiency","Dyspepsia","GERD","Gastritis","Nausea and vomiting"]},{"id":"celiac","name":"Coeliac serology (tTG-IgA with total IgA)","kind":"blood","why":"Iron deficiency, diarrhoea, bloating, unexplained weight loss and fatigue.","interpret":"Must be done while still eating gluten. Total IgA is needed to interpret a negative result.","conditions":["Anemia, iron deficiency","Autoimmune conditions","Bloating and gas","Celiac disease","Diarrhea","Dyspepsia","Food intolerance","Gastritis","Irritable bowel syndrome","Small intestinal bacterial overgrowth"]},{"id":"stoolcx","name":"Stool culture, ova and parasites, PCR panel","kind":"stool","why":"Persistent or bloody diarrhoea, travel history, and suspected parasites.","interpret":"A PCR panel is more sensitive than microscopy; treat on a positive result rather than on suspicion.","conditions":["Diarrhea","Inflammatory bowel disease","Irritable bowel syndrome","Parasites, intestinal"]},{"id":"calpro","name":"Faecal calprotectin","kind":"stool","why":"Separating inflammatory bowel disease from irritable bowel syndrome.","interpret":"A normal value makes IBD unlikely and can spare a colonoscopy.","conditions":["Bloating and gas","Constipation","Diarrhea","Food intolerance","Inflammatory bowel disease","Irritable bowel syndrome","Parasites, intestinal","Small intestinal bacterial overgrowth"]},{"id":"fob","name":"Faecal occult blood / FIT","kind":"stool","why":"Colorectal cancer screening; blood on the rectal glove.","interpret":"A positive result needs colonoscopy, not repeat testing.","conditions":["Anemia, iron deficiency","Hemorrhoids"]},{"id":"gimap","name":"Comprehensive stool analysis","kind":"specialty","why":"Dysbiosis, digestive capacity and inflammation in functional GI presentations.","interpret":"Interpret alongside symptoms; findings are frequently over-read.","conditions":["Bloating and gas","Diarrhea","Food intolerance","Irritable bowel syndrome","Parasites, intestinal","Small intestinal bacterial overgrowth"]},{"id":"sibo","name":"SIBO breath test","kind":"function","why":"Bloating, distension and IBS with a suspected overgrowth.","interpret":"Hydrogen and methane over the test period; methane-positive patients tend toward constipation.","conditions":["Bloating and gas","Food intolerance","Irritable bowel syndrome","Small intestinal bacterial overgrowth"]},{"id":"ua","name":"Urinalysis with microscopy","kind":"urine","why":"Urinary symptoms, flank pain, and as part of any systemic workup.","interpret":"Nitrites and leukocyte esterase point at infection; microhaematuria appears in stones, Legionella and glomerular disease.","conditions":["Benign prostatic hyperplasia","Chronic kidney disease","Diabetes mellitus, type 2","Edema","Hypertension","Interstitial cystitis","Kidney stones","Prostatitis","Sarcoidosis","Sexually transmitted infection","Urinary incontinence","Urinary tract infection"]},{"id":"urineculture","name":"Urine culture and sensitivity","kind":"micro","why":"Recurrent, complicated or treatment-failing urinary infection.","interpret":"Take before starting antibiotics wherever possible.","conditions":["Benign prostatic hyperplasia","Interstitial cystitis","Prostatitis","Sexually transmitted infection","Urinary incontinence","Urinary tract infection"]},{"id":"legionella_ag","name":"Legionella and pneumococcal urinary antigen","kind":"urine","why":"Pneumonia with GI symptoms, hyponatraemia, or exposure to water systems, cooling towers or swamp coolers.","interpret":"The urinary antigen test is what confirms Legionella — the exposure history is the clue that prompts it.","conditions":["Pneumonia"]},{"id":"psa","name":"PSA","kind":"blood","why":"Prostate assessment alongside the digital rectal exam, after a shared decision about screening.","interpret":"A 5-alpha reductase inhibitor halves the value — double it when interpreting. Prostatitis, recent ejaculation and cycling all raise it.","conditions":["Benign prostatic hyperplasia","Prostatitis"]},{"id":"sti","name":"STI testing (NAAT)","kind":"micro","why":"Urethral or cervical discharge, cervical motion tenderness, and new or multiple partners.","interpret":"Gonorrhoea and chlamydia by NAAT; add trichomonas, syphilis serology and HIV as indicated.","conditions":["Herpes simplex","Interstitial cystitis","Prostatitis","Sexually transmitted infection","Sore throat","Urinary tract infection","Warts"]},{"id":"wetmount","name":"Vaginal wet mount and pH","kind":"micro","why":"Discharge, itch and odour.","interpret":"Clue cells for bacterial vaginosis, pseudohyphae for candida, motile organisms for trichomonas.","conditions":["Candidiasis","Sexually transmitted infection"]},{"id":"hormones_f","name":"Female hormone panel","kind":"blood","why":"Irregular cycles, infertility, PCOS and menopause. Timed to the cycle — day 3 for FSH, LH and oestradiol, day 21 for progesterone.","interpret":"An LH:FSH ratio above 2:1 with raised free testosterone supports PCOS. FSH over 25 with amenorrhoea suggests menopause.","conditions":["Acne","Amenorrhea","Anemia, iron deficiency","Dysmenorrhea","Endometriosis","Erectile dysfunction","Fertility and preconception","Menopause","Polycystic ovary syndrome","Premenstrual syndrome"]},{"id":"androgens","name":"Androgen panel","kind":"blood","why":"Hirsutism, acne, alopecia and suspected PCOS.","interpret":"Free testosterone, DHEA-S and 17-OH progesterone to exclude late-onset congenital adrenal hyperplasia.","conditions":["Acne","Amenorrhea","Polycystic ovary syndrome"]},{"id":"prolactin","name":"Prolactin","kind":"blood","why":"Amenorrhoea, galactorrhoea and infertility.","interpret":"Raised levels need a repeat, a medication review, and imaging if persistent.","conditions":["Amenorrhea","Fertility and preconception","Polycystic ovary syndrome"]},{"id":"cortisol","name":"Cortisol rhythm (salivary or dried urine)","kind":"specialty","why":"Fatigue, stress-related presentations and suspected HPA dysregulation.","interpret":"Four-point sampling shows the curve rather than a single value. In PTSD your notes describe high CRH with blunted ACTH and low cortisol.","conditions":["Chronic fatigue syndrome","Fatigue and low energy","Post-traumatic stress disorder"]},{"id":"semen","name":"Semen analysis","kind":"specialty","why":"Male factor in infertility — the first test, before extensive female workup.","interpret":"Repeat after 6–12 weeks before drawing conclusions.","conditions":["Fertility and preconception"]},{"id":"dexa","name":"DEXA bone density","kind":"imaging","why":"Osteoporosis screening and monitoring.","interpret":"T-score at or below −2.5 is osteoporosis; −1.0 to −2.5 is osteopenia.","conditions":["Celiac disease","Hyperthyroidism","Menopause","Osteoporosis"]},{"id":"cxr","name":"Chest X-ray","kind":"imaging","why":"Cough over three weeks, suspected pneumonia, breathlessness, chest trauma, and any abnormal chest exam.","interpret":"Lobar infiltrate confirms pneumonia. In asthma it shows hyperinflation, increased markings and atelectasis in children — patchy infiltration is not typical. It cannot confirm COPD.","conditions":["Asthma","Bronchitis","COVID-19","Chronic obstructive pulmonary disease","Congestive heart failure","Cough","Influenza","Pleural disease","Pneumonia","Pulmonary hypertension","Pulmonary nodules and lung cancer","Respiratory failure and ARDS","Sarcoidosis","Tuberculosis"]},{"id":"chestct","name":"Chest CT","kind":"imaging","why":"Interstitial disease, bronchiectasis, nodules, and characterising anything unclear on plain film.","interpret":"Tram-track, signet-ring and honeycomb signs appear in bronchiectasis and fibrosis; non-caseating granulomas are a histological finding, not a radiological one.","conditions":["Bronchiectasis","Cystic fibrosis","Idiopathic pulmonary fibrosis","Pleural disease","Pulmonary nodules and lung cancer","Sarcoidosis","Tuberculosis"]},{"id":"ctpa","name":"CT pulmonary angiography","kind":"imaging","why":"The imaging study that rules out pulmonary embolism.","interpret":"The definitive test; V/Q scanning is the alternative where contrast or radiation is a problem.","conditions":["Pulmonary embolism","Respiratory failure and ARDS"]},{"id":"spirometry","name":"Spirometry with bronchodilator response","kind":"function","why":"Diagnosing and staging asthma and COPD — spirometry alone confirms COPD, without CT or plain film.","interpret":"An FEV1/FVC ratio at or below 70% indicates obstruction. FEV1 falls with methacholine and rises with albuterol in asthma. Long-standing asthma raises FRC, RV and TLC, but not vital capacity.","conditions":["Asthma","Bronchiectasis","Chronic obstructive pulmonary disease","Cough","Cystic fibrosis","Idiopathic pulmonary fibrosis","Pulmonary hypertension"]},{"id":"peakflow","name":"Peak flow monitoring","kind":"function","why":"Home monitoring of asthma control and treatment response — not a diagnostic test.","interpret":"Track against the patient's own personal best, not a population value.","conditions":["Asthma"]},{"id":"feno","name":"Fractional exhaled nitric oxide (FeNO)","kind":"function","why":"Type 2 airway inflammation; predicting steroid response in asthma.","interpret":"Falls with adherence to inhaled steroids — useful for checking it.","conditions":["Asthma"]},{"id":"psg","name":"Polysomnography","kind":"procedure","why":"The gold standard for diagnosing obstructive sleep apnoea, after a positive screening questionnaire.","interpret":"The Apnea-Hypopnea Index from this study determines severity — not neck circumference or the questionnaire score.","conditions":["Central sleep apnea","Insomnia","Obstructive sleep apnea"]},{"id":"stopbang","name":"STOP-BANG questionnaire","kind":"screen","why":"The first step in suspected sleep apnoea — a clinically relevant score is what supports going on to polysomnography.","interpret":"Snoring, Tiredness, Observed apnoea, Pressure, BMI, Age, Neck, Gender.","conditions":["Atrial fibrillation","Fatigue and low energy","Hypertension","Insomnia","Obesity","Obstructive sleep apnea"]},{"id":"epworth","name":"Epworth Sleepiness Scale","kind":"screen","why":"Quantifying daytime sleepiness and tracking response to treatment.","interpret":"Measures sleepiness, not apnoea — it does not gate polysomnography.","conditions":["Obstructive sleep apnea"]},{"id":"sputum","name":"Sputum Gram stain and culture","kind":"micro","why":"Pneumonia not responding as expected, and suspected resistant or unusual organisms.","interpret":"Red currant-jelly sputum suggests Klebsiella. A foul taste with dullness and absent breath sounds suggests lung abscess.","conditions":["Bronchiectasis","Cystic fibrosis","Pneumonia","Pulmonary nodules and lung cancer","Tuberculosis"]},{"id":"afb","name":"Sputum acid-fast bacilli and TB NAAT","kind":"micro","why":"Chronic cough with haemoptysis, night sweats, weight loss or travel to an endemic area.","interpret":"Microscopy showing acid-fast bacilli is not definitive by itself — culture confirms. A Mantoux reading of 5 mm is positive only in defined high-risk groups.","conditions":["Cough","Pneumonia","Tuberculosis"]},{"id":"sweatcl","name":"Sweat chloride (pilocarpine iontophoresis)","kind":"specialty","why":"Cystic fibrosis — recurrent bronchitis, sinus disease, steatorrhoea and failure to thrive in a child.","interpret":"Elevated sweat sodium, chloride or potassium confirms the diagnosis.","conditions":["Bronchiectasis","Cystic fibrosis"]},{"id":"thoracentesis","name":"Thoracentesis with fluid analysis","kind":"procedure","why":"Characterising a pleural effusion.","interpret":"Transudate points at left-sided heart failure, hypoalbuminaemia or cirrhosis; exudate at pneumonia, malignancy, tuberculosis or embolism.","conditions":["Pleural disease","Pulmonary nodules and lung cancer"]},{"id":"rhc","name":"Right heart catheterisation","kind":"procedure","why":"The gold standard confirming pulmonary artery hypertension.","interpret":"Required before any pulmonary vasodilator — sarcoidosis in particular should not be treated empirically with prostacyclin derivatives.","conditions":["Pulmonary hypertension","Sarcoidosis"]},{"id":"echo","name":"Echocardiogram","kind":"imaging","why":"Murmurs, heart failure, and screening for pulmonary hypertension before catheterisation.","interpret":"Gives ejection fraction, valve function and estimated pulmonary pressures.","conditions":["Atherosclerosis","Atrial fibrillation","Central sleep apnea","Congestive heart failure","Edema","Hypertension","Idiopathic pulmonary fibrosis","Pulmonary hypertension"]},{"id":"ekg","name":"12-lead EKG","kind":"procedure","why":"Chest pain, palpitations, syncope, an irregular pulse, and before starting QT-prolonging drugs.","interpret":"Read in a fixed order: rate, rhythm, QRS, P waves, PR interval, ST segments, delta waves, T waves — the eight-step sequence from your EKG assignment.","conditions":["Abdominal aortic aneurysm","Atherosclerosis","Atrial fibrillation","Congestive heart failure","Hypertension","Hyperthyroidism","Pulmonary embolism","Pulmonary hypertension","Vertigo"]},{"id":"holter","name":"Ambulatory EKG monitoring","kind":"procedure","why":"Intermittent palpitations, syncope and suspected paroxysmal atrial fibrillation.","interpret":"Longer recording raises the yield when symptoms are infrequent.","conditions":["Atrial fibrillation"]},{"id":"abi","name":"Ankle-brachial index","kind":"function","why":"Claudication, absent pulses, non-healing leg ulcer — and before compressing any limb.","interpret":"At or below 0.9 indicates peripheral arterial disease; above 1.3 suggests non-compressible calcified vessels.","conditions":["Atherosclerosis","Edema","Varicose veins","Wound healing"]},{"id":"venous_us","name":"Venous duplex ultrasound","kind":"imaging","why":"Suspected deep vein thrombosis, varicose veins and venous insufficiency.","interpret":"The first-line test for a swollen, tender calf.","conditions":["Deep vein thrombosis","Edema","Pulmonary embolism","Varicose veins"]},{"id":"carotid_us","name":"Carotid ultrasound","kind":"imaging","why":"Carotid bruit, transient ischaemic attack or stroke.","interpret":"Quantifies stenosis and guides intervention.","conditions":["Atherosclerosis"]},{"id":"aaa_us","name":"Abdominal aortic ultrasound","kind":"imaging","why":"A widened or expansile aortic pulsation, and one-time screening in older men who have smoked.","interpret":"Diameter over 3 cm defines an aneurysm.","conditions":["Abdominal aortic aneurysm"]},{"id":"abdo_us","name":"Abdominal ultrasound","kind":"imaging","why":"Right upper quadrant pain, abnormal liver enzymes, suspected gallstones, hepatomegaly and fatty liver.","interpret":"First-line for gallstones and for characterising the liver.","conditions":["Dyspepsia","Gallstones","Hepatic steatosis","Hepatitis","Nausea and vomiting"]},{"id":"renal_us","name":"Renal and bladder ultrasound","kind":"imaging","why":"Stones, obstruction, recurrent infection and post-void residual.","interpret":"Avoids radiation; CT is more sensitive for small stones.","conditions":["Benign prostatic hyperplasia","Chronic kidney disease","Interstitial cystitis","Kidney stones","Prostatitis","Urinary incontinence","Urinary tract infection"]},{"id":"ctabdo","name":"CT abdomen and pelvis","kind":"imaging","why":"Acute abdomen, suspected appendicitis, renal colic and unexplained mass.","interpret":"Non-contrast CT is the standard for renal colic.","conditions":["Kidney stones"]},{"id":"pelvic_us","name":"Pelvic ultrasound (transvaginal)","kind":"imaging","why":"Pelvic pain, abnormal bleeding, adnexal mass, fibroids and PCOS morphology.","interpret":"Polycystic morphology supports but does not by itself make the PCOS diagnosis.","conditions":["Amenorrhea","Dysmenorrhea","Endometriosis","Fertility and preconception","Polycystic ovary syndrome"]},{"id":"mammo","name":"Mammography and breast ultrasound","kind":"imaging","why":"A breast lump, skin or nipple change, and routine screening.","interpret":"Any discrete new lump needs imaging regardless of a reassuring examination.","conditions":["Menopause"]},{"id":"colonoscopy","name":"Colonoscopy","kind":"procedure","why":"Rectal bleeding, a rectal mass, altered bowel habit over 50, a positive FIT, and IBD assessment.","interpret":"The investigation a palpable rectal mass or blood on the glove leads to.","conditions":["Constipation","Hemorrhoids","Inflammatory bowel disease"]},{"id":"egd","name":"Upper endoscopy","kind":"procedure","why":"Alarm dyspepsia — weight loss, dysphagia, anaemia, vomiting, or onset over 50 — and reflux not responding to therapy.","interpret":"Allows biopsy for H. pylori, coeliac disease and Barrett's oesophagus.","conditions":["Celiac disease","Dyspepsia","GERD","Gastritis"]},{"id":"mri_spine","name":"MRI spine","kind":"imaging","why":"Back pain with neurological deficit, suspected cauda equina, or red flags for infection or malignancy.","interpret":"Cauda equina syndrome is an emergency MRI, not a routine request.","conditions":["Back pain","Multiple sclerosis"]},{"id":"xray_joint","name":"Plain radiograph of a joint","kind":"imaging","why":"Trauma, deformity and osteoarthritis assessment.","interpret":"Radiographic change and symptom severity correlate poorly in osteoarthritis.","conditions":["Back pain","Neck and shoulder pain","Osteoarthritis","Rheumatoid arthritis"]},{"id":"mri_joint","name":"MRI of a joint","kind":"imaging","why":"Suspected ligament or meniscal tear, and persistent pain with a normal radiograph.","interpret":"Order when the result would change management.","conditions":["Neck and shoulder pain"]},{"id":"jointasp","name":"Joint aspiration with crystal analysis and culture","kind":"procedure","why":"A hot, swollen, acutely tender joint — the test that separates gout from septic arthritis.","interpret":"Negatively birefringent needle crystals mean gout; a positive Gram stain or culture means septic arthritis and admission.","conditions":["Gout","Osteoarthritis"]},{"id":"skinbiopsy","name":"Skin biopsy","kind":"procedure","why":"Undiagnosed rash, suspicious pigmented lesion, and a non-healing ulcer.","interpret":"The answer for anything atypical or refractory.","conditions":["Burns","Warts","Wound healing"]},{"id":"kohprep","name":"KOH preparation and fungal culture","kind":"micro","why":"Suspected tinea, candida and onychomycosis.","interpret":"Confirm before committing to months of oral antifungal therapy.","conditions":["Candidiasis","Eczema"]},{"id":"mycotoxin","name":"Urine mycotoxin panel","kind":"specialty","why":"Suspected mould illness — the multi-system picture your lecture describes.","interpret":"Vibrant Wellness covers 29 mycotoxins plus total burden and also runs metals and environmental toxicants; Mosaic covers 11; Real Time 16. Pick one company and stay with it so results stay comparable.","conditions":["Attention deficit disorder","Autoimmune conditions","Candidiasis","Chronic fatigue syndrome","Cognitive decline","Eczema","Fertility and preconception","Inflammatory bowel disease","Mold and mycotoxin illness","Seizure disorder","Sinusitis"]},{"id":"oat","name":"Organic Acids Test (OAT)","kind":"specialty","why":"Fungal colonisation, mitochondrial and neurotransmitter markers.","interpret":"Detects Aspergillus and Fusarium colonisation. The arabinose marker suggests candida; high oxalic acid suggests fungal colonisation and can mimic fibromyalgia.","conditions":["Candidiasis","Chronic fatigue syndrome","Chronic pain","Fibromyalgia","Mold and mycotoxin illness"]},{"id":"shoemaker","name":"Shoemaker inflammatory markers","kind":"specialty","why":"Selected mould workup where the result will change the plan.","interpret":"TGF-beta-1 for inflammation and possible current exposure; C4a as a mould exposure marker; C3a for bacterial and Lyme reactivation. Only order labs that give actionable data.","conditions":["Mold and mycotoxin illness"]},{"id":"hladq","name":"HLA-DQ genotyping","kind":"specialty","why":"Genetic susceptibility to mould illness.","interpret":"Identifies patients more sensitive to re-exposure — who may, your lecture notes, actually detect it faster. Interpretation calculators are available online.","conditions":["Cognitive decline","Mold and mycotoxin illness","Seizure disorder"]},{"id":"nasalswab","name":"Nasal swab — bacterial and fungal","kind":"micro","why":"Sinus colonisation, especially in treatment-resistant cases.","interpret":"Always order BOTH components. The fungal side is often the more important and is the one commonly missed.","conditions":["Mold and mycotoxin illness","Sinusitis"]},{"id":"candida_ab","name":"Candida antibodies (IgA, IgG, IgM)","kind":"specialty","why":"Suspected candida overgrowth alongside mould work.","interpret":"Interpret with the OAT arabinose marker and clinical picture.","conditions":["Candidiasis","Mold and mycotoxin illness"]},{"id":"envtest","name":"Home environmental testing","kind":"specialty","why":"Establishing whether the building is the source before any detox is attempted.","interpret":"Self-test swab kits from Real Time Labs and Micrometrics; interpret with the HERTSMI calculator. A certified inspector should use heat-signature technology, and HVAC needs its own specialist.","conditions":["Mold and mycotoxin illness"]},{"id":"heavymetals","name":"Heavy metals and environmental toxicants","kind":"specialty","why":"Chronic multi-system illness, unexplained neurological symptoms and infertility.","interpret":"Your lecture treats metals and mould together — they are detoxed simultaneously.","conditions":["Fertility and preconception","Mold and mycotoxin illness","Parkinson's disease"]},{"id":"phq9","name":"PHQ-9","kind":"screen","why":"Screening for depression and tracking severity over time.","interpret":"5–9 mild, 10–14 moderate, 15–19 moderately severe, 20–27 severe. Item 9 asks about self-harm — never skip it.","conditions":["Adjustment disorder","Depression","Fatigue and low energy","Insomnia","Post-traumatic stress disorder"]},{"id":"gad7","name":"GAD-7","kind":"screen","why":"Screening for generalised anxiety; also useful in panic, social anxiety and PTSD.","interpret":"5–9 mild, 10–14 moderate, 15+ severe. A score of 10 or more is the recommended cutoff for further evaluation.","conditions":["Adjustment disorder","Anxiety","Insomnia","Post-traumatic stress disorder"]},{"id":"mdq","name":"Mood Disorder Questionnaire (MDQ)","kind":"screen","why":"Screening for bipolar disorder — essential before starting an antidepressant.","interpret":"13 questions on symptoms and function. A positive screen means a full evaluation, not a diagnosis.","conditions":["Anxiety","Bipolar disorder","Depression"]},{"id":"utox","name":"Urine toxicology","kind":"urine","why":"Part of the medical workup that rules out substance-related causes of psychiatric presentation.","interpret":"Ordered alongside CBC, TSH and electrolytes before attributing symptoms to a primary psychiatric cause.","conditions":["Anxiety","Bipolar disorder","Cognitive decline","Depression","Post-traumatic stress disorder","Seizure disorder"]},{"id":"mmse","name":"Cognitive screening (MMSE / MoCA)","kind":"screen","why":"Memory complaints and suspected cognitive decline.","interpret":"MoCA is more sensitive to mild impairment; correct for education.","conditions":["Cognitive decline","Parkinson's disease","Seizure disorder","Vertigo"]},{"id":"audit","name":"AUDIT-C and substance screening","kind":"screen","why":"Alcohol and substance use as a driver of mood, sleep, liver and cardiac findings.","interpret":"Brief and well validated; ask everyone.","conditions":["Depression"]},{"id":"bp_home","name":"Home blood pressure monitoring","kind":"function","why":"Confirming hypertension before treating, and excluding white-coat effect.","interpret":"A validated upper-arm device, twice daily for a week, is worth more than a single clinic reading.","conditions":["Abdominal aortic aneurysm","Chronic kidney disease","Erectile dysfunction","Hypertension","Migraine","Obesity","Obstructive sleep apnea","Urinary incontinence"]},{"id":"orthostatic","name":"Orthostatic vitals","kind":"function","why":"Dizziness, syncope, fatigue and suspected dysautonomia.","interpret":"A fall of 20 systolic or 10 diastolic on standing defines orthostatic hypotension.","conditions":["Vertigo"]},{"id":"fet","name":"Forced expiratory time","kind":"function","why":"A bedside screen for airflow obstruction, timed at the trachea.","interpret":"Your respiratory chart sets normal under 5 seconds; most texts call 6 seconds or more a positive test.","conditions":["Cough"]},{"id":"pulseox","name":"Pulse oximetry","kind":"function","why":"Every respiratory presentation.","interpret":"92% or less indicates a need for more advanced care; 88% or less means the emergency department.","conditions":["Asthma","Bronchitis","COVID-19","Chronic obstructive pulmonary disease","Common cold","Cough","Idiopathic pulmonary fibrosis","Influenza","Obstructive sleep apnea","Pneumonia","Respiratory failure and ARDS"]},{"id":"cat_score","name":"COPD Assessment Test (CAT)","kind":"screen","why":"Symptom burden in COPD, used with exacerbation history to place the patient in a treatment group.","interpret":"A score of 33 is very severe and warrants specialist referral.","conditions":["Chronic obstructive pulmonary disease"]},{"id":"crista_q","name":"Mould exposure questionnaire","kind":"screen","why":"Structured intake and documentation where mould illness is suspected.","interpret":"Dr Jill Crista's questionnaire is the one your lecture recommends for documentation and intake.","conditions":["Mold and mycotoxin illness"]}],"byCondition":{"Acne":{"pharm":["topretin","bpo","acne_abx","ocp","mra","isotret"],"supps":["zinc","omega3","vitaminA","dim","probiotic"],"therapies":["medi_diet","glycemic","dermcare"],"labs":["androgens","a1c","hormones_f"],"note":"Persistent adult acne with irregular cycles and hirsutism should be worked up as PCOS rather than treated as skin alone.","protocol":"acne-vulgaris"},"Allergic rhinitis":{"pharm":["inasal","antihist2","ltra","decong"],"supps":["quercetin","vitc","probiotic","bromelain","vitd"],"therapies":["nasalrinse","elimdiet","remediation"],"labs":["ige","eos","cbc"],"note":"Intranasal corticosteroid outperforms an oral antihistamine for persistent symptoms; saline rinsing is the highest-yield non-drug measure.","protocol":"allergies"},"Amenorrhea":{"pharm":["ocp","progestin","ovulation"],"supps":["vitex","iron","vitd","inositol","maca"],"therapies":["medi_diet","counselling","exercise"],"labs":["hormones_f","prolactin","tsh","androgens","pelvic_us","cbc"],"note":"Exclude pregnancy first, then separate hypothalamic (low energy availability, over-exercise) from PCOS and from prolactinoma."},"Anemia, iron deficiency":{"pharm":[],"supps":["iron","vitc","b12","folate"],"therapies":["medi_diet"],"labs":["cbc","ferritin","celiac","fob","hpylori_t","hormones_f"],"note":"Iron deficiency in an adult is a symptom, not a diagnosis — find the bleeding source. In men and post-menopausal women that means investigating the gut."},"Anxiety":{"pharm":["ssri","snri","buspirone","benzo","antihist1","hydroxyzine"],"supps":["magglyc","ltheanine","ashwagandha","lavender","cbd","chamomile","passionflower","bcomplex","omega3","phosphatidyl"],"therapies":["cbt","mindfulness","glycemic","caffeine_cut","exercise","vagal","elimdiet","diaphbreath"],"labs":["gad7","tsh","cbc","cmp","utox","mdq"],"note":"Panic before meals points at blood glucose rather than at anxiety. Screen with the MDQ before any antidepressant — an unrecognised bipolar patient can be flipped into mania.","protocol":"generalized-anxiety-disorder"},"Asthma":{"pharm":["ics","saba","laba","icslaba","ltra","lama","sysster","biologic_resp","theoph"],"supps":["magglyc","vitd","quercetin","omega3","boswellia","nac"],"therapies":["breathing","pulmrehab","remediation","elimdiet","exercise","diaphbreath"],"labs":["spirometry","peakflow","feno","eos","ige","cxr","pulseox"],"note":"An inhaled corticosteroid belongs to every patient with persistent asthma; a LABA is never given alone. In an acute attack, wheeze that quietens is the airway closing, not improving."},"Atherosclerosis":{"pharm":["statin","aspirin","acei","bblocker","nitrate"],"supps":["omega3","coq10","garlic","berberine","vitk2","nattokinase"],"therapies":["medi_diet","exercise","smokingcess","weightmgmt"],"labs":["lipids","a1c","crp","ekg","carotid_us","abi","echo"],"note":"Cholesterol that will not shift with diet and lifestyle may have an environmental toxicant component — one of the flags from your mould lecture.","protocol":"coronary-artery-disease"},"Autoimmune conditions":{"pharm":["dmard","sysster","biologic_imm","naltrexone_ld"],"supps":["vitd","omega3","curcumin","glutamine","probiotic","selenium"],"therapies":["elimdiet","medi_diet","mindfulness","sleephyg"],"labs":["ana","crp","cbc","cmp","vitdlab","thyroidab","celiac","mycotoxin"],"note":"Always consider mould and toxicant burden in autoimmunity that resists treatment; screen for latent TB and hepatitis B before any biologic."},"Back pain":{"pharm":["nsaid","acetamin","musclerelax","gabapentinoid"],"supps":["curcumin","magglyc","vitd","boswellia"],"therapies":["physio","exercise","acupuncture","cbt","hydrotherapy"],"labs":["mri_spine","xray_joint","crp"],"note":"Image only for red flags: saddle anaesthesia, bladder or bowel change and bilateral weakness mean cauda equina and an emergency MRI; fever, night pain and weight loss mean infection or malignancy."},"Benign prostatic hyperplasia":{"pharm":["alphablock","fivear","oab"],"supps":["saw","betasito","lycopene","zinc"],"therapies":["weightmgmt","exercise"],"labs":["psa","ua","renal_us","urineculture"],"note":"A 5-alpha reductase inhibitor halves the PSA — double the measured value when interpreting. A hard or nodular prostate on the rectal exam changes the question entirely.","protocol":"benign-prostatic-hyperplasia-bph"},"Bloating and gas":{"pharm":["rifax","antispas","prokin","loperamide"],"supps":["digenzyme","pepomint","probiotic","betaine","glutamine","psyllium"],"therapies":["elimdiet","mayanmassage","exercise"],"labs":["sibo","celiac","calpro","gimap","tsh"],"note":"Your Mayan abdominal massage coursework names gastrointestinal and pelvic pain among its indications; it is a reasonable adjunct once obstruction and mass are excluded."},"Bronchitis":{"pharm":["saba","muco","abx_resp","antihist1"],"supps":["nac","elderberry","propolis","vitc","zinc","garlic"],"therapies":["steam","breathing","smokingcess"],"labs":["cxr","pulseox","procalcitonin"],"note":"Acute bronchitis is a clinical diagnosis — no test confirms it, and antibiotics belong only where you genuinely suspect bacterial infection or co-infection."},"Candidiasis":{"pharm":["antifungal"],"supps":["sboulardii","probiotic","biocidin","berberine","garlic","zinc"],"therapies":["glycemic","elimdiet","sinusrinse"],"labs":["kohprep","wetmount","oat","candida_ab","a1c","mycotoxin"],"note":"Treatment-resistant candida is one of the presentations your mould lecture says should always prompt a mycotoxin workup; the OAT arabinose marker links the two."},"Chronic fatigue syndrome":{"pharm":["naltrexone_ld","ssri"],"supps":["coq10","dribose","carnitine","bcomplex","magglyc","vitd","iron","adaptogen_blend","nadh","rhodiola","astragalus","mushroom","phosphatidyl"],"therapies":["sleephyg","counselling","medi_diet","vagal"],"labs":["cbc","cmp","tsh","ferritin","b12folate","vitdlab","cortisol","mycotoxin","oat","hepser"],"note":"Pace rather than push — graded exercise can worsen post-exertional malaise. Brain fog with chronic fatigue and multiple systems involved is the pattern your mould lecture asks you to test for."},"Chronic kidney disease":{"pharm":["acei","arb","sglt2","loop"],"supps":["omega3","vitd","iron"],"therapies":["medi_diet","exercise","weightmgmt"],"labs":["cmp","ua","cbc","a1c","renal_us","bp_home"],"note":"Review every drug and supplement for renal dosing. NSAIDs, high-dose vitamin C and many botanicals need reconsidering.","protocol":"chronic-kidney-disease-ckd"},"Chronic obstructive pulmonary disease":{"pharm":["lama","laba","saba","sama","ics","pde4","sysster","varen","nrt","abx_resp","theoph"],"supps":["nac","vitd","coq10","omega3","curcumin"],"therapies":["smokingcess","pulmrehab","o2","breathing","exercise"],"labs":["spirometry","cxr","aat","cat_score","pulseox","abg","eos"],"note":"Spirometry alone confirms the diagnosis — imaging is not needed for it. NAC is the most effective agent for mucus. Cessation is the only intervention that changes the trajectory; screen mood before varenicline.","protocol":"chronic-obstructive-pulmonary-disease"},"Chronic pain":{"pharm":["gabapentinoid","snri","tca","acetamin","naltrexone_ld","nsaid"],"supps":["curcumin","magglyc","omega3","vitd","msm","boswellia"],"therapies":["cbt","physio","exercise","acupuncture","mindfulness","hydrotherapy"],"labs":["crp","vitdlab","ferritin","tsh","oat"],"note":"High urinary oxalates from fungal colonisation can mimic fibromyalgia and diffuse pain — worth remembering before settling on a central sensitisation label."},"Cognitive decline":{"pharm":["ssri"],"supps":["omega3","bcomplex","b12","vitd","lionsmane","ginkgo","coq10","creatine","ginseng","phosphatidyl"],"therapies":["exercise","medi_diet","sleephyg","groupsupport"],"labs":["mmse","tsh","b12folate","cbc","cmp","vitdlab","utox","mycotoxin","hladq"],"note":"Exclude the reversible causes first — B12, thyroid, medication burden, alcohol, sleep apnoea and depression. New brain fog with other systems involved should raise mould.","protocol":"alzheimer-s"},"Common cold":{"pharm":["decong","antihist1","acetamin"],"supps":["zinc","vitc","elderberry","propolis","garlic","vitd","astragalus","mushroom"],"therapies":["steam","nasalrinse","sleephyg"],"labs":["pulseox"],"note":"Test for a specific pathogen as soon as a patient in a high-risk group becomes symptomatic. In anyone under 19 on long-term aspirin or salicylates, a viral URI raises the risk of Reye's syndrome.","protocol":"upper-respiratory-infections"},"Congestive heart failure":{"pharm":["acei","arb","bblocker","mra","loop","sglt2"],"supps":["coq10","hawthorn","magglyc","taurine","carnitine"],"therapies":["exercise","weightmgmt","medi_diet"],"labs":["bnp","echo","ekg","cmp","cbc","cxr","tsh"],"note":"Left-sided heart failure is the classic cause of a transudative pleural effusion. Daily weights catch decompensation before breathlessness does."},"Conjunctivitis":{"pharm":["abx_topical_eye","antihist2"],"supps":["vitc","zinc"],"therapies":["dermcare"],"labs":[],"note":"Most cases are viral and self-limiting. A contact-lens wearer, photophobia, or vision change needs same-day ophthalmology."},"Constipation":{"pharm":["laxative","prokin"],"supps":["magglyc","psyllium","probiotic","vitc"],"therapies":["exercise","mayanmassage","medi_diet","pelvicfloor","diaphbreath"],"labs":["tsh","cmp","cbc","calpro","colonoscopy"],"note":"Correct constipation before any detox protocol — your mould lecture is explicit that toxins recirculate when the bowel is not moving."},"Cough":{"pharm":["muco","saba","ppi","antihist1","inasal"],"supps":["nac","slipperyelm","propolis","elderberry"],"therapies":["steam","breathing","nasalrinse"],"labs":["cxr","spirometry","afb","fet","pulseox"],"note":"The three commonest causes of chronic cough are upper airway cough syndrome, asthma and reflux. Cough beyond three weeks, or with haemoptysis, night sweats or weight loss, needs imaging and TB testing."},"Depression":{"pharm":["ssri","snri","bupropion","mirtaz","atypical","ketamine"],"supps":["omega3","saffron","vitd","bcomplex","magglyc","same","sjw","creatine","fivehtp"],"therapies":["cbt","exercise","medi_diet","phototherapy","sleephyg","counselling"],"labs":["phq9","mdq","tsh","cbc","cmp","vitdlab","b12folate","ferritin","utox","audit"],"note":"Five or more symptoms for at least two weeks, one of them depressed mood or anhedonia. Screen the MDQ before an antidepressant: SAMe, St John's wort and rhodiola can all trigger mania in a bipolar patient.","protocol":"major-depressive-disorder"},"Diabetes mellitus, type 2":{"pharm":["metformin","glp1","sglt2","sulfonyl","insulin","statin","acei"],"supps":["berberine","alphalipoic","chromium","magglyc","omega3","vitd","b12","inositol"],"therapies":["medi_diet","exercise","weightmgmt","glycemic"],"labs":["a1c","fastingins","lipids","cmp","ua","b12folate","vitdlab"],"note":"Check B12 in anyone on metformin for more than a few years. Berberine's glucose-lowering rivals metformin in trials but it inhibits CYP3A4 — review the whole medication list.","protocol":"diabetes-mellitus-t2dm"},"Diarrhea":{"pharm":["loperamide","antiparasitic","rifax"],"supps":["sboulardii","probiotic","psyllium","glutamine","zinc"],"therapies":["elimdiet","medi_diet"],"labs":["stoolcx","calpro","celiac","cbc","cmp","gimap"],"note":"Do not slow the gut where there is fever or blood in the stool — loperamide prolongs invasive infection."},"Dysmenorrhea":{"pharm":["nsaid","ocp","progestin","tranexamic"],"supps":["magglyc","omega3","vitex","curcumin","vitd","ginkgo"],"therapies":["mayanmassage","exercise","acupuncture","hydrotherapy"],"labs":["pelvic_us","cbc","ferritin","hormones_f"],"note":"Your Mayan abdominal massage coursework names dysmenorrhoea first among its indications. Pain that escalates over years, or with dyspareunia and subfertility, points at endometriosis."},"Dyspepsia":{"pharm":["ppi","h2ra","antacid","prokin","hpylori"],"supps":["dgl","slipperyelm","digenzyme","betaine","aloe"],"therapies":["elimdiet","glycemic","sleephyg"],"labs":["hpylori_t","egd","cbc","celiac","abdo_us"],"note":"Alarm features — weight loss, dysphagia, anaemia, vomiting, or new onset over 50 — mean endoscopy before empirical acid suppression."},"Eczema":{"pharm":["topster","topcalc","antihist1","biologic_imm","hydroxyzine"],"supps":["omega3","vitd","probiotic","zinc","quercetin"],"therapies":["dermcare","wetwrap","elimdiet","uvb"],"labs":["ige","cbc","kohprep","mycotoxin"],"note":"Eczema in an infant is often the first sign of mould illness, per your lecture. Emollients and barrier care are the base every regimen is built on.","protocol":"eczema"},"Edema":{"pharm":["loop","mra","ccb"],"supps":["citrusflav","horsechest","magglyc","taurine"],"therapies":["compression","exercise","weightmgmt"],"labs":["bnp","cmp","ua","echo","venous_us","abi"],"note":"Separate bilateral (cardiac, renal, hepatic, drug) from unilateral (DVT, lymphatic, local) — a unilateral swollen, warm, tender calf is a DVT until excluded."},"Endometriosis":{"pharm":["nsaid","ocp","progestin","gnrh"],"supps":["omega3","curcumin","dim","magglyc","nac","vitd"],"therapies":["mayanmassage","elimdiet","pelvicfloor","acupuncture","cbt","diaphbreath"],"labs":["pelvic_us","cbc","crp","hormones_f"],"note":"Your Mayan abdominal massage coursework lists endometriosis among its indications. A fixed retroverted uterus with nodular uterosacral ligaments on bimanual exam is the classic finding.","protocol":"endometriosis"},"Fatigue and low energy":{"pharm":[],"supps":["iron","b12","vitd","bcomplex","coq10","magglyc","adaptogen_blend","carnitine","rhodiola","ginseng","licorice_dgl","phosphatidyl"],"therapies":["sleephyg","exercise","medi_diet","glycemic","counselling"],"labs":["cbc","ferritin","tsh","b12folate","vitdlab","cmp","a1c","phq9","stopbang","cortisol"],"note":"Work through the common causes before the interesting ones: anaemia, thyroid, sleep apnoea, depression, medication and alcohol."},"Fertility and preconception":{"pharm":["ovulation","levothyrox"],"supps":["folate","vitd","omega3","inositol","coq10","iron","carnitine","maca"],"therapies":["mayanmassage","medi_diet","weightmgmt","counselling","remediation"],"labs":["hormones_f","semen","tsh","thyroidab","prolactin","pelvic_us","a1c","heavymetals","mycotoxin"],"note":"Your massage coursework names infertility among the indications, and your mould lecture asks you to screen for environmental toxicants where IVF has failed repeatedly. Start the male partner's semen analysis early."},"Fibromyalgia":{"pharm":["gabapentinoid","snri","tca","naltrexone_ld"],"supps":["magglyc","coq10","dribose","vitd","curcumin","carnitine","melatonin"],"therapies":["exercise","cbt","sleephyg","acupuncture","hydrotherapy","mindfulness"],"labs":["tsh","cbc","crp","vitdlab","ferritin","oat"],"note":"High oxalates from fungal colonisation can mimic fibromyalgia — worth excluding before committing to the label."},"Food intolerance":{"pharm":[],"supps":["digenzyme","probiotic","glutamine","betaine","nacetylglu"],"therapies":["elimdiet","medi_diet"],"labs":["celiac","sibo","calpro","ige","gimap"],"note":"Exclude coeliac disease before removing gluten — the serology only works while gluten is still being eaten."},"GERD":{"pharm":["ppi","h2ra","antacid","sucral","prokin"],"supps":["dgl","slipperyelm","melatonin_gerd","aloe","digenzyme"],"therapies":["sleephyg","weightmgmt","elimdiet"],"labs":["egd","hpylori_t","cbc"],"note":"Raise the head of the bed and leave three hours between the last meal and lying down. Taper a long-term PPI rather than stopping it — rebound acid is real. Peppermint oil must be enteric-coated or it makes reflux worse.","protocol":"gastroesophageal-reflux-disease"},"Gallstones":{"pharm":["ursodiol"],"supps":["milkthistle","taurine","hepavit","vitc"],"therapies":["medi_diet","weightmgmt"],"labs":["abdo_us","lft","cbc","cmp"],"note":"Ultrasound is first-line. Inspiratory arrest on right subcostal palpation — Murphy's sign — with fever means acute cholecystitis and urgent referral."},"Gastritis":{"pharm":["ppi","h2ra","sucral","hpylori"],"supps":["dgl","slipperyelm","glutamine","aloe","zinc"],"therapies":["elimdiet","medi_diet","mindfulness"],"labs":["hpylori_t","egd","cbc","celiac"],"note":"Test and treat H. pylori. Betaine HCl is contraindicated while the mucosa is inflamed or while on a PPI or NSAID."},"Gingivitis":{"pharm":["abx_resp"],"supps":["coq10","vitc","vitd","omega3","probiotic"],"therapies":["medi_diet"],"labs":["a1c","cbc"],"note":"Persistent or severe periodontal disease should prompt a diabetes screen — the relationship runs both ways."},"Gout":{"pharm":["nsaid","colchicine","uratelower","sysster"],"supps":["tarter","vitc","omega3","magglyc"],"therapies":["medi_diet","weightmgmt","exercise"],"labs":["urate","jointasp","cmp","cbc","a1c","lipids"],"note":"Aspirate a first presentation where infection is possible — negatively birefringent crystals mean gout, a positive culture means septic arthritis. Urate can be normal during a flare.","protocol":"gout"},"Hemorrhoids":{"pharm":["topster","laxative"],"supps":["citrusflav","psyllium","butchers","horsechest"],"therapies":["sitzbath","exercise","medi_diet"],"labs":["fob","colonoscopy","cbc"],"note":"Never attribute rectal bleeding to haemorrhoids without examining — and over 50, or with weight loss or altered bowel habit, colonoscopy first."},"Hepatitis":{"pharm":["hepser_tx","sysster"],"supps":["milkthistle","nac","vitd","omega3","taurine"],"therapies":["medi_diet","weightmgmt","exercise"],"labs":["lft","hepser","abdo_us","cbc","cmp"],"note":"Establish the cause before treating — viral, autoimmune, metabolic, alcohol and drug-induced take entirely different paths. Review every supplement for hepatotoxicity."},"Herpes simplex":{"pharm":["antiviral_hsv"],"supps":["zinc","vitc","propolis","mushroom","vitd"],"therapies":["sleephyg","mindfulness"],"labs":["sti","cbc"],"note":"Start antivirals within 72 hours of prodrome. Suppressive therapy is worth discussing where recurrences are frequent or a partner is uninfected."},"Hypertension":{"pharm":["acei","arb","ccb","thiazide","bblocker","mra"],"supps":["magglyc","coq10","garlic","hawthorn","omega3","taurine"],"therapies":["medi_diet","exercise","weightmgmt","vagal","sleephyg"],"labs":["bp_home","cmp","lipids","a1c","ua","ekg","echo","stopbang"],"note":"Confirm with home readings before treating. Screen for sleep apnoea in resistant hypertension. Liquorice and NSAIDs both raise blood pressure — check the supplement list.","protocol":"hypertension"},"Hyperthyroidism":{"pharm":["antithyroid","bblocker"],"supps":["selenium","magglyc","carnitine"],"therapies":["mindfulness","counselling"],"labs":["tsh","thyroidab","cbc","lft","ekg","dexa"],"note":"Any sore throat or fever on an antithyroid drug needs an urgent white cell count — agranulocytosis. Avoid ashwagandha, which raises thyroid hormones."},"Hypothyroidism":{"pharm":["levothyrox"],"supps":["selenium","iodine","iron","vitd","zinc","b12"],"therapies":["medi_diet","exercise","sleephyg"],"labs":["tsh","thyroidab","t3rt3","cbc","ferritin","lipids","b12folate"],"note":"Take levothyroxine fasted, four hours away from calcium, iron, magnesium and coffee. Correct iron and selenium — conversion depends on them. High-dose iodine can worsen Hashimoto's."},"Influenza":{"pharm":["oselt","acetamin","decong"],"supps":["elderberry","zinc","vitc","vitd","propolis","astragalus"],"therapies":["sleephyg","steam"],"labs":["pulseox","cxr","cbc"],"note":"Rapid onset of fatigue, fever, myalgia and headache without loss of taste or smell points to influenza over COVID-19. Antivirals work best within 48 hours."},"Insomnia":{"pharm":["trazodone","zdrug","mirtaz","antihist1"],"supps":["magglyc","melatonin","glycine","valerian","ltheanine","passionflower","chamomile"],"therapies":["cbt","sleephyg","caffeine_cut","exercise","vagal"],"labs":["stopbang","psg","tsh","ferritin","phq9","gad7"],"note":"CBT-I outperforms hypnotics and its gains last. Screen for sleep apnoea and restless legs before prescribing anything sedating — ferritin under 50 drives restless legs."},"Interstitial cystitis":{"pharm":["gabapentinoid","tca","antihist1"],"supps":["glutamine","aloe","quercetin","magglyc"],"therapies":["pelvicfloor","elimdiet","cbt","mindfulness","diaphbreath"],"labs":["ua","urineculture","sti","renal_us"],"note":"A culture-negative painful bladder. Identify dietary triggers — coffee, citrus, alcohol and artificial sweeteners are the usual four."},"Irritable bowel syndrome":{"pharm":["antispas","rifax","loperamide","laxative","ssri","tca"],"supps":["pepomint","psyllium","probiotic","glutamine","digenzyme","sboulardii","nacetylglu"],"therapies":["elimdiet","mayanmassage","cbt","exercise","mindfulness"],"labs":["calpro","celiac","sibo","stoolcx","cbc","gimap"],"note":"Your massage coursework names IBS among its indications. Calprotectin separates it from inflammatory bowel disease and can spare a colonoscopy. Treatment-resistant IBS is on your mould lecture's list of presentations to test.","protocol":"irritable-bowel-syndrome"},"Kidney stones":{"pharm":["nsaid","alphablock","thiazide"],"supps":["magglyc","vitk2","citrusflav"],"therapies":["medi_diet","exercise"],"labs":["ctabdo","renal_us","ua","cmp","urate"],"note":"Fluid volume beats every other measure. High-dose vitamin C raises oxalate — reconsider it in stone formers. Thiazides lower urinary calcium.","protocol":"nephrolithiasis"},"Lactation support":{"pharm":[],"supps":["vitd","omega3","iron","bcomplex","calcium"],"therapies":["counselling","groupsupport","medi_diet"],"labs":["cbc","ferritin","tsh","vitdlab"],"note":"Check every medication and botanical for lactation safety. Your mould lecture allows PectaSol and probiotics in pregnancy and stops all other detox agents."},"Menopause":{"pharm":["hrt","ssri","snri","ocp"],"supps":["blackcohosh","vitd","calcium","vitk2","magglyc","maca","omega3"],"therapies":["exercise","medi_diet","cbt","acupuncture","sleephyg"],"labs":["hormones_f","tsh","lipids","a1c","dexa","mammo"],"note":"Vaginal oestrogen is minimally absorbed and can be used where systemic therapy is not appropriate. Any post-menopausal bleeding is endometrial carcinoma until excluded."},"Migraine":{"pharm":["triptan","nsaid","cgrp","topiramate","bblocker","tca"],"supps":["magglyc","riboflavin","coq10","omega3","melatonin"],"therapies":["sleephyg","exercise","acupuncture","glycemic","elimdiet"],"labs":["bp_home","cbc","ferritin","tsh"],"note":"Riboflavin at 400 mg and magnesium have the best supplement evidence, both over 2–3 months. Limit acute medication to under 10 days a month or medication-overuse headache follows.","protocol":"migraine"},"Nausea and vomiting":{"pharm":["ondan","prokin","antihist1"],"supps":["magglyc","bcomplex","probiotic"],"therapies":["acupuncture","glycemic"],"labs":["cmp","cbc","abdo_us","hpylori_t"],"note":"Nausea with headache, confusion and hyponatraemia in a lung cancer patient is a paraneoplastic syndrome, not a gut problem."},"Neck and shoulder pain":{"pharm":["nsaid","acetamin","musclerelax"],"supps":["magglyc","curcumin","omega3","boswellia"],"therapies":["physio","exercise","acupuncture","hydrotherapy"],"labs":["xray_joint","mri_joint","crp"],"note":"Midline spinous tenderness after trauma needs imaging before mobilisation. Arm pain reproduced by extension, rotation and axial loading is radicular."},"Obesity":{"pharm":["glp1","metformin","sglt2"],"supps":["berberine","chromium","omega3","vitd","inositol"],"therapies":["medi_diet","exercise","weightmgmt","cbt","sleephyg"],"labs":["a1c","fastingins","lipids","lft","tsh","stopbang","bp_home"],"note":"Obesity is the commonest risk factor for obstructive sleep apnoea — screen with STOP-BANG. Exclude hypothyroidism and check for fatty liver."},"Osteoarthritis":{"pharm":["acetamin","nsaid","sysster"],"supps":["glucosamine","curcumin","collagen","msm","omega3","vitd"],"therapies":["exercise","physio","weightmgmt","acupuncture","hydrotherapy"],"labs":["xray_joint","crp","urate","jointasp"],"note":"Weight loss and strengthening outperform every supplement in knee osteoarthritis. Radiographic change tracks poorly with symptoms.","protocol":"osteoarthritis-oa"},"Osteoporosis":{"pharm":["bisphos","denosumab","hrt"],"supps":["vitd","calcium","vitk2","magglyc","collagen"],"therapies":["exercise","medi_diet","weightmgmt"],"labs":["dexa","vitdlab","cmp","tsh","cbc"],"note":"Correct vitamin D and calcium before starting an antiresorptive. Never stop denosumab without a follow-on agent — rebound vertebral fractures follow.","protocol":"osteoporosis"},"Otitis media":{"pharm":["abx_resp","acetamin","decong"],"supps":["vitd","zinc","propolis","probiotic"],"therapies":["steam","nasalrinse"],"labs":["cbc"],"note":"A bulging, immobile, erythematous tympanic membrane is the finding. Many cases resolve without antibiotics — delayed prescribing is reasonable in the well child."},"Parasites, intestinal":{"pharm":["antiparasitic"],"supps":["berberine","biocidin","garlic","sboulardii","probiotic"],"therapies":["elimdiet","medi_diet"],"labs":["stoolcx","cbc","gimap","calpro"],"note":"Treat on a positive stool test, not on suspicion. Eosinophilia on the CBC differential supports a parasitic cause."},"Pneumonia":{"pharm":["abx_resp","saba","sysster","oselt"],"supps":["nac","vitd","vitc","zinc","propolis"],"therapies":["steam","breathing","o2","pulmrehab"],"labs":["cxr","procalcitonin","sputum","legionella_ag","cbc","cmp","pulseox","abg","afb"],"note":"A lobar infiltrate on chest X-ray is what makes the diagnosis definitive — not the white count, the sputum stain or the blood gas. GI symptoms with hyponatraemia and a water-system exposure means Legionella and a urinary antigen test.","protocol":"lower-respiratory-infection"},"Polycystic ovary syndrome":{"pharm":["metformin","ocp","mra","ovulation","glp1"],"supps":["inositol","vitd","omega3","berberine","zinc","dim"],"therapies":["exercise","weightmgmt","medi_diet","glycemic","counselling"],"labs":["androgens","hormones_f","a1c","fastingins","lipids","pelvic_us","tsh","prolactin"],"note":"Myo-inositol in a 40:1 ratio with D-chiro-inositol has the best supplement evidence. Letrozole beats clomiphene for ovulation induction. Exclude thyroid disease, prolactinoma and late-onset CAH.","protocol":"polycystic-ov-ary-syndrome-pcos"},"Premenstrual syndrome":{"pharm":["ssri","ocp","nsaid"],"supps":["vitex","magglyc","bcomplex","calcium","omega3","dim"],"therapies":["exercise","medi_diet","cbt","glycemic","caffeine_cut"],"labs":["tsh","cbc","ferritin","hormones_f"],"note":"Vitex needs three cycles to judge. Symptom charting across two cycles distinguishes PMS from a mood disorder that merely worsens premenstrually.","protocol":"premenstrual-syndrome-pms"},"Prostatitis":{"pharm":["abx_prostate","alphablock","nsaid"],"supps":["saw","quercetin","betasito","zinc","probiotic"],"therapies":["pelvicfloor","sitzbath","mindfulness","diaphbreath"],"labs":["ua","urineculture","psa","sti","renal_us"],"note":"Chronic bacterial prostatitis needs 4–6 weeks of a drug that penetrates the gland. A boggy, exquisitely tender prostate with fever is acute prostatitis — do not massage it."},"Psoriasis":{"pharm":["topster","topcalc","dmard","biologic_imm"],"supps":["omega3","vitd","curcumin","probiotic","zinc"],"therapies":["uvb","dermcare","medi_diet","weightmgmt","mindfulness"],"labs":["crp","lipids","a1c","lft","ana"],"note":"Screen for psoriatic arthritis and for metabolic syndrome — both travel with it. Methotrexate and biologics need pre-treatment TB and hepatitis screening.","protocol":"psoriasis"},"Raynaud's phenomenon":{"pharm":["ccb"],"supps":["ginkgo","omega3","magglyc","vitc"],"therapies":["exercise","smokingcess","vagal"],"labs":["ana","cbc","crp","tsh"],"note":"Beta blockers worsen it. A positive ANA with digital ulceration suggests secondary Raynaud's from a connective tissue disease rather than primary."},"Rheumatoid arthritis":{"pharm":["dmard","biologic_imm","nsaid","sysster"],"supps":["omega3","curcumin","vitd","boswellia","probiotic"],"therapies":["exercise","physio","medi_diet","hydrotherapy"],"labs":["rf_ccp","crp","cbc","cmp","xray_joint","ana","hepser"],"note":"Symmetric MCP and PIP synovitis with over an hour of morning stiffness. Early DMARD therapy changes the outcome — do not delay while trialling supplements alone."},"Sinusitis":{"pharm":["inasal","abx_resp","decong","antihist2","ampho_nasal"],"supps":["bromelain","quercetin","nac","vitc","propolis","lsakei"],"therapies":["nasalrinse","steam","sinusrinse","remediation"],"labs":["nasalswab","cbc","ige","mycotoxin"],"note":"Saline irrigation is the highest-yield measure. Treatment-resistant sinusitis is where your mould lecture asks for a nasal swab with BOTH bacterial and fungal components — the fungal side is the one commonly missed."},"Sore throat":{"pharm":["abx_resp","acetamin","antihist1"],"supps":["propolis","zinc","vitc","elderberry","slipperyelm","licorice_dgl"],"therapies":["steam","sleephyg"],"labs":["cbc","sti"],"note":"Score before swabbing, and swab before prescribing. In anyone under 19 on long-term salicylates, a viral illness carries Reye's syndrome risk."},"Urinary incontinence":{"pharm":["oab","hrt","alphablock"],"supps":["magglyc","dmannose","vitd"],"therapies":["pelvicfloor","weightmgmt","exercise","caffeine_cut","diaphbreath"],"labs":["ua","urineculture","renal_us","bp_home"],"note":"Supervised pelvic floor physiotherapy is first-line for both stress and urgency types. New incontinence with saddle anaesthesia and leg weakness is cauda equina — an emergency."},"Urinary tract infection":{"pharm":["abx_uti","nsaid"],"supps":["dmannose","cranberry","probiotic","vitc"],"therapies":["sitzbath","pelvicfloor"],"labs":["ua","urineculture","renal_us","sti","a1c"],"note":"Nitrofurantoin does not reach the kidney — flank pain and fever mean pyelonephritis and a different agent. D-mannose is prevention, not treatment.","protocol":"urinary-tract-infection-uti"},"Varicose veins":{"pharm":["nsaid"],"supps":["citrusflav","horsechest","butchers","gotukola","vitc"],"therapies":["compression","exercise","weightmgmt"],"labs":["venous_us","abi"],"note":"Check the ankle-brachial index before compressing any limb where arterial disease is possible. Diosmin and hesperidin have the best oral evidence."},"Vertigo":{"pharm":["antihist1","ondan","benzo"],"supps":["ginkgo","magglyc","b12","vitd"],"therapies":["physio","vagal","hydrotherapy"],"labs":["cbc","cmp","b12folate","orthostatic","ekg","mmse"],"note":"Separate peripheral from central: sudden vertigo with any new neurological sign, or an inability to walk, is a posterior circulation stroke until excluded."},"Wound healing":{"pharm":["topster"],"supps":["zinc","vitc","vitaminA","collagen","gotukola","glutamine","bromelain"],"therapies":["dermcare","medi_diet","hydrotherapy"],"labs":["cbc","a1c","cmp","ferritin","abi","skinbiopsy"],"note":"A non-healing lower limb wound needs an ankle-brachial index and a glucose check before anything topical. Zinc and vitamin C are the two nutrients that most often limit healing.","protocol":"scars"},"Bipolar disorder":{"pharm":["lithium","moodstab","atypical","ketamine"],"supps":["omega3","magglyc","bcomplex","lithorotate","nadh"],"therapies":["sleephyg","medi_diet","cbt","counselling","exercise"],"labs":["mdq","tsh","cmp","cbc","utox","lipids"],"note":"Bipolar I needs one manic episode of at least a week; bipolar II needs a hypomanic episode of at least four days plus a major depressive episode; cyclothymia is recurrent dysthymic and hypomanic episodes over two years. AVOID SAMe, St John's wort, rhodiola, ginseng and high-dose caffeine — each can trigger mania or cycling. Light therapy also needs care.","extra":true},"Post-traumatic stress disorder":{"pharm":["ssri","snri","prazosin","ketamine","methblue","benzo"],"supps":["omega3","bcomplex","cbd","ashwagandha","lavender","magglyc"],"therapies":["cpt_therapy","pe_therapy","emdr","mindfulness","vagal","exercise"],"labs":["gad7","phq9","cortisol","tsh","cbc","utox"],"note":"Psychotherapy is first-line — CPT, prolonged exposure and EMDR. Benzodiazepines are NOT recommended: they interfere with the extinction learning therapy depends on and carry a high dependence risk. The HPA profile is raised CRH with a blunted ACTH response and low cortisol — a sensitised negative feedback loop.","extra":true},"Adjustment disorder":{"pharm":["ssri"],"supps":["magglyc","ltheanine","ashwagandha"],"therapies":["counselling","cbt","mindfulness","exercise","groupsupport"],"labs":["phq9","gad7"],"note":"Emotional or behavioural symptoms within three months of an identifiable stressor, out of proportion to it, resolving within six months of the stressor ending. That timeline is what separates it from MDD.","extra":true},"Obstructive sleep apnea":{"pharm":[],"supps":["vitd","magglyc","omega3"],"therapies":["cpap","mad","posturaltherapy","weightmgmt","uas","uppp","exercise"],"labs":["stopbang","psg","epworth","pulseox","a1c","bp_home"],"note":"STOP-BANG first — a clinically relevant score is what supports polysomnography, the gold standard. Severity comes from the Apnea-Hypopnea Index, not the questionnaire or neck circumference. Obesity is the commonest risk factor; lateral decubitus sleeping helps and supine worsens it. Vitamin D deficiency tracks with having the condition, and the worse the deficiency the worse the symptoms.","extra":true},"Central sleep apnea":{"pharm":[],"supps":["vitd","coq10"],"therapies":["cpap","weightmgmt"],"labs":["psg","echo","bnp","abg"],"note":"Cheyne-Stokes breathing is the associated pattern. Management is better control of the causative chronic conditions plus positive airway pressure — not the airway surgery or jaw devices used in obstructive apnoea. Opioids, sedatives, alcohol and smoking are root causes; NSAIDs are not.","extra":true},"Idiopathic pulmonary fibrosis":{"pharm":["antifib","sysster"],"supps":["nac","quercetin","serrapeptase","nattokinase","vitd"],"therapies":["o2","pulmrehab","smokingcess","breathing"],"labs":["chestct","spirometry","abg","pulseox","echo"],"note":"Pirfenidone and nintedanib are the antifibrotics. Quercetin may help but is not antifibrotic in mechanism. Honeycombing on high-resolution CT is the characteristic finding.","extra":true},"Bronchiectasis":{"pharm":["abx_resp","saba","laba","ics","muco"],"supps":["nac","vitd","omega3","probiotic"],"therapies":["airwayclear","pulmrehab","breathing"],"labs":["chestct","spirometry","sputum","sweatcl","cbc"],"note":"Tram-track and signet-ring signs on CT. Treatment is infection control, bronchodilation, inflammation suppression and — above all — daily airway clearance. Antifibrotic therapy has no place in it.","extra":true},"Sarcoidosis":{"pharm":["sysster","dmard","biologic_imm","naltrexone_ld"],"supps":["omega3","curcumin","nac"],"therapies":["pulmrehab","exercise"],"labs":["cxr","chestct","cmp","vitdlab","ua","cbc","rhc","crp"],"note":"Raised 1,25-dihydroxyvitamin D without supplementation, hypercalciuria, mild anaemia and a reversed albumin/globulin ratio. Do NOT supplement vitamin D blindly here. Prostacyclin derivatives are not a treatment — no pulmonary vasodilator without a right heart catheterisation first.","extra":true},"Cystic fibrosis":{"pharm":["muco","abx_resp","saba"],"supps":["vitaminA","vitd","vite","vitk2","digenzyme","nac"],"therapies":["airwayclear","pulmrehab","exercise"],"labs":["sweatcl","chestct","spirometry","sputum","cbc"],"note":"Recurrent bronchitis with haemoptysis, chronic sinus disease, greasy floating stools and failure to thrive. Elevated sweat sodium, chloride or potassium on quantitative pilocarpine iontophoresis confirms it.","extra":true},"Pulmonary hypertension":{"pharm":["ccb","anticoag","loop"],"supps":["coq10","nattokinase","taurine","carnitine"],"therapies":["o2","pulmrehab","exercise"],"labs":["rhc","echo","cxr","ekg","bnp","spirometry"],"note":"Right heart catheterisation is the gold standard — echocardiography screens, it does not confirm. Cor pulmonale is the complication to fear. Exertional dyspnoea with syncope and enlarged pulmonary arteries on plain film is the picture.","extra":true},"Pulmonary embolism":{"pharm":["anticoag"],"supps":["omega3"],"therapies":["compression","exercise"],"labs":["ddimer","ctpa","abg","ekg","venous_us","trop","bnp"],"note":"D-dimer is the first step where clinical likelihood is LOW; CT angiography is what rules it out. Blood gases classically show low oxygen with low CO2 from hyperventilation. A pleural friction rub points specifically at pulmonary infarction.","extra":true},"Respiratory failure and ARDS":{"pharm":["sysster","saba","abx_resp"],"supps":["nac","vitc","vitd"],"therapies":["o2","cpap","breathing","pulmrehab"],"labs":["abg","cxr","pulseox","cbc","cmp","ctpa"],"note":"Type 1 is hypoxaemic, type 2 adds CO2 retention — non-invasive positive pressure ventilation suits type 2. ARDS under the Berlin criteria requires an insult within one week, and injures capillary endothelial and alveolar epithelial cells. Keep oxygen to the minimum effective concentration — 60–100% risks oxygen toxicity.","extra":true},"Pulmonary nodules and lung cancer":{"pharm":["sysster"],"supps":["vitd","curcumin","mushroom","omega3"],"therapies":["smokingcess","counselling","groupsupport","exercise"],"labs":["chestct","cxr","sputum","cbc","cmp","thoracentesis"],"note":"Irregular border, large size, ground-glass appearance and older age suggest malignancy; concentric calcification suggests benignity. Small cell and squamous arise centrally with symptoms; adenocarcinoma and large cell peripherally without. Radon is the commonest cause after smoking; adenocarcinoma is commonest in non-smokers; small cell is the most aggressive. Brain, bone and liver are the usual metastatic sites. Hyponatraemia in small cell is paraneoplastic SIADH.","extra":true},"Pleural disease":{"pharm":["nsaid","abx_resp"],"supps":["curcumin","omega3"],"therapies":["breathing","physio"],"labs":["cxr","chestct","thoracentesis","cbc","crp"],"note":"Increased fremitus separates early lobar pneumonia from effusion — sound travels better through consolidated lung than through fluid. Transudates come from left-sided heart failure; exudates from pneumonia, malignancy and embolism. The visceral pleura is insensitive; pleuritic pain comes from the parietal pleura via the intercostal nerves, and diaphragmatic involvement refers to neck and shoulder. Pneumothorax needs a chest tube; a retained haemothorax risks empyema and fibrothorax.","extra":true},"Tuberculosis":{"pharm":["abx_resp"],"supps":["vitd","vitaminA","zinc"],"therapies":["counselling"],"labs":["afb","cxr","chestct","cbc","cmp","sputum"],"note":"Chronic cough with haemoptysis, night sweats and travel to an endemic area. No single test is definitive on its own — culture confirms. Drug-resistant TB is not prevalent in the United States.","extra":true},"COVID-19":{"pharm":["covid_av","sysster","anticoag"],"supps":["resveratrol","quercetin","vitd","zinc","vitc","nac","melatonin"],"therapies":["breathing","o2","sleephyg"],"labs":["pulseox","cxr","cbc","cmp","ddimer","crp"],"note":"Resveratrol is the agent that addresses both the inflammation and the thrombus formation. Return to normal activities needs symptom improvement AND no fever for 24 hours — not a negative test.","extra":true},"Mold and mycotoxin illness":{"pharm":["ampho_nasal","abx_resp"],"supps":["pectasol","ultrabinder","sboulardii","biocidin","nac","glutathione","lsakei","probiotic","iron","b12","iodine","zinc","vitd"],"therapies":["remediation","binderprotocol","sauna","lymphatic","sinusrinse","medi_diet","counselling"],"labs":["mycotoxin","oat","shoemaker","hladq","nasalswab","candida_ab","envtest","heavymetals","crista_q","cbc","cmp"],"note":"Multiple symptoms across multiple systems together is the clinical clue. Order of work: correct nutritional deficiencies (iron, B12, B9, iodine, vitamin D, copper, zinc, thyroid), then foundations of sleep, food and stress, then gut and toxicant detox together, then infectious disease last. Do NOT detox during ongoing exposure, active colonisation, severe constipation or extreme sensitivity, and avoid glutathione, liver sauce and NAD+ while exposure continues. Treat sinuses last. Always consider mould when treating Lyme, EBV, seizures, autism, treatment-resistant SIBO, MCAS, chronic candida, infertility and cancer.","extra":true},"Atrial fibrillation":{"pharm":["anticoag","bblocker","ccb"],"supps":["magglyc","taurine","omega3","coq10"],"therapies":["weightmgmt","exercise","caffeine_cut"],"labs":["ekg","holter","echo","tsh","cmp","cbc","stopbang"],"note":"An irregularly irregular pulse is the bedside finding. Check thyroid function and screen for sleep apnoea — both drive it. Anticoagulation is decided on stroke risk, not on symptoms.","extra":true,"protocol":"atrial-fibrillation"},"Deep vein thrombosis":{"pharm":["anticoag"],"supps":["nattokinase","omega3","citrusflav"],"therapies":["compression","exercise"],"labs":["venous_us","ddimer","cbc","cmp"],"note":"Unilateral calf swelling, warmth and tenderness. Duplex ultrasound is first-line. Do not start a fibrinolytic supplement alongside anticoagulation without supervision.","extra":true},"Abdominal aortic aneurysm":{"pharm":["statin","acei","bblocker"],"supps":["omega3","vitc"],"therapies":["smokingcess","exercise"],"labs":["aaa_us","lipids","bp_home","ekg"],"note":"A widened, expansile pulsation over 3 cm. Blood pressure control and smoking cessation slow expansion; size and growth rate decide repair.","extra":true},"Statin-associated muscle symptoms":{"pharm":["statin"],"supps":["coq10","vitd","omega3"],"therapies":["exercise"],"labs":["ck","lft","vitdlab","tsh"],"note":"Check CK where pain is severe. Correct vitamin D and thyroid before abandoning the statin; CoQ10 replaces what the drug depletes. Never combine a statin with red yeast rice.","extra":true},"Inflammatory bowel disease":{"pharm":["mesalamine","sysster","biologic_imm","dmard"],"supps":["omega3","curcumin","glutamine","probiotic","vitd","boswellia","aloe","iron"],"therapies":["elimdiet","medi_diet","mindfulness","remediation"],"labs":["calpro","colonoscopy","cbc","cmp","crp","ferritin","stoolcx","mycotoxin"],"note":"Your mould lecture's “fuzzy dresser” case is an IBD patient whose inflammatory markers only normalised once a mould-contaminated piece of furniture left the house — worth remembering in inflammation that resists treatment.","extra":true,"protocol":"irritable-bowel-disease"},"Sexually transmitted infection":{"pharm":["abx_uti","antiviral_hsv","antifungal"],"supps":["probiotic","zinc","vitc","mushroom"],"therapies":["counselling","pelvicfloor"],"labs":["sti","wetmount","ua","urineculture"],"note":"Screen partners and re-test after treatment. The protocol splits its plan by organism — bacterial vaginosis and candidiasis, herpes simplex, and human papillomavirus.","extra":true,"protocol":"sexually-transmitted-infection-sti"},"Erectile dysfunction":{"pharm":["alphablock","statin","acei"],"supps":["carnitine","ginkgo","maca","coq10","omega3","zinc"],"therapies":["exercise","weightmgmt","counselling","medi_diet","smokingcess"],"labs":["a1c","lipids","hormones_f","tsh","bp_home","cmp"],"note":"Erectile dysfunction is often the first sign of endothelial disease — work it up as a cardiovascular risk marker, not only as a sexual complaint.","extra":true,"protocol":"erectile-dysfunction-ed"},"Attention deficit disorder":{"pharm":["bupropion","ssri"],"supps":["omega3","magglyc","zinc","iron","bcomplex","phosphatidyl","lionsmane"],"therapies":["sleephyg","exercise","elimdiet","glycemic","cbt","counselling"],"labs":["cbc","ferritin","tsh","vitdlab","b12folate","mycotoxin"],"note":"Check iron and ferritin — low iron worsens attention and restless sleep. New-onset ADHD is on your mould lecture's list of presentations to test for mycotoxins.","extra":true,"protocol":"attention-deficit-disorder"},"Seizure disorder":{"pharm":["moodstab","benzo"],"supps":["magglyc","bcomplex","vitd","omega3","taurine"],"therapies":["sleephyg","elimdiet","counselling"],"labs":["cmp","cbc","mmse","utox","mycotoxin","hladq"],"note":"Sudden-onset seizures with no family history is the presentation your mould lecture's second case study describes — testing confirmed exposure and the child was weaned off medication after relocation and detox.","extra":true,"protocol":"seizures"},"Multiple sclerosis":{"pharm":["biologic_imm","dmard","sysster","gabapentinoid","naltrexone_ld"],"supps":["vitd","omega3","alphalipoic","bcomplex","coq10","probiotic","carnitine"],"therapies":["exercise","physio","medi_diet","mindfulness","counselling"],"labs":["vitdlab","b12folate","ana","cbc","cmp","mri_spine"],"note":"Vitamin D status is both a risk factor and a modifiable target. Heat sensitivity (Uhthoff's phenomenon) makes hot exercise environments a practical problem.","extra":true,"protocol":"multiple-sclerosis"},"Parkinson's disease":{"pharm":["ssri","gabapentinoid"],"supps":["coq10","omega3","vitd","creatine","probiotic","carnitine","magglyc"],"therapies":["exercise","physio","counselling","medi_diet","groupsupport"],"labs":["cbc","cmp","tsh","b12folate","mmse","heavymetals"],"note":"Constipation and loss of smell often precede the motor signs by years. Protein timing matters where levodopa is used — large protein meals compete with its absorption.","extra":true,"protocol":"parkinson-s"},"Hepatic steatosis":{"pharm":["glp1","sglt2","metformin","statin"],"supps":["milkthistle","omega3","vite","berberine","nac","hepavit","taurine"],"therapies":["weightmgmt","exercise","medi_diet","glycemic"],"labs":["lft","abdo_us","a1c","fastingins","lipids","hepser","cbc"],"note":"Weight loss of 7–10% is the intervention with the strongest evidence. Exclude alcohol, viral hepatitis and drug causes before calling it metabolic.","extra":true,"protocol":"hepatic-steatosis"},"Celiac disease":{"pharm":[],"supps":["iron","b12","folate","vitd","calcium","zinc","digenzyme","probiotic","glutamine"],"therapies":["elimdiet","medi_diet","counselling"],"labs":["celiac","cbc","ferritin","b12folate","vitdlab","dexa","cmp","egd"],"note":"Serology only works while gluten is still being eaten — test before removing it. Strict lifelong gluten avoidance is the treatment; screen for the deficiencies malabsorption leaves behind.","extra":true,"protocol":"celiac-disease"},"Small intestinal bacterial overgrowth":{"pharm":["rifax","prokin"],"supps":["berberine","biocidin","digenzyme","betaine","glutamine","probiotic","pepomint"],"therapies":["elimdiet","mayanmassage","exercise"],"labs":["sibo","celiac","calpro","cbc","tsh","gimap"],"note":"Treatment-resistant SIBO is one of the presentations your mould lecture says should always prompt a mycotoxin workup. Address motility, not just the overgrowth, or it returns.","extra":true,"protocol":"small-intestinal-bacterial-overgrowth"},"Warts":{"pharm":["antiviral_hsv"],"supps":["zinc","vitaminA","vitc","mushroom","propolis","garlic"],"therapies":["dermcare"],"labs":["sti","skinbiopsy"],"note":"Most resolve spontaneously over months to years. Anogenital warts need STI screening and cervical screening where relevant.","extra":true,"protocol":"warts"},"Burns":{"pharm":["topster","acetamin","nsaid","abx_resp"],"supps":["aloe","vitc","zinc","collagen","gotukola","vitaminA","glutamine","bromelain"],"therapies":["dermcare","hydrotherapy","medi_diet"],"labs":["cbc","cmp","skinbiopsy"],"note":"Depth and total body surface area decide referral. Cool with running water, never ice, and never break blisters routinely.","extra":true,"protocol":"burns"}},"protocols":[{"id":"urinary-tract-infection-uti","title":"Urinary Tract Infection (UTI)","condition":"Urinary tract infection","background":"Urinary tract infections (UTIs) are infections that occur anywhere along the urinary tract, most commonly affecting the bladder (cystitis) and urethra (urethritis), and less frequently the kidneys (pyelonephritis). They are primarily caused by ascending bacterial pathogens, most notably Escherichia coli, which accounts for up to 90% of cases. Risk factors include female sex, sexual activity, urinary stasis, catheterization, and anatomical abnormalities. UTIs are highly prevalent, especially among women, with nearly half experiencing at least one episode in their lifetime. Pathophysiologically, bacteria colonize the periurethral area, ascend the urethra, and adhere to uroepithelial cells, triggering inflammation. Clinically, UTIs typically present with dysuria, urinary frequency, urgency, suprapubic discomfort, and hematuria. In upper tract infections, fever, flank pain, and systemic symptoms may occur. Differential diagnoses include vaginitis, interstitial cystitis, urethritis, and sexually transmitted infections. Diagnosis is based on clinical symptoms and confirmed with urinalysis and urine culture. Management involves increased fluid intake and appropriate antibiotics, with nitrofurantoin or TMP-SMX commonly used for uncomplicated cases. Prognosis is generally excellent with timely treatment, but complications such as recurrent infections, renal scarring, or sepsis can occur, particularly in high-risk groups like pregnant women and the elderly.","steps":[{"agent":"D-Mannose","dose":"2 grams three times daily for 5-7 days","why":"D-Mannose inhibits bacterial adhesion, particularly of E. coli, to the bladder wall, helping flush pathogens out through urination. It's effective for acute symptom management and recurrent UTI prevention."},{"agent":"Uva-ursi (Arctostaphylos uva-ursi)","dose":"500 mg capsule or 5 mL tincture every 2-3 hours (max 5 days)","why":"Contains arbutin, a urinary antiseptic that becomes active in alkaline urine, reducing bacterial load. Best for short-term use due to potential liver toxicity with prolonged dosing."},{"agent":"Cranberry Extract (Vaccinium spp.)","dose":"500-1000 mg extract TID (acute), or 6-8 oz unsweetened juice TID","why":"Rich in proanthocyanidins that prevent bacterial adhesion to the urinary tract lining. Useful in both acute infections and for reducing recurrence risk."},{"agent":"Vaginal Probiotics (Lactobacillus rhamnosus & L. reuteri)","dose":"One capsule intravaginally once weekly for 4 weeks","why":"Recolonizes the vaginal flora with protective Lactobacilli, helping lower vaginal pH and outcompete uropathogens, especially beneficial in individuals with recurrent UTIs."},{"agent":"Additional Support","dose":null,"why":"Hydration: Encourage >1.5-2 L/day to promote bladder flushing. Avoid Irritants: Limit caffeine, alcohol, and spicy food during active infection. Safety Plan: Educate patients to seek emergent medical care for fever, flank pain, or symptoms >3 days."}],"notes":null,"flag":null},{"id":"sexually-transmitted-infection-sti","title":"Sexually Transmitted Infection (STI)","condition":"Sexually transmitted infection","background":"Sexually transmitted infections (STIs) are infections primarily spread through sexual contact, including vaginal, anal, and oral sex. They are caused by a range of pathogens, including bacteria (eg, Chlamydia trachomatis, Neisseria gonorrhoeae, Treponema pallidum), viruses (eg, HIV , HPV , HSV), and parasites (eg, Trichomonas vaginalis). STIs are among the most common infectious diseases worldwide, with young adults aged 15-24 at highest risk due to behavioral and biological factors. Social stigma, limited access to care, and asymptomatic carriers contribute to widespread transmission. Pathophysiologically, pathogens invade mucosal or epithelial surfaces, triggering local and systemic immune responses. Clinical presentations vary but may include urethral or vaginal discharge, dysuria, genital ulcers, pelvic pain, or asymptomatic infection. Differential diagnoses include urinary tract infections, bacterial vaginosis, candidiasis, and dermatologic conditions. Diagnosis is based on history, physical exam, and targeted lab tests (eg, NAATs, serology). Management depends on the pathogen but often includes antibiotics or antivirals, partner notification, and education. Prognosis is generally good with early treatment, but untreated STIs can lead to complications such as pelvic inflammatory disease, infertility, chronic pelvic pain, adverse pregnancy outcomes, and increased HIV risk.","steps":[{"agent":"Bacterial Vaginosis and Candidiasis","dose":null,"why":"","heading":true},{"agent":"Intravaginal Probiotics","dose":"1+ billion CFU Lactobacillus spp intravaginally once daily for 7-10 days","why":"Restores healthy vaginal flora by promoting acid-producing Lactobacilli, which suppress overgrowth of pathogenic bacteria and yeast. Especially effective in BV and yeast infections, and helpful post-antibiotic."},{"agent":"Herpes Simplex Virus (HSV)","dose":null,"why":"","heading":true},{"agent":"Lysine + Antiviral Botanicals","dose":"Lysine 3 g/day during outbreaks, 1-2 g/day for prevention","why":"Add: Melissa officinalis or Glycyrrhiza glabra tea or tincture (2-4 mL TID) Lysine competes with arginine to inhibit HSV replication. Antiviral herbs further support immune defense and may reduce severity and duration of lesions."},{"agent":"Human Papillomavirus (HPV)","dose":null,"why":"","heading":true},{"agent":"Green Tea Extract","dose":null,"why":"Topical: Sinecatechin 15% ointment, apply TID for up to 16 weeks Oral: 500-800 mg green tea extract daily for 3-6 months EGCG in green tea supports HPV clearance and immune modulation. Topical formulations can reduce size and recurrence of genital warts."}],"notes":null,"flag":null},{"id":"chronic-kidney-disease-ckd","title":"Chronic Kidney Disease (CKD)","condition":"Chronic kidney disease","background":"Chronic kidney disease (CKD) is defined as a gradual, irreversible decline in kidney function lasting more than three months, typically measured by a glomerular filtration rate (GFR) <60 mL/min/1.73 m² and/or evidence of kidney damage such as albuminuria. Major causes include diabetes mellitus, hypertension, glomerulonephritis, and polycystic kidney disease. CKD affects approximately 10-15% of the global population, with increased prevalence in older adults and those with cardiovascular risk factors. Pathophysiologically, CKD involves progressive nephron loss leading to compensatory hyperfiltration, glomerular sclerosis, and interstitial fibrosis. Patients may remain asymptomatic in early stages, with later symptoms including fatigue, edema, hypertension, uremia, and electrolyte imbalances. Differential diagnoses include acute kidney injury, urinary tract obstruction, and nephrotic syndrome. Diagnosis relies on eGFR, urinalysis, albumin-to- creatinine ratio, and renal imaging. Management focuses on slowing progression through blood pressure control (ACE inhibitors/ARBs), glycemic management, lifestyle modifications, and avoidance of nephrotoxins. Prognosis varies by stage and comorbidities; however, advanced CKD can progress to end-stage renal disease requiring dialysis or transplant. Complications include anemia, mineral-bone disorder, cardiovascular disease, and increased mortality.","steps":[{"agent":"Protein Management","dose":null,"why":"Early CKD: 0.8-1 g/kg/day Moderate to Advanced CKD: 0.6-0.8 g/kg/day Restricting protein slows kidney workload and reduces nitrogenous waste accumulation. Emphasize plant-based proteins like legumes, soy, and quinoa while avoiding red and processed meats."},{"agent":"Sodium Restriction","dose":"<2 g/day (or up to 3 g/day if strict restriction not tolerated)","why":"Lower sodium intake helps control blood pressure, reduce fluid retention, and improve responsiveness to RAAS medications - all crucial for slowing CKD progression."},{"agent":"Phosphorus Control","dose":null,"why":"Target: <800 mg/day for Stage 3 CKD and beyond Reducing dietary phosphorus (by limiting processed foods and dairy) lowers risk of vascular calcification and secondary hyperparathyroidism. Use phosphate binders with meals as needed in later stages."},{"agent":"Oral Sodium Bicarbonate (for Metabolic Acidosis)","dose":"650-1300 mg BID if serum CO₂ <20 mmol/L","why":"Alkali therapy corrects metabolic acidosis, which can otherwise accelerate CKD progression and bone loss. The goal is to maintain serum CO₂ >22 mmol/L."},{"agent":"Additional Support","dose":null,"why":"Monitor labs regularly (GFR, potassium, phosphorus, bicarbonate) Encourage a DASH or Mediterranean diet early on; adjust based on labs Collaborate with nephrology and dietetics for personalized care as CKD advances"}],"notes":null,"flag":null},{"id":"nephrolithiasis","title":"Nephrolithiasis","condition":"Kidney stones","background":"Nephrolithiasis, or kidney stones, refers to the formation of solid crystalline aggregates in the renal collecting system, often composed of calcium oxalate, calcium phosphate, uric acid, or cystine. Etiologies include dehydration, hypercalciuria, hyperoxaluria, low urinary citrate, dietary factors, genetic predisposition, and metabolic disorders. It affects about 10% of the population, with higher incidence in men and peak onset between ages 30-50. Pathophysiologically, stones form when urinary solutes become supersaturated and precipitate into crystals, which may grow and obstruct urinary flow. Clinically, nephrolithiasis presents with sudden, severe flank pain radiating to the groin, hematuria, nausea, and urinary urgency or frequency. Differential diagnoses include pyelonephritis, appendicitis, ectopic pregnancy, and abdominal aortic aneurysm. Diagnosis is confirmed via non-contrast CT, renal ultrasound, or urinalysis showing hematuria or crystals. Management includes hydration, pain control (NSAIDs or opioids), and stone-specific treatments such as alpha-blockers (eg, tamsulosin) for passage or lithotripsy for larger stones. Prognosis is generally good with proper treatment, but recurrence is common. Complications may include urinary obstruction, infection, hydronephrosis, or renal damage.","steps":[{"agent":"Hydration Optimization","dose":null,"why":"Goal: ≥2.5 L urine/day (up to 3 L/day for uric acid or cystine stones) High fluid intake dilutes urinary solutes and reduces crystal formation, lowering recurrence risk for all stone types. Use lemon water or herbal teas to support hydration and citrate levels."},{"agent":"Potassium Citrate (for hypocitraturia and uric acid/cystine stones)","dose":"10-20 mEq BID (max 100 mEq/day); adjust based on labs and urine pH","why":"Raises urinary citrate and alkalizes urine, preventing calcium oxalate and uric acid stone formation. Monitor potassium and urine pH to avoid over-alkalinization."},{"agent":"Phyllanthus niruri (Chanca Piedra)","dose":"400-500 mg capsule TID or 30-60 drops tincture TID for 6-8 weeks","why":"Demonstrated litholytic (ability to dissolve or break stones) activity, helping to reduce stone size and ease passage. Often used for calcium oxalate and uric acid stone prevention."},{"agent":"Pyridoxine (Vitamin B6)","dose":"200 mg BID","why":"Reduces urinary oxalate production by supporting glyoxylate metabolism, particularly in calcium oxalate stone formers. Safe and well-tolerated as a long-term preventive."}],"notes":null,"flag":"Filed under Kidney stones."},{"id":"erectile-dysfunction-ed","title":"Erectile Dysfunction (ED)","condition":"Erectile dysfunction","background":"Erectile dysfunction (ED) is the persistent inability to achieve or maintain an erection sufficient for satisfactory sexual performance. Etiologies include vascular disease (eg, atherosclerosis), diabetes mellitus, neurological disorders, hypogonadism, medications (eg, antihypertensives, SSRIs), psychological factors, and lifestyle contributors like smoking and alcohol use. ED affects an estimated 30 million men in the U.S., with prevalence increasing with age, particularly in men over 40. Pathophysiologically, ED results from impaired blood flow, nerve signaling, or hormonal imbalance, often involving endothelial dysfunction and reduced nitric oxide availability. Patients may report reduced rigidity, difficulty maintaining erections, or loss of nocturnal erections. Differential diagnoses include hypogonadism, Peyronie’s disease, depression, and medication-induced sexual dysfunction. Diagnosis involves history, physical exam, and targeted labs (eg, testosterone, glucose, lipids), with further evaluation (eg, nocturnal penile tumescence testing) in select cases. Management includes lifestyle modification, treating underlying conditions, and pharmacotherapy - typically PDE5 inhibitors like sildenafil. Prognosis is favorable with appropriate treatment, though ED may signal underlying cardiovascular disease. Complications include reduced quality of life, relationship stress, and psychological distress.","steps":[{"agent":"L-Arginine","dose":"3-5 g/day or 2 g extended-release, taken 30-60 minutes before sexual activity.","why":"L-Arginine boosts nitric oxide production, enhancing blood flow to penile tissue. Particularly helpful in cases involving vascular insufficiency."},{"agent":"Mediterranean Diet + Exercise","dose":null,"why":"Duration: Ongoing This anti-inflammatory, antioxidant-rich dietary pattern improves endothelial function and reduces metabolic syndrome risk, both of which are key contributors to ED. Combine this with regular aerobic and resistance training for synergistic benefit."},{"agent":"Maca (Lepidium meyenii)","dose":"1.5-3 g/day for at least 6-12 weeks","why":"Traditionally used to enhance libido, energy, and sexual stamina; acts as an adaptogen to support hormonal and sexual function."},{"agent":"Acetyl-L-Carnitine","dose":"2 grams twice daily","why":"Supports nerve regeneration and mitochondrial function, especially useful in ED related to nerve damage (eg. post- prostatectomy or diabetic neuropathy). Can be combined with PDE5 inhibitors for enhanced effect."},{"agent":"Additional Advice","dose":null,"why":"Screen for and manage diabetes, hypertension, and depression. Address psychogenic factors with counseling if relevant. Avoid OTC ED supplements due to contamination risk."}],"notes":null,"flag":null},{"id":"benign-prostatic-hyperplasia-bph","title":"Benign Prostatic Hyperplasia (BPH)","condition":"Benign prostatic hyperplasia","background":"Benign prostatic hyperplasia (BPH) is a non-malignant enlargement of the prostate gland, commonly affecting men over 50 due to age-related hormonal changes, particularly increased dihydrotestosterone (DHT) activity. It is the most common cause of lower urinary tract symptoms (LUTS) in aging men, with prevalence rising from 20% in men aged 40-49 to over 80% in those over 70. BPH results from hyperplasia of prostatic stromal and epithelial cells, leading to urethral compression and bladder outlet obstruction. Clinically, it presents with urinary hesitancy, weak stream, nocturia, frequency, urgency, and incomplete emptying. Differential diagnoses include prostate cancer, urinary tract infection, neurogenic bladder, and urethral stricture. Diagnosis is based on symptom assessment (eg, IPSS score), digital rectal exam, urinalysis, PSA levels, and sometimes ultrasound or urodynamic testing. Management includes lifestyle modifications, alpha-blockers (eg, tamsulosin), 5-alpha-reductase inhibitors (eg, finasteride), and surgical options like TURP if severe. Prognosis is generally good, but complications may include acute urinary retention, recurrent UTIs, bladder stones, and renal impairment if untreated.","steps":[{"agent":"Saw Palmetto (Serenoa repens)","dose":"160 mg twice daily for at least 3-6 months","why":"Inhibits 5-alpha-reductase, reducing dihydrotestosterone (DHT) levels and improving urinary symptoms. Comparable in efficacy to tamsulosin in mild to moderate BPH."},{"agent":"Flaxseed Meal","dose":"30 g/day (~2 tablespoons), ground and added to food","why":"Rich in lignans and omega-3s, flaxseed supports hormone metabolism, reduces PSA levels, and improves lower urinary tract symptoms (LUTS)."},{"agent":"Pumpkin Seeds (Cucurbita pepo)","dose":"1-2 tablespoons daily as part of diet or standardized extract","why":"Improve urinary flow (Qmax), symptom score (IPSS), and quality of life by supporting bladder function and reducing inflammation."},{"agent":"Lycopene + Selenium","dose":"Lycopene 15 mg/day + Selenium 100-200 mcg/day","why":"Lycopene reduces prostate volume and improves symptom scores; selenium adds antioxidant support and may enhance the effects of saw palmetto and lycopene."}],"notes":null,"flag":null},{"id":"premenstrual-syndrome-pms","title":"Premenstrual Syndrome (PMS)","condition":"Premenstrual syndrome","background":"Premenstrual syndrome (PMS) refers to a group of physical, emotional, and behavioral symptoms that occur cyclically during the luteal phase of the menstrual cycle and resolve shortly after menstruation begins. The exact etiology is unclear but is believed to involve abnormal responses to normal hormonal fluctuations, particularly involving serotonin and progesterone. PMS affects up to 75% of menstruating women, with moderate-to-severe symptoms in about 20-30%, most commonly in women in their late 20s to early 40s. Pathophysiologically, PMS may involve altered neurotransmitter sensitivity, fluid retention, and hormonal imbalances affecting mood and somatic function. Common symptoms include mood swings, irritability, anxiety, fatigue, bloating, breast tenderness, and headaches. Differential diagnoses include premenstrual dysphoric disorder (PMDD), depression, anxiety disorders, hypothyroidism, and anemia. Diagnosis is clinical, requiring symptom tracking over at least two cycles. Management includes lifestyle modifications, aerobic exercise, calcium (500-1200 mg/day), magnesium, vitamin B6, SSRIs, and hormonal contraceptives. Prognosis is favorable with treatment, though some may progress to PMDD. Complications include impaired daily functioning and reduced quality of life if left unaddressed.","steps":[{"agent":"Cal/Mag/D Supplement","dose":"Calcium 500 mg + Magnesium 200 mg + Vitamin D 2000 IU daily ongoing. Reassess after 2-3 cycles.","why":"This combination consistently improves both physical (cramps, bloating, breast tenderness) and mood symptoms. Calcium regulates neuromuscular tone, magnesium aids cramp relief and fluid balance, and vitamin D supports hormonal regulation."},{"agent":"Fish Oil (Omega-3s)","dose":"1000-2000 mg EPA/DHA daily for 8 weeks.","why":"Omega-3s reduce systemic inflammation, improve mood, and lessen pain, often reducing the need for NSAIDs during the luteal phase of the cycle."},{"agent":"Herbal Formula with Cimicifuga, Viburnum, Hypericum","dose":null,"why":"1-2 mL tincture BID during luteal phase or continuously. Begin 14 days before menses and repeat monthly. Cimicifuga modulates estrogen, Viburnum acts as an antispasmodic for uterine cramps, and Hypericum supports mood regulation, especially in cases with emotional symptoms or PMDD tendencies."},{"agent":"Matricaria chamomilla herbal tea","dose":null,"why":"1 cup (8 oz) TID as needed during symptomatic day during the luteal phase or acutely Chamomile calms the nervous system, reduces anxiety and irritability, and has mild antispasmodic properties supportive for easing cramping."}],"notes":null,"flag":null},{"id":"endometriosis","title":"Endometriosis","condition":"Endometriosis","background":"Endometriosis is a chronic gynecological condition characterized by the presence of functional endometrial-like tissue outside the uterine cavity, most commonly on the ovaries, pelvic peritoneum, and fallopian tubes. Its exact etiology is unclear, but proposed mechanisms include retrograde menstruation, coelomic metaplasia, and immune dysfunction. Endometriosis affects approximately 10% of reproductive-aged women and is particularly prevalent in those with infertility or chronic pelvic pain. Pathophysiologically, ectopic endometrial implants respond to hormonal cycles, leading to inflammation, scarring, and adhesions. Clinical presentation includes dysmenorrhea, chronic pelvic pain, dyspareunia, infertility, and sometimes bowel or urinary symptoms. Differential diagnoses include pelvic inflammatory disease, irritable bowel syndrome, ovarian cysts, and fibroids. Diagnosis is suspected clinically and confirmed by laparoscopy with biopsy. Management includes NSAIDs, hormonal therapies (eg, combined oral contraceptives, GnRH agonists), and surgical removal of lesions for pain or fertility preservation. Prognosis varies; while symptoms can often be managed effectively, recurrence is common. Complications may include infertility, adhesions, & significant decreased quality of life.","steps":[{"agent":"Melatonin","dose":"10 mg daily at bedtime for 12 weeks","why":"Melatonin reduces pelvic pain, suppresses estrogen levels, improves sleep, and may lower oxidative stress. It’s especially useful for endometriosis-associated insomnia and pain control."},{"agent":"Vitamin E + Vitamin C","dose":"Vitamin E 1200 IU + Vitamin C 1000 mg daily for 12 weeks","why":"This antioxidant combo has been shown to reduce chronic pelvic pain and inflammation, particularly when taken consistently. It may help decrease the intensity of dysmenorrhea and the need for analgesics."},{"agent":"Diosmin","dose":"500 mg twice daily for 3 months","why":"Diosmin is a flavonoid that improves microcirculation and reduces pelvic congestion and inflammation. It has shown efficacy in relieving pain associated with endometriosis."},{"agent":"Anti-inflammatory Diet + Omega-3s","dose":"Fish oil 1000mg EPA/DHA daily","why":"Consume 1 serving of fatty fish (eg. salmon, sardines) or 1-2 tbsp ground flax/chia seeds daily A plant-forward, low-fat, high-fruit/vegetable diet with omega-3s helps modulate systemic inflammation, reduce prostaglandin activity, and ease menstrual cramps and pelvic pain."}],"notes":"This integrative plan emphasizes reducing systemic inflammation, oxidative stress, and estrogenic load - all central to endometriosis pathology. Lifestyle strategies such as pelvic physical therapy, stress reduction, and avoidance of xenoestrogens are encouraged to further support hormonal balance. Monitor symptom progression. OB- GYN referral may be indicated if fertility concerns or refractory pain arise.","flag":null},{"id":"polycystic-ov-ary-syndrome-pcos","title":"Polycystic Ovary Syndrome (PCOS)","condition":"Polycystic ovary syndrome","background":"Polycystic ovary syndrome (PCOS) is a common endocrine disorder characterized by chronic anovulation, hyperandrogenism, and polycystic ovaries on ultrasound. The etiology is multifactorial, involving genetic predisposition, insulin resistance, and hormonal imbalances. PCOS affects approximately 6-12% of reproductive-aged women and is a leading cause of infertility. Pathophysiologically, insulin resistance promotes excess ovarian androgen production, disrupting follicular development and ovulation. Clinical features include irregular or absent menses, hirsutism, acne, obesity, and polycystic ovaries. Differential diagnoses include hypothyroidism, hyperprolactinemia, non-classic congenital adrenal hyperplasia, and androgen-secreting tumors. Diagnosis is based on the Rotterdam criteria (two of three: oligo/ anovulation, hyperandrogenism, polycystic ovaries). Management includes lifestyle modification, hormonal contraceptives to regulate menses, and metformin for insulin sensitivity. Prognosis is variable; while symptoms can often be managed, complications include infertility, type 2 diabetes, endometrial hyperplasia, and cardiovascular risk.","steps":[{"agent":"Myo-Inositol + Folic Acid","dose":"2-4 g/day Myo-inositol + 200-400 mcg folic acid, daily for 3-6 months","why":"Myo-inositol improves insulin sensitivity, lowers testosterone, and promotes ovulation, making it especially useful in patients with irregular cycles and fertility concerns. It also enhances oocyte quality and may improve SHBG levels."},{"agent":"N-Acetyl Cysteine (NAC)","dose":"600 mg three times daily or 1200 mg twice daily for 8-12 weeks","why":"NAC enhances insulin sensitivity and ovulation, and has shown benefit when combined with ovulation-inducing agents like letrozole. Its antioxidant properties support ovarian health and reduce inflammation."},{"agent":"Calcium + Vitamin D","dose":"Calcium 500 mg + Vitamin D 600-1000 IU daily for at least 3 months","why":"This combo has been shown to improve menstrual regularity, reduce androgen excess, and support ovulation. It may also help reduce inflammation and improve insulin sensitivity in vitamin D-deficient patients."},{"agent":"Low-Glycemic Plant-Forward Diet + Exercise","dose":"≥150 minutes/week of moderate activity + sustainable low-GI or DASH-style diet focused on fiber, legumes, and","why":""},{"agent":"soy protein","dose":null,"why":"Diet and exercise are the first-line interventions to reduce weight, improve insulin sensitivity, regulate cycles, and lower cardiometabolic risk. Replacing red meat with plant proteins (eg. lentils, beans, soy) improves glucose and testosterone levels."}],"notes":"This foundational plan targets the core drivers of PCOS - insulin resistance, inflammation, and hormonal imbalance - through evidence-based diet, nutrients, and metabolic support. Consistency and sustainable lifestyle change are key. Monitor ovulation and cardiometabolic markers over time, and consider adding omega-3s or CoQ10 if fertility, lipid abnormalities, or menstrual irregularities persist.","flag":null},{"id":"allergies","title":"Allergies","condition":"Allergic rhinitis","background":"Allergies are hypersensitive immune responses to typically harmless substances (allergens) such as pollen, dust mites, foods, or medications. Etiology involves genetic predisposition and environmental exposures that trigger exaggerated IgE- mediated immune reactions. Allergic conditions are highly prevalent, affecting up to 30% of adults and 40% of children globally, with increasing incidence in industrialized nations. Pathophysiologically, allergens activate mast cells via allergen-specific IgE, leading to histamine and cytokine release that causes inflammation and tissue irritation. Clinical manifestations vary by system and include rhinitis, conjunctivitis, urticaria, eczema, wheezing, or anaphylaxis. Differential diagnoses depend on the organ system and include viral infections, asthma, contact dermatitis, or food intolerances. Diagnosis is based on clinical history, skin prick testing, or specific IgE blood tests. Management includes allergen avoidance, antihistamines, corticosteroids, leukotriene receptor antagonists, and immunotherapy. Prognosis is generally favorable with management, though complications may include chronic sinusitis, asthma, or life-threatening anaphylaxis in severe cases.","steps":[{"agent":"Quercetin + Vitamin C","dose":"Quercetin 500 mg twice daily + Vitamin C 1000 mg twice daily, ongoing during allergy season","why":"Quercetin stabilizes mast cells and reduces histamine release, while vitamin C enhances its absorption and independently lowers circulating histamine levels. This combo effectively addresses symptoms of sneezing, itching, and congestion."},{"agent":"Urtica dioica (Nettle)","dose":null,"why":"300 mg daily freeze-dried leaf for 8 weeks Nettle has antihistamine and anti-inflammatory effects, making it ideal for acute seasonal allergy relief. It can be used alongside conventional antihistamines or other natural therapies."},{"agent":"MSM (Methylsulfonylmethane)","dose":"3000 mg daily (divided into 2 doses) for 4 weeks","why":"MSM reduces nasal congestion, itching, and rhinorrhea, as shown in clinical trials. It supports mucosal integrity and reduces oxidative stress associated with allergic responses."},{"agent":"Probiotics (Lactobacillus + Bifidobacterium)","dose":"5-10 billion CFU/day for at least 8 weeks","why":"Probiotics help regulate immune function, reduce Th2-skewed allergic responses, and improve nasal and ocular symptoms. Choose a well-researched multi-strain formula with proven respiratory tract benefits."}],"notes":"This plan addresses both acute symptom relief and long-term immune modulation. Combine targeted supplements with dietary flavonoids, vitamin C-rich foods, and environmental control measures (eg. HEPA filters, bedding hygiene). Consider evaluating food sensitivities or oral allergy syndrome in persistent or atypical cases. Regular use of these interventions can significantly improve symptom control and reduce reliance on antihistamines.","flag":"Filed under Allergic rhinitis; the protocol is written for allergy generally."},{"id":"upper-respiratory-infections","title":"Upper Respiratory Infections","condition":"Common cold","background":"Upper respiratory infections (URIs) are acute infections involving the nose, sinuses, pharynx, or larynx, commonly referred to as the common cold. They are most often caused by viruses such as rhinovirus, coronavirus, adenovirus, or respiratory syncytial virus. URIs are highly prevalent worldwide, especially in children who may experience 6-8 episodes annually, and are a leading cause of missed work and school days. Pathophysiologically, viral invasion of the respiratory mucosa triggers local inflammation, mucus production, and immune activation. Symptoms typically include nasal congestion, rhinorrhea, sore throat, cough, low-grade fever, and malaise. Differential diagnoses include allergic rhinitis, influenza, streptococcal pharyngitis, and sinusitis. Diagnosis is clinical, based on symptom pattern and duration. Management is supportive, including rest, hydration, saline nasal irrigation, and over-the-counter analgesics or decongestants. Antibiotics are not indicated unless bacterial superinfection is suspected. Prognosis is excellent, with most cases resolving within 7-10 days. Complications are rare but may include secondary bacterial sinusitis, otitis media, or bronchitis.","steps":[{"agent":"Zinc Lozenges","dose":"Zinc gluconate 25mg TID starting within 24 hours of symptom onset for up to 5 days","why":"Zinc supports antiviral immunity and may reduce URI duration by inhibiting viral replication in the oropharynx. Lozenges are most effective when started early and used consistently."},{"agent":"Vitamin C","dose":"1000 mg twice daily for 5-10 days","why":"Vitamin C has mild antiviral and antioxidant properties and can modestly reduce the duration and severity of URIs, especially in individuals under physical or oxidative stress."},{"agent":"Demulcent Herbal Tea + Honey","dose":"Sip warm infusions of Althaea officinalis + Glycyrrhiza glabra + honey 3x daily PRN","why":"These botanicals soothe irritated mucosa, relieve sore throat, and reduce cough. Honey also provides antimicrobial and cough-suppressing benefits."},{"agent":"Immune Soup","dose":"Consume 1 cup of warm soup as needed up to 4x daily","why":"Ingredients: ½ yellow onion (chopped), 4 garlic cloves (minced), 1 tbsp fresh ginger (grated), ½ cup shiitake mushrooms"},{"agent":"(sliced), 1 lemon (juiced), 2 tbsp chopped parsley, 1 carrot (sliced)","dose":null,"why":"Instructions: Simmer all ingredients for 20-30 minutes, season with sea salt and optionally cayenne. This immunostimulating soup provides immune-enhancing polysaccharides, sulfur compounds, antioxidants, and warmth to support mucosal defenses and recovery."}],"notes":"This URI plan combines symptom relief with immune modulation through food, botanicals, and targeted nutrients. Encourage rest, hydration, and early initiation of zinc and vitamin C for best results. Reassure patients of the self-limiting nature of most viral URIs, and refer for medical evaluation if red flags arise (eg. worsening symptoms, high fever >3 days, difficulty breathing, or immunocompromised status).","flag":"Filed under Common cold; the protocol covers upper respiratory infection broadly."},{"id":"osteoarthritis-oa","title":"Osteoarthritis (OA)","condition":"Osteoarthritis","background":"Osteoarthritis (OA) is a chronic, degenerative joint disease characterized by progressive loss of articular cartilage, subchondral bone remodeling, and osteophyte formation. It is primarily caused by mechanical wear and tear, but risk factors include aging, joint overuse, obesity, previous injury, and genetic predisposition. OA is the most common form of arthritis, affecting over 32 million adults in the United States, particularly those over 50. Pathophysiologically, cartilage breakdown leads to joint space narrowing, inflammation, and bony changes that cause pain and reduced mobility. Clinically, OA presents with joint pain worsened by activity and relieved by rest, morning stiffness lasting less than 30 minutes, crepitus, and limited range of motion - commonly affecting knees, hips, hands, and spine. Differential diagnoses include rheumatoid arthritis, gout, bursitis, and referred pain. Diagnosis is clinical, supported by imaging (X-ray showing joint space narrowing, osteophytes) and exclusion of inflammatory markers. Management includes weight loss, physical therapy, NSAIDs, intra-articular corticosteroids, and joint replacement in advanced cases. Prognosis is variable; while OA is non-fatal, it can lead to significant disability. Complications include chronic pain, reduced quality of life, and loss of joint function.","steps":[{"agent":"Glucosamine + Chondroitin + MSM Combo","dose":"Glucosamine sulfate 1500 mg + Chondroitin sulfate 1200 mg + MSM 1000 mg daily for 12 weeks","why":"This combination supports cartilage integrity, reduces joint stiffness, and has mild to moderate pain-relieving effects. MSM adds anti-inflammatory synergy and is generally well-tolerated."},{"agent":"Mediterranean Diet + Cherry Intake","dose":null,"why":"Adopt Mediterranean dietary pattern and consume ~12 cherries or 4 oz tart cherry juice (low sugar) daily This diet reduces systemic inflammation and metabolic burden on joints, while cherries may lower CRP and joint pain via antioxidant and anti-inflammatory polyphenols."},{"agent":"Bromelain","dose":"500 mg BID on an empty stomach for 2 weeks","why":"Bromelain is a proteolytic enzyme with fast-acting anti-inflammatory and analgesic properties, making it useful for acute OA flares or as an NSAID alternative."},{"agent":"Low-Impact Exercise + Weight Loss Goals","dose":"150+ minutes/week of low-impact movement (eg. swimming, cycling, walking)","why":"Aim for 5-10% weight loss over 6-12 months Exercise improves joint mobility and function, while even modest weight loss significantly reduces pain and inflammatory markers in overweight individuals with OA."}],"notes":"This integrative plan addresses OA from multiple angles - structural support, inflammation, metabolism, and physical function. Dietary changes and movement are foundational, while evidence-based supplements like glucosamine, MSM, and bromelain enhance symptom relief. Reinforce that consistent, joint-friendly activity and long-term weight loss are central to slowing OA progression.","flag":null},{"id":"gout","title":"Gout","condition":"Gout","background":"Gout is a form of inflammatory arthritis caused by monosodium urate crystal deposition in joints due to chronic hyperuricemia. Etiologies include genetic predisposition, high purine intake (eg, red meat, alcohol), obesity, renal insufficiency, and medications such as diuretics. Gout affects about 4% of U.S. adults, with higher prevalence in men and postmenopausal women. Pathophysiologically, excess serum uric acid leads to crystal precipitation in joints, triggering intense neutrophilic inflammation. It classically presents as sudden, severe pain, redness, and swelling in a single joint - most commonly the first metatarsophalangeal joint (podagra). Differential diagnoses include septic arthritis, pseudogout, cellulitis, and rheumatoid arthritis. Diagnosis is confirmed by joint aspiration showing negatively birefringent urate crystals; serum uric acid levels and imaging may support the diagnosis. Management includes NSAIDs, colchicine, or corticosteroids for acute flares, and urate-lowering therapy (eg, allopurinol) for long-term prevention. Prognosis is good with adherence to therapy, but complications include tophi, joint destruction, and chronic arthritis if poorly managed.","steps":[{"agent":"Hydration + Cherry Intake","dose":"Drink 2-3 liters of water daily + consume 10-12 cherries daily","why":"Adequate hydration enhances renal excretion of uric acid, while cherries reduce serum uric acid and flare frequency through anti-inflammatory and antioxidant effects."},{"agent":"Quercetin + Vitamin C","dose":"Quercetin 500 mg/day + Vitamin C 500 mg/day for ongoing support","why":"Quercetin inhibits xanthine oxidase, lowering uric acid production, while vitamin C modestly enhances uric acid excretion. Both are also present in cherries and support flare prevention."},{"agent":"DASH Diet with Low-Purine Emphasis","dose":null,"why":"Adopt a DASH-style diet emphasizing vegetables, legumes, low-fat dairy, and whole grains. Avoid consuming organ meats, beer, and high-fructose foods. This dietary pattern directly addresses both triggers and contributors to gout flares."},{"agent":"Weight Loss for Overweight Patients","dose":null,"why":"Aim for 5% body weight loss over 3-6 months through whole-food eating and low-impact exercise. Weight reduction helps to significantly lower uric acid, thereby reducing the frequency of gout attacks, especially in metabolically active individuals."}],"notes":"This plan targets gout from both preventative and symptomatic angles by reducing uric acid production and enhancing excretion. Cherries, hydration, and quercetin offer natural alternatives to pharmacologic urate-lowering therapy, especially in early or mild cases. Emphasize gradual dietary shifts and flare prevention education for long-term success.","flag":null},{"id":"osteoporosis","title":"Osteoporosis","condition":"Osteoporosis","background":"Osteoporosis is a skeletal disorder characterized by reduced bone mass and microarchitectural deterioration, leading to increased bone fragility and fracture risk. It most commonly results from aging, estrogen deficiency (especially postmenopause), chronic glucocorticoid use, or nutritional deficiencies in calcium and vitamin D. Osteoporosis affects over 10 million people in the U.S., with higher prevalence in postmenopausal women and older adults. Pathophysiologically, an imbalance between bone resorption and formation leads to porous, weakened bone. Osteoporosis is often asymptomatic until a fracture occurs, typically in the hip, vertebrae, or wrist. Differential diagnoses include osteomalacia, multiple myeloma, and metastatic bone disease. Diagnosis is made via dual-energy X-ray absorptiometry (DEXA) scan showing a T-score ≤ -2.5. Management includes weight-bearing exercise, calcium (1000-1200 mg/day), vitamin D (800-1000 IU/day), bisphosphonates, and fall prevention strategies. Prognosis is favorable with early intervention, but complications such as fragility fractures, chronic pain, loss of independence, and increased mortality (especially with hip fractures) are significant concerns.","steps":[{"agent":"Cal/Mag/D/K Combo Supplement","dose":"Calcium 500 mg + Magnesium 400 mg + Vitamin D3 1000 IU + Vitamin K2 200 mcg daily","why":"This foundational combo supports bone mineralization, calcium absorption, and regulation of calcium into the bone matrix. K2 specifically activates osteocalcin, directing calcium into bone and away from arteries."},{"agent":"Weight-Bearing & Resistance Exercise","dose":"Walk 30 minutes at least 5x/week + resistance training 2-3x/week","why":"Mechanical loading stimulates osteoblast activity and improves bone density, while resistance and balance training reduce fracture risk by improving muscle strength and fall prevention."},{"agent":"Mediterranean-Style Diet + Bone-Specific Foods","dose":null,"why":"Emphasize yogurt, leafy greens, legumes, nuts, soy foods, olive oil, and fish. Limit alcohol to 1-2 drinks daily. This pattern provides key nutrients like calcium, magnesium, protein, and phytoestrogens (from soy), supporting bone mineral density (BMD) and reducing inflammation-related bone loss."},{"agent":"Strontium Citrate","dose":"680 mg/day for at 6 months in mild to moderate osteoporosis","why":"Strontium mimics calcium in bone and may enhance bone formation while reducing resorption. It has shown promising results in improving BMD when used adjunctively."}],"notes":"This plan integrates diet, movement, and supplementation to address the multifactorial nature of osteoporosis. Prioritize food-based calcium and magnesium, and use a targeted supplement when needed. Encourage lifelong weight-bearing movement, especially in postmenopausal women. Monitor BMD periodically, and reinforce the importance of fall prevention strategies to preserve independence as well as overall quality of life.","flag":null},{"id":"attention-deficit-disorder","title":"Attention Deficit Disorder","condition":"Attention deficit disorder","background":"Attention Deficit Disorder (ADD), now classified under Attention-Deficit/Hyperactivity Disorder (ADHD), predominantly inattentive presentation, is a neurodevelopmental disorder marked by persistent patterns of inattention that interfere with daily functioning. Etiology is multifactorial, involving genetic predisposition, neurochemical imbalances (especially dopamine and norepinephrine), and environmental factors such as prenatal exposures or early adversity. ADHD affects about 5-10% of children and 2-5% of adults, with ADD more common in females and often underdiagnosed due to its less overt hyperactivity. Pathophysiologically, dysregulation in fronto-striatal circuits and neurotransmitter signaling impairs executive functioning and attention regulation. Clinical features include distractibility, forgetfulness, disorganization, poor task follow-through, and difficulty sustaining attention, often emerging before age 12. Differential diagnoses include anxiety, depression, learning disorders, and thyroid dysfunction. Diagnosis is clinical, based on DSM-5 criteria, corroborated by behavioral scales and input from multiple settings (eg, school, home). Management includes behavioral therapy, academic accommodations, and pharmacologic treatment - typically stimulants like methylphenidate or non-stimulants such as atomoxetine. Prognosis is variable; many symptoms improve with age, but untreated can lead to academic underachievement, low self-esteem, and functional impairments.","steps":[{"agent":"Omega-3 Fatty Acids","dose":"EPA dominant omega-3 fatty acid 3 grams daily for 12 weeks","why":"EPA-rich omega-3s support cognitive function, reduce inattention, and modulate dopamine transmission. Algae-based EPA is a good vegetarian option and shows mild but consistent benefit in symptom reduction."},{"agent":"Zinc + Magnesium Supplementation","dose":"Zinc 15 mg twice daily + Magnesium 200 mg daily for 12 weeks","why":"Zinc enhances the effectiveness of stimulant medications and supports neurotransmitter activity, while magnesium contributes to neurological stability and may reduce restlessness and irritability symptoms."},{"agent":"Feingold or Elimination Diet","dose":null,"why":"Remove artificial additives and trial elimination of common triggers (dairy, wheat, soy) for 4 weeks. Removing synthetic dyes and preservatives can reduce hyperactivity in sensitive individuals. Elimination diets may identify food sensitivities that contribute to attention or behavior issues - reintroduce foods one at a time to monitor response."},{"agent":"Vitamin D Supplementation","dose":"Vitamin D 2000 IU/day for 3 months","why":"Vitamin D plays a role in brain development and has shown small but meaningful benefits when used in combination with stimulant medications. Deficiency is common and easy to address with safe daily dosing."}],"notes":"This integrative plan supports attention and behavior by targeting nutrient deficiencies, inflammatory dietary triggers, and neurocognitive support. Avoid artificial additives, support a whole-food diet, and consider gentle lifestyle strategies like regular outdoor time and reducing toxin exposure (lead, tobacco). Individual responses vary - consistent observation and support are key. Always collaborate with mental health professionals for diagnosis and medication guidance.","flag":null},{"id":"migraine","title":"Migraine","condition":"Migraine","background":"Migraine is a chronic neurological disorder characterized by recurrent moderate to severe headaches, often unilateral and pulsating, typically lasting 4-72 hours and associated with nausea, photophobia, and phonophobia. Etiology involves genetic predisposition and environmental triggers such as stress, hormonal fluctuations, certain foods, and sleep disturbances. Migraine affects approximately 12% of the global population, with higher prevalence in women, especially during reproductive years. Pathophysiologically, migraines involve cortical spreading depression, trigeminovascular system activation, and neuroinflammation, leading to the release of vasoactive peptides like CGRP. Clinical presentation may include a prodrome, aura (in about 25% of patients), the headache phase, and postdrome. Differential diagnoses include tension-type headache, cluster headache, sinusitis, and intracranial pathology. Diagnosis is clinical, based on the International Classification of Headache Disorders criteria. Management includes trigger avoidance, lifestyle modification, acute treatments (eg, NSAIDs, triptans), and preventive therapies (eg, beta-blockers, topiramate, CGRP antagonists). Prognosis varies; many experience episodic migraines manageable with treatment, but some progress to chronic migraine. Complications may include reduced quality of life as well as comorbid anxiety and/or depression.","steps":[{"agent":"Riboflavin + Magnesium + CoQ10","dose":"Riboflavin 400 mg + Magnesium 600 mg + CoQ10 150 mg daily for prevention for 3 months","why":"This trio supports mitochondrial function, reduces neuronal excitability, and lowers migraine frequency and severity. These nutrients are among the most evidence-supported for migraine prevention."},{"agent":"Zingiber officinale (Ginger)","dose":"500-1000 mg extract at onset of migraine; repeat in 4 hours if needed","why":"Ginger acts as an anti-inflammatory and anti-nausea agent, offering safe and effective acute migraine relief."},{"agent":"Melatonin","dose":"3 mg daily at bedtime for ongoing preventative support","why":"Melatonin helps regulate circadian rhythms and supports sleep quality, which can reduce migraine frequency, especially among individuals with insomnia or irregular sleep patterns."},{"agent":"Nutrition + Trigger Avoidance","dose":null,"why":"Emphasize an anti-inflammatory whole foods diet. Avoid skipping meals. Avoid known personal triggers. Eating meals consistently and emphasizing nutrient-dense foods help stabilize blood sugar and reduce inflammation. Identifying and eliminating triggers (especially common dietary triggers including wine, chocolate, aged cheese, artificial sweeteners) can significantly reduce migraine attack frequency and severity."}],"notes":"This plan combines prevention and acute care through nutrient therapy, botanicals, and lifestyle changes. Begin with targeted daily supplements and encourage patients to track symptoms and triggers with a migraine diary. Address sleep, stress, and diet patterns alongside natural therapies for optimal long-term success. Consider referring for advanced care if migraines become chronic or disabling.","flag":null},{"id":"seizures","title":"Seizures","condition":"Seizure disorder","background":"A seizure is a transient episode of abnormal, excessive, or synchronous neuronal activity in the brain, leading to changes in behavior, sensation, movement, or consciousness. Etiologies include epilepsy, head trauma, stroke, brain tumors, infections, metabolic disturbances (eg, hypoglycemia, hyponatremia), and drug or alcohol withdrawal. Seizures affect about 8-10% of people at some point in life, with epilepsy diagnosed when two or more unprovoked seizures occur. Pathophysiologically, seizures result from an imbalance between excitatory and inhibitory neural signals, often involving glutamate and GABA pathways. Clinical presentation varies by type: generalized seizures may involve tonic-clonic movements and loss of consciousness, while focal seizures can present with localized motor activity, sensory changes, or altered awareness. Differential diagnoses include syncope, transient ischemic attack, migraine, and psychogenic non- epileptic seizures. Diagnosis is based on clinical history, EEG, and neuroimaging to identify underlying causes. Management includes treating the underlying cause, antiepileptic drugs (eg, levetiracetam, valproate), and lifestyle modifications to reduce triggers. Prognosis depends on the cause and seizure control; while many achieve good control with medication, complications can include status epilepticus, injury during seizures, and psychosocial impacts.","steps":[{"agent":"Ketogenic Diet","dose":null,"why":"Adopt a classic ketogenic diet consisting of about 89% fat, 8% protein, 3% carbs Initiate this under clinical supervision with multivitamin, calcium, vitamin D, and trace mineral support. The ketogenic diet alters brain energy metabolism and increases GABA, thereby reducing seizure frequency, especially effective in intractable epilepsy. Monitor for nutrient deficiencies and potential side effects."},{"agent":"Vitamin D + Magnesium","dose":"Vitamin D3 2000 IU/day (adjust dose based on labs) + Magnesium glycinate 400 mg/day ongoing","why":"Vitamin D repletion supports neurologic function and may reduce seizure frequency in deficient individuals. Magnesium is essential for membrane stability and neuronal excitability, especially on keto diets."},{"agent":"Carnitine","dose":"500 mg/day of L-carnitine for those on valproic acid taken ongoing as needed","why":"Valproate depletes carnitine, contributing to fatigue and potential hepatotoxicity. Supplementing carnitine can reduce side effects and support mitochondrial function."},{"agent":"Vitamin E","dose":"400-800 IU/day of mixed tocopherols for 3 months","why":"Vitamin E acts as an antioxidant and may reduce seizure frequency by decreasing oxidative stress in the brain, particularly in patients presenting with idiopathic or medication-resistant epilepsy."}],"notes":"This integrative plan supports neurologic stability through diet, targeted nutrients, and coordination with medical care. The ketogenic diet remains the most evidence-based non-pharmaceutical option for refractory epilepsy. Supplementation should be personalized and carefully monitored, particularly when anticonvulsants are used. Always collaborate with neurology before initiating significant dietary or supplement changes.","flag":null},{"id":"multiple-sclerosis","title":"Multiple Sclerosis","condition":"Multiple sclerosis","background":"Multiple sclerosis (MS) is a chronic autoimmune demyelinating disease of the central nervous system characterized by recurrent episodes of neurologic dysfunction due to immune-mediated destruction of myelin and axons. The exact etiology is unknown but involves a combination of genetic susceptibility and environmental triggers, such as Epstein-Barr virus and low vitamin D levels. MS affects about 2.8 million people worldwide, with higher prevalence in women and individuals of northern European descent, typically presenting between ages 20-40. Pathophysiologically, autoreactive lymphocytes cross the blood-brain barrier, leading to demyelination, inflammation, and eventual neurodegeneration. Clinical presentation varies but may include optic neuritis, limb weakness, sensory disturbances, ataxia, bladder dysfunction, and fatigue. The disease may follow a relapsing-remitting, secondary progressive, or primary progressive course. Differential diagnoses include neuromyelitis optica, lupus, B12 deficiency, and stroke. Diagnosis relies on clinical features, MRI showing demyelinating lesions, and CSF analysis with oligoclonal bands. Management includes acute relapse treatment with corticosteroids, disease-modifying therapies (eg, interferons, monoclonal antibodies), and symptomatic support. Prognosis varies, with most patients experiencing gradual decline over decades. Complications include mobility loss, cognitive impairment, depression, and reduced quality of life.","steps":[{"agent":"Vitamin D3","dose":"2000 IU/day (adjust as necessary to maintain ~45 ng/mL serum level)","why":"Vitamin D modulates immune function, reduces pro-inflammatory cytokines, and may lower relapse rates. Deficiency is strongly linked to increased disease activity and disability progression."},{"agent":"Omega-3 Fatty Acids","dose":"2 grams omega-3 (combined EPA + DHA) taken daily for 6 months","why":"Omega-3s reduce inflammation, improve neuronal membrane health, and may decrease relapse frequency. Dietary sources including fatty fish, flax, and chia are also encouraged to incorporate into your diet."},{"agent":"Alpha-Lipoic Acid (ALA)","dose":"1200 mg/day for 6 months","why":"ALA acts as a potent antioxidant and has been shown to slow brain atrophy and improve mobility in secondary progressive MS. It also supports mitochondrial function and reduces oxidative stress."},{"agent":"Acetyl-L-Carnitine + CoQ10","dose":"Acetyl-L-Carnitine 1000 mg twice daily + CoQ10 300 mg daily","why":"This combination improves cellular energy production and reduces MS-related fatigue and depression. Both support mitochondrial health, which is often impaired in MS."}],"notes":"This plan emphasizes immune modulation, neuroprotection, and fatigue reduction through targeted nutrients and dietary patterns such as the Mediterranean diet. Lifestyle interventions like yoga, mindfulness, and stress management further support symptom control and quality of life. Regular monitoring of vitamin D levels, B12 status, and overall diet quality is recommended to optimize long-term outcomes.","flag":null},{"id":"parkinson-s","title":"Parkinson’S","condition":"Parkinson's disease","background":"Parkinson’s disease is a progressive neurodegenerative disorder characterized by motor and non-motor symptoms resulting from the loss of dopaminergic neurons in the substantia nigra of the basal ganglia. Its etiology is multifactorial, involving genetic mutations (eg, LRRK2, P ARK7) and environmental exposures (eg, pesticides, heavy metals). It affects approximately 1% of individuals over age 60, with higher prevalence in men. Pathophysiologically, dopamine deficiency disrupts the regulation of movement and leads to the hallmark motor symptoms: resting tremor, bradykinesia, rigidity, and postural instability. Non-motor features include constipation, anosmia, depression, cognitive decline, and sleep disturbances. Differential diagnoses include essential tremor, multiple system atrophy, progressive supranuclear palsy, and drug-induced parkinsonism. Diagnosis is clinical, based on history and neurologic exam, with supportive imaging like DaTscan if needed. Management includes dopaminergic therapies (eg, levodopa/carbidopa), MAO-B inhibitors, physical therapy, and deep brain stimulation in advanced cases. Prognosis is variable; although not fatal, Parkinson’s leads to progressive disability. Complications include falls, aspiration pneumonia, dementia, and loss of independence.","steps":[{"agent":"Vitamin B12 + B6","dose":"B12 1000 mcg/day sublingual methylcobalamin + B6: 50 mg/day (only if not on levodopa)","why":"Long-term levodopa use can deplete B12 and alter B6 metabolism, increasing risk for neuropathy and worsening cognitive symptoms. Supplementing supports nerve health and methylation balance."},{"agent":"Protein Timing + Levodopa Spacing Strategy","dose":null,"why":"Limit protein intake to dinner. Take levodopa 30 minutes before or 60 minutes after meals. Competing amino acids interfere with levodopa absorption, so strategic protein timing enhances medication efficacy as well as symptom control."},{"agent":"Melatonin","dose":"3 mg daily at bedtime for 8 weeks","why":"Melatonin improves sleep onset and quality, which can be significantly impaired in Parkinson’s. It also provides some mild antioxidant and neuroprotective benefits."},{"agent":"Probiotics + Fiber for Constipation","dose":null,"why":"Probiotic dose: Lactobacillus + Bifidobacterium strains aiming for 5-10 billion CFU/day Fiber dose: 1 tbsp ground flaxseed daily for 12 weeks Constipation is a common non-motor symptom. This combination of probiotics and fiber aims to support gut motility, microbiome balance, and stool regularity."}],"notes":"This plan addresses motor and non-motor symptoms while enhancing medication effectiveness and quality of life. Emphasize a Mediterranean-style diet with adequate hydration, organic produce, and reduced pesticide exposure. Avoid iron and fava beans near levodopa dosing, and monitor bone health proactively. Nutritional strategies should complement (but not replace) conventional treatment, in close coordination with neurology.","flag":null},{"id":"alzheimer-s","title":"Alzheimer’S","condition":"Cognitive decline","background":"Alzheimer’s disease is a progressive neurodegenerative disorder and the most common cause of dementia, characterized by gradual cognitive decline affecting memory, language, and executive function. The etiology is multifactorial, involving genetic factors (eg, APOE ε4 allele), age-related neuronal changes, and environmental influences. Alzheimer’s affects over 6 million Americans, primarily those over 65, with risk increasing with age. Pathophysiologically, the disease is marked by accumulation of beta-amyloid plaques and neurofibrillary tangles composed of hyperphosphorylated tau protein, leading to synaptic dysfunction and neuronal loss, especially in the hippocampus and cortex. Clinically, it presents with progressive memory loss, difficulty with language, impaired judgment, and later, behavioral changes and loss of daily functioning. Differential diagnoses include vascular dementia, Lewy body dementia, frontotemporal dementia, and depression. Diagnosis is clinical, supported by cognitive testing (eg, MMSE, MoCA), MRI, and sometimes PET imaging or CSF biomarkers. Management focuses on symptom control and slowing progression using cholinesterase inhibitors (eg, donepezil) and NMDA receptor antagonists (eg, memantine), along with supportive care. Prognosis is poor, with average survival of 4-8 years after diagnosis. Complications include complete dependence, malnutrition, infections, and death, often from aspiration pneumonia.","steps":[{"agent":"Phosphatidylserine","dose":"100 mg TID for 12 weeks","why":"Phosphatidylserine supports neuronal membrane fluidity and neurotransmitter signaling, which may help stabilize mood and cognitive function in early-stage Alzheimer’s."},{"agent":"Vitamin E","dose":"2000 IU daily (mixed tocopherols) for 16 weeks","why":"Vitamin E functions as an antioxidant and has been shown to modestly slow functional decline in Alzheimer’s, particularly in those with mild to moderate disease."},{"agent":"MIND Diet","dose":null,"why":"Adopt a MIND diet incorporating the following things into your daily nutrition: 1 serving leafy greens daily, 2 servings"},{"agent":"berries per week, fish 1-2x per week, and olive oil as primary fat. Reduce red meat and fried foods.","dose":null,"why":"This hybrid diet is associated with reduced Alzheimer’s risk and slower cognitive decline through antioxidant and anti- inflammatory dietary patterns."},{"agent":"Acetyl-L-Carnitine","dose":null,"why":"Dose 1g BID for 12 weeks Especially beneficial in younger or early-onset cases, acetyl-L-carnitine supports mitochondrial energy metabolism and may improve memory and cognitive processing speed."}],"notes":"This plan combines dietary, mitochondrial, and neuroprotective strategies to support cognition and daily function in Alzheimer’s disease. Care should be coordinated with neurology, and families should be supported with adequate education and planning. Lifestyle interventions are most effective when initiated early and sustained with consistency.","flag":"Filed under Cognitive decline, the nearest condition in this index."},{"id":"diabetes-mellitus-t2dm","title":"Diabetes Mellitus (T2DM)","condition":"Diabetes mellitus, type 2","background":"Type 2 diabetes mellitus (T2DM) is a chronic metabolic disorder characterized by insulin resistance and relative insulin deficiency, leading to hyperglycemia. Etiology involves genetic predisposition and lifestyle factors such as obesity, physical inactivity, and poor diet. T2DM accounts for over 90% of diabetes cases worldwide and is increasingly prevalent in both adults and adolescents, particularly in populations with higher rates of obesity and metabolic syndrome. Pathophysiologically, insulin resistance in muscle and liver tissues, combined with impaired pancreatic beta-cell function, disrupts glucose homeostasis. Clinical presentation may be insidious, with symptoms including polyuria, polydipsia, fatigue, blurred vision, and recurrent infections, though many cases are diagnosed incidentally. Differential diagnoses include type 1 diabetes, latent autoimmune diabetes in adults (LADA), and medication-induced hyperglycemia. Diagnosis is confirmed by elevated fasting glucose (≥126 mg/dL), HbA1c (≥6.5%), or 2-hour OGTT. Management includes lifestyle modifications, metformin as first-line pharmacotherapy, and additional agents (eg, GLP-1 agonists, SGLT2 inhibitors) as needed. Prognosis improves with glycemic control, but long-term complications can include cardiovascular disease, nephropathy, neuropathy, and retinopathy. T2DM Diagnostic Criteria: Fasting Plasma Glucose (FPG): Normal: <100 mg/dL || Pre-diabetes: 100-125 mg/dL || Diabetes: ≥126 mg/dL 2-hour OGTT (75g glucose): Normal: <140 mg/dL || Pre-diabetes: 140-199 mg/dL || Diabetes: ≥200 mg/dL Hemoglobin A1c: Normal: <5.7% || Pre-diabetes: 5.7-6.4% || Diabetes: ≥6.5% Random Plasma Glucose: Diabetes: ≥200 mg/dL with symptoms (no prediabetes range defined)","steps":[{"agent":"Berberine","dose":"500 mg three times daily with meals for 12 weeks","why":"Berberine improves insulin sensitivity and reduces hepatic glucose production. Its glucose-lowering effects are comparable to metformin, with added benefits on lipids and inflammation."},{"agent":"Fiber Loading + Flaxseed","dose":"7 grams fiber daily before each meal + 1 tbsp ground flaxseed daily for 8 weeks","why":"Pre-meal fiber slows glucose absorption and improves postprandial glycemic control. Flaxseed enhances insulin sensitivity and contributes to satiety and lipid balance."},{"agent":"Mediterranean Diet + Carb Counting","dose":null,"why":"Adopt a Mediterranean diet aiming for 45-60 grams of carbohydrates per meal. Emphasizing vegetables, legumes, whole grains, and fish reduces A1c and cardiovascular risk. Structured carb intake supports glycemic control and patient empowerment."},{"agent":"Alpha-Lipoic Acid","dose":null,"why":"600 mg twice daily for 12 weeks ALA improves diabetic neuropathy symptoms through antioxidants and mitochondrial support. It also modestly improves insulin sensitivity and oxidative stress."}],"notes":null,"flag":null},{"id":"coronary-artery-disease","title":"Coronary Artery Disease","condition":"Atherosclerosis","background":"Coronary artery disease (CAD) is a condition characterized by the narrowing or blockage of coronary arteries due to atherosclerosis, leading to reduced blood flow to the myocardium. Etiology involves modifiable risk factors such as hypertension, hyperlipidemia, smoking, diabetes, and sedentary lifestyle, as well as non-modifiable factors like age, male sex, and family history. CAD is the leading cause of death globally, particularly prevalent in individuals over 45 and those with metabolic syndrome. Pathophysiologically, endothelial injury triggers lipid accumulation, inflammation, and plaque formation in coronary vessels, which can rupture and cause thrombosis. Clinically, CAD presents with exertional chest pain (angina), dyspnea, or may be silent, especially in diabetics. Acute presentations include unstable angina or myocardial infarction. Differential diagnoses include aortic dissection, pericarditis, GERD, and pulmonary embolism. Diagnosis is made via ECG, stress testing, cardiac biomarkers, and coronary angiography. Management includes lifestyle changes, antiplatelet agents (aspirin), statins, beta-blockers, nitrates, and revascularization (PCI or CABG) when indicated. Prognosis varies with disease severity and treatment adherence; complications include heart failure, arrhythmias, myocardial infarction, and sudden cardiac death.","steps":[{"agent":"Mediterranean Diet","dose":"≥4 tbsp/day extra virgin olive oil, ≥5 servings/day of vegetables/fruits, legumes 4x/week, nuts daily, and fish 2x/","why":""},{"agent":"week on an ongoing basis.","dose":null,"why":"Rich in monounsaturated fats, antioxidants, and anti-inflammatory compounds, this diet reduces oxidative stress, lowers LDL, and improves endothelial function. It’s shown to reduce cardiovascular events by ~30%."},{"agent":"Red Yeast Rice (Monascus purpureus)","dose":"1200 mg twice daily for 3 months, then reassess lipids and liver enzymes.","why":"Monascus purpureus naturally contains monacolin K (a lovastatin analog) which inhibits HMG-CoA reductase, effectively lowering LDL cholesterol and improving lipid profiles."},{"agent":"Omega-3 Fatty Acids (EPA/DHA)","dose":"EPA 2 grams twice daily for at least 12 weeks. Ongoing in high-risk patients.","why":"Reduces triglycerides, stabilizes plaques, and offers anti-inflammatory and antithrombotic effects. Especially helpful for secondary prevention or elevated triglycerides."},{"agent":"Vitamin K2 (MK-7)","dose":"180 mcg/day (may titrate to 500 mcg/day) for at least 6 months. Ongoing if tolerated.","why":"Activates matrix Gla-protein (MGP), a key inhibitor of arterial calcification; useful for reducing vascular stiffness, particularly in aging populations or long-term statin users."}],"notes":"A whole-food, anti-inflammatory approach combined with targeted supplementation supports lipid control, plaque stabilization, and vascular integrity. Reinforce ≥150 minutes/week of moderate aerobic activity, smoking cessation, and regular monitoring of lipid panels and inflammation markers. Integrate care with conventional cardiology where appropriate.","flag":"Filed under Atherosclerosis, the nearest condition in this index."},{"id":"hypertension","title":"Hypertension","condition":"Hypertension","background":"Hypertension is defined as persistently elevated blood pressure, typically ≥130/80 mmHg, and is classified as either primary (essential) or secondary to underlying conditions such as renal disease, endocrine disorders, or medication use. Primary hypertension accounts for about 90-95% of cases and arises from a combination of genetic predisposition, high salt intake, obesity, stress, and sedentary lifestyle. It affects nearly half of adults in the United States and is a major risk factor for cardiovascular morbidity and mortality. Pathophysiologically, hypertension involves increased systemic vascular resistance due to dysregulation of vascular tone, the renin-angiotensin-aldosterone system, and sympathetic nervous system overactivity. Most patients are asymptomatic, but severe or prolonged hypertension may present with headaches, visual changes, or signs of end-organ damage. Differential diagnoses include white-coat hypertension, anxiety, and secondary causes like hyperaldosteronism or pheochromocytoma. Diagnosis requires consistent blood pressure measurements, often supplemented by ambulatory monitoring. Management focuses on lifestyle modifications (dietary sodium restriction, weight loss, exercise) and pharmacologic therapy (thiazide diuretics, ACE inhibitors, ARBs, calcium channel blockers). Prognosis is good with treatment but uncontrolled hypertension can lead to complications such as stroke, myocardial infarction, chronic kidney disease, and heart failure. American Heart Association Blood Pressure Reference Ranges: Hypertensive Urgency = BP ≥180/120 mmHg • Without signs of acute target organ damage • Symptoms may include headache or anxiety, but no immediate threat to organs. • Managed with oral antihypertensives and close outpatient follow-up. Hypertensive Emergency = BP ≥180/120 mmHg • With acute target organ damage (eg. MI, stroke, aortic dissection, pulmonary edema, acute kidney injury). • Requires immediate hospitalization and IV antihypertensives to reduce BP and prevent worsening damage.","steps":[{"agent":"DASH Diet + Sodium Restriction","dose":"Adopt the DASH diet with sodium <2 g/day on an ongoing basis.","why":"Emphasizing fruits, vegetables, whole grains, and legumes while limiting sodium, red meat, and processed foods can lower systolic BP by up to 11.5 mmHg. Supports vascular health and reduces fluid retention."},{"agent":"Magnesium Glycinate","dose":"300-500 mg/day for 12 weeks.","why":"Supports endothelial function and vascular tone, with studies showing average BP reductions of ~4/2 mmHg. Beneficial for patients with low dietary magnesium or mild-moderate hypertension."},{"agent":"Garlic Extract (standardized)","dose":"1000 mg/day providing ≥10 mg allicin for 12 weeks.","why":"Has vasodilatory and ACE-inhibitory effects, resulting in BP reductions averaging ~8/6 mmHg. Well tolerated and effective as adjunctive therapy."},{"agent":"CoQ10 (Ubiquinone or Ubiquinol)","dose":"150 mg/day for 12 weeks. Ongoing if effective.","why":"Enhances mitochondrial and endothelial function, with modest BP-lowering effects of ~10/5 mmHg. Especially useful in patients on antihypertensives or with statin-associated myalgia and fatigue."}],"notes":"Foundational dietary and lifestyle changes, especially sodium reduction and increased potassium-rich foods, offer reliable BP control. Herbal and nutrient adjuncts like garlic, magnesium, and CoQ10 further support vascular regulation. Exercise, stress management, and avoidance of excess alcohol and caffeine also reinforce long-term blood pressure stability. Coordinate care and monitor BP regularly to ensure safety and effectiveness.","flag":null},{"id":"atrial-fibrillation","title":"Atrial Fibrillation","condition":"Atrial fibrillation","background":"Atrial fibrillation (AF) is the most common sustained cardiac arrhythmia, characterized by disorganized, rapid electrical impulses in the atria leading to ineffective atrial contractions and an irregularly irregular ventricular rhythm. Etiologies include hypertension, coronary artery disease, valvular heart disease, heart failure, hyperthyroidism, alcohol use, and aging. AF affects over 6 million adults in the U.S., with increasing prevalence in individuals over age 65 and those with cardiovascular comorbidities. Pathophysiologically, structural and electrical remodeling of atrial tissue promotes ectopic foci and reentrant circuits, especially near the pulmonary veins. Clinical presentation may include palpitations, fatigue, dyspnea, dizziness, or it may be asymptomatic. Differential diagnoses include other supraventricular tachycardias, premature atrial contractions, and sinus arrhythmia. Diagnosis is confirmed via ECG showing absent P waves and irregularly irregular QRS complexes. Management includes rate or rhythm control (beta-blockers, calcium channel blockers, antiarrhythmics), stroke prevention with anticoagulation (based on CHA₂DS₂-V ASc score), and procedures like cardioversion or catheter ablation when indicated. Prognosis depends on underlying disease and stroke risk; complications include thromboembolism (notably stroke), heart failure, and reduced quality of life.","steps":[{"agent":"Mediterranean Diet","dose":null,"why":"Adopt a Mediterranean diet rich in vegetables, fruits, whole grains, legumes, olive oil, and fatty fish. The Mediterranean diet is associated with significantly reduced AFib risk (HR 0.62) and cardiovascular events. It’s safe with anticoagulant use and particularly effective in women."},{"agent":"Weight Loss + Fitness","dose":"Aim for >10% sustained weight loss and fitness improvement of >2 METs over 6-12 months.","why":"Reduces AFib burden, improves rhythm stability, and increases arrhythmia-free survival. This works synergistically with medical and nutritional interventions."},{"agent":"Magnesium Glycinate","dose":"500 mg/day for 8 weeks. Avoid if renal impairment is present.","why":"Often deficient in AFib patients and supports electrical conduction and rhythm regulation through cellular calcium handling and membrane stabilization."},{"agent":"CoQ10 (Ubiquinone or Ubiquinol)","dose":"150 mg/day for 12 weeks. Continue ongoing if tolerated.","why":"Enhances mitochondrial energy production and endothelial function."}],"notes":"AFib management benefits from a whole-systems approach that emphasizes weight control, cardioprotective nutrition, and mitochondrial support. The Mediterranean diet, magnesium, and CoQ10 are well-tolerated adjuncts to conventional care. Avoid energy drinks, monitor caffeine intake, and consider melatonin for beta-blocker- associated sleep issues. Regular reassessment and collaboration with cardiology are essential.","flag":null},{"id":"gastroesophageal-reflux-disease","title":"Gastroesophageal Reflux Disease","condition":"GERD","background":"Gastroesophageal reflux disease (GERD) is a chronic condition in which stomach contents flow backward into the esophagus, causing symptoms or mucosal injury due to impaired lower esophageal sphincter (LES) function. Etiologies include LES dysfunction, hiatal hernia, obesity, pregnancy, smoking, and certain foods or medications that reduce LES tone. GERD affects up to 20% of adults in Western countries and is a leading cause of outpatient visits for gastrointestinal complaints. Pathophysiologically, refluxed gastric acid and bile irritate the esophageal lining, leading to inflammation and symptoms. Clinically, GERD presents with heartburn, regurgitation, chest discomfort, and sometimes chronic cough, hoarseness, or dysphagia. Differential diagnoses include peptic ulcer disease, esophagitis, angina, and esophageal motility disorders. Diagnosis is often clinical but may be confirmed with upper endoscopy, pH monitoring, or esophageal manometry when atypical or refractory. Management includes lifestyle modifications (eg, weight loss, avoiding triggers, head-of-bed elevation), acid suppression with proton pump inhibitors (PPIs), and surgical options (eg, fundoplication) in select cases. Prognosis is favorable with treatment, but complications can include erosive esophagitis, strictures, Barrett’s esophagus, and increased risk of esophageal adenocarcinoma.","steps":[{"agent":"Dietary & Lifestyle Modifications","dose":null,"why":"Eat smaller, more frequent meals and avoid food 2-3 hours before bed. Elevate the head of your bed 6-8 inches to help prevent nighttime acid reflux. Adopt a Mediterranean-style low-glycemic diet on an ongoing basis. This eating pattern reduces reflux by minimizing gastric distention and improving gastric emptying. Evidence supports the Mediterranean diet being as effective as PPIs in symptom control and improves overall GI health."},{"agent":"Elimination of Trigger Foods","dose":null,"why":"Identify and avoid symptom-specific triggers using a food/symptom diary over a 4 week elimination phase. Common triggers include peppermint, citrus, chocolate, tomatoes, fried foods, alcohol, and caffeine."},{"agent":"Deglycyrrhizinated Licorice (DGL)","dose":"1000 mg chewable tablets 15-30 minutes before meals or PRN for acute symptoms.","why":"Acts as a mucosal protectant by enhancing mucus production and healing the esophageal lining without affecting cortisol metabolism. Especially useful in patients presenting with inflammation or mild esophagitis."},{"agent":"Digestive Bitters Formula","dose":"2 mL tincture 15 minutes before meals TID.","why":"Indicated in cases of suspected hypochlorhydria, bloating, or postprandial fullness contributing to reflux. Bitters (eg. gentian, artichoke leaf, dandelion root, orange peel) stimulate digestive secretions including stomach acid and bile, supporting proper digestion and gastric emptying. Supports digestion by restoring stomach acid levels, which enhances gastric emptying and reduces fermentation, a contributor to reflux in low-acid conditions. Avoid bitters in cases of active gastritis or peptic ulcers."}],"notes":"GERD responds well to a multifaceted approach targeting diet, lifestyle, and mucosal support. Evaluate for hypochlorhydria if symptoms persist despite trigger avoidance and demulcents. Monitor nutrient levels (B12, Mg, Fe) in patients using PPIs long term. Weight loss, mindful eating, and postural habits round out a strong foundation for lasting symptom control.","flag":null},{"id":"hepatic-steatosis","title":"Hepatic Steatosis","condition":"Hepatic steatosis","background":"Hepatic steatosis, also known as fatty liver disease, is characterized by excessive fat accumulation in hepatocytes, typically exceeding 5% of liver weight. It can be classified as nonalcoholic fatty liver disease (NAFLD) or alcoholic fatty liver disease (AFLD), depending on alcohol consumption history. Etiologies include obesity, insulin resistance, type 2 diabetes, dyslipidemia, and excessive alcohol use. NAFLD is the most common liver disorder in industrialized nations, affecting up to 25% of adults globally. Pathophysiologically, hepatic steatosis arises from imbalances in lipid uptake, synthesis, oxidation, and export, often driven by insulin resistance and oxidative stress. Most patients are asymptomatic, though some may report fatigue or right upper quadrant discomfort. Differential diagnoses include viral hepatitis, autoimmune hepatitis, hemochromatosis, and drug-induced liver injury. Diagnosis is typically made via imaging (eg, ultrasound, CT, MRI) and supported by liver function tests; biopsy is reserved for suspected steatohepatitis. Management focuses on lifestyle interventions - weight loss, diet, exercise - and control of metabolic comorbidities. Prognosis is generally good in simple steatosis, but progression to nonalcoholic steatohepatitis (NASH), fibrosis, cirrhosis, and hepatocellular carcinoma is possible if risk factors persist.","steps":[{"agent":"Hypocaloric Mediterranean Diet","dose":"≤1400 kcal/day consisting of low-glycemic carbs and cruciferous & inulin-rich vegetables.","why":"Improves hepatic fat content and decreases inflammation & fibrosis by enhancing insulin sensitivity, reducing oxidative stress, and modulating the gut-liver axis. Sustained dietary adherence supports long-term weight loss and metabolic correction."},{"agent":"Omega-3 Fatty Acids","dose":"3000 mg/day for 12 weeks.","why":"Reduces liver fat and inflammation by regulating hepatic lipid metabolism and downregulating inflammatory cytokines. Particularly effective in patients with elevated triglycerides or features of metabolic syndrome."},{"agent":"Alpha-Lipoic Acid (ALA)","dose":"600 mg twice daily for 12 weeks.","why":"Enhances insulin sensitivity and decreases oxidative stress in hepatocytes by improving mitochondrial function and regenerating intracellular antioxidants. Reduces liver enzymes and improves glucose control."},{"agent":"Probiotic + Prebiotic Support","dose":"10 billion CFU/day of multi-strain probiotic + 1 cup/day of inulin-rich vegetables for 12 weeks.","why":"Inulin-rich vegetables to incorporate include: chicory root, dandelion greens, garlic, onions, and asparagus. Improves gut microbiota diversity, reduces intestinal permeability, and lowers hepatic inflammation by reducing circulating endotoxins. Supports the gut-liver axis and may reduce progression of steatosis."}],"notes":"A hypocaloric, plant-rich Mediterranean diet combined with omega-3s, antioxidant support, and microbiome modulation forms the foundation for reversing NAFLD. Exercise (45 minutes, 3x/week) and ≥10% weight loss greatly enhance outcomes. Avoid alcohol, refined carbs, and processed foods. Monitor liver enzymes, HbA1c, and lipid markers during treatment.","flag":null},{"id":"chronic-obstructive-pulmonary-disease","title":"Chronic Obstructive Pulmonary Disease","condition":"Chronic obstructive pulmonary disease","background":"Chronic obstructive pulmonary disease (COPD) is a progressive respiratory condition characterized by persistent airflow limitation due to chronic bronchitis, emphysema, or both. The primary etiology is long-term exposure to noxious particles, most commonly cigarette smoke, though environmental pollutants, occupational exposures, and genetic factors (eg, alpha-1 antitrypsin deficiency) also contribute. COPD affects over 16 million adults in the U.S. and is a leading cause of morbidity and mortality worldwide, especially in individuals over age 40 with a smoking history. Pathophysiologically, COPD involves chronic airway inflammation, mucous hypersecretion, and alveolar wall destruction, leading to decreased elastic recoil and airflow obstruction. Clinical presentation includes chronic cough, sputum production, progressive dyspnea, and wheezing, often worsening over time. Differential diagnoses include asthma, heart failure, bronchiectasis, and interstitial lung disease. Diagnosis is confirmed with spirometry showing a post-bronchodilator FEV₁/FVC ratio <0.70. Management includes smoking cessation, bronchodilators (eg, LABAs, LAMAs), inhaled corticosteroids in select cases, pulmonary rehabilitation, and oxygen therapy for advanced disease. Prognosis varies with severity but is generally progressive; complications include respiratory infections, pulmonary hypertension, acute exacerbations, and respiratory failure.","steps":[{"agent":"Nutrient-Dense Meals + Whey Protein","dose":"High-calorie Mediterranean-style diet with additional whey protein supplementation (25 g/day).","why":"Supports weight maintenance and prevents pulmonary cachexia by ensuring sufficient caloric and protein intake, especially in patients with BMI ≤20. Smaller meals reduce postprandial dyspnea. Whey protein supplementation improves muscle preservation and recovery."},{"agent":"N-Acetylcysteine (NAC)","dose":"1000 mg twice daily for 12 weeks.","why":"Acts as a mucolytic and antioxidant by replenishing intracellular glutathione and thinning respiratory mucus, improving clearance and reducing exacerbation frequency. Particularly useful in moderate to severe COPD cases presenting with chronic productive cough."},{"agent":"Coenzyme Q10 (Ubiquinone)","dose":"150 mg daily for 12 weeks.","why":"Improves mitochondrial energy production and reduces oxidative stress, enhancing functional capacity and exercise tolerance in COPD patients with fatigue or decreased endurance."},{"agent":"Beetroot Juice","dose":"2 oz twice daily for 8 weeks.","why":"Rich in dietary nitrates that enhance nitric oxide availability, promoting vasodilation and oxygen delivery to tissues. Shown to improve exercise capacity as well as quality of life in patients with chronic lung disease."}],"notes":"A high-calorie, antioxidant-rich diet combined with targeted supplements like NAC, CoQ10, and beetroot juice supports lung function, reduces oxidative stress, and improves stamina in COPD. Emphasize smoking cessation, pulmonary rehab, and routine screening for malnutrition. Consistent nutritional and functional support slows disease progression and enhances quality of life.","flag":null},{"id":"lower-respiratory-infection","title":"Lower Respiratory Infection","condition":"Pneumonia","background":"Lower respiratory infections (LRIs) involve the trachea, bronchi, bronchioles, and lungs, with pneumonia and bronchitis being the most common forms. Etiologies include viral pathogens (eg, influenza, RSV , SARS-CoV-2), bacterial agents (eg, Streptococcus pneumoniae, Haemophilus influenzae), and less commonly fungi or atypical organisms. LRIs are a leading cause of morbidity and mortality worldwide, particularly affecting children under five, older adults, and immunocompromised individuals. Pathophysiologically, pathogens invade the lower airways, triggering inflammation, mucus production, and impaired gas exchange. Clinically, LRIs present with cough, sputum production, fever, dyspnea, and chest pain; pneumonia may additionally cause rales, decreased breath sounds, or hypoxia. Differential diagnoses include asthma, COPD exacerbation, pulmonary embolism, and heart failure. Diagnosis is based on clinical findings, chest imaging (especially for pneumonia), and supportive lab tests like CBC or sputum culture. Management depends on the cause and severity - viral infections may be self-limited or require antivirals, while bacterial infections are treated with appropriate antibiotics. Prognosis is generally good with prompt treatment but worsens with age, comorbidities, or delayed care. Complications: respiratory failure, sepsis, pleural effusion, and lung abscess.","steps":[{"agent":"Hydration + Rest","dose":"Minimum 2.5 liters/day of fluids including warm water, broths, and herbal teas.","why":"Supportive herbal teas include: thyme, licorice root, ginger, mullein, and peppermint. Adequate hydration thins mucus, promotes expectoration, and supports mucosal immunity. Rest enhances immune function and reduces metabolic demand during infection."},{"agent":"N-Acetylcysteine (NAC)","dose":"1000 mg twice daily for 7-10 days.","why":"Acts as a mucolytic, thereby reducing mucus viscosity & enhances glutathione levels, supporting antioxidant defense in bronchial tissue. It is especially effective in acute bronchitis or pneumonia with thick sputum."},{"agent":"Vitamin C","dose":"1000mg daily for 5-7 days.","why":"Supports neutrophil function and epithelial barrier integrity, helping reduce symptom severity and duration. Most effective when started early in the course of illness."},{"agent":"Zinc Citrate","dose":"30 mg daily for 5-7 days.","why":"Zinc functions to inhibit viral replication and supports innate and adaptive immunity. Daily use during early infection reduces symptom duration and intensity."}],"notes":"Lower respiratory infections benefit from early intervention with hydration, immune support, and mucolytics. Nutrient repletion (particularly of vitamin C, zinc, and NAC) helps modulate inflammation and enhance recovery. Encourage rest, light meals, and avoidance of smoking or environmental irritants during the acute phase. Reassess if symptoms persist or worsen after 7-10 days.","flag":"Filed under Pneumonia; the protocol covers lower respiratory infection broadly."},{"id":"irritable-bowel-disease","title":"Irritable Bowel Disease","condition":"Inflammatory bowel disease","background":"Inflammatory bowel disease (IBD) is a chronic, relapsing-remitting inflammatory disorder of the gastrointestinal tract, primarily Crohn's disease and ulcerative colitis. While the exact etiology is unknown, it is thought to result from a dysregulated immune response to intestinal microbiota in genetically susceptible individuals, influenced by environmental factors such as diet, smoking, and antibiotic use. IBD affects over 3 million people in the U.S., with peak onset between ages 15-35. Pathophysiologically, Crohn’s disease can affect any part of the GI tract with transmural inflammation and skip lesions, whereas ulcerative colitis involves continuous superficial inflammation limited to the colon and rectum. Common symptoms include abdominal pain, diarrhea (often bloody in UC), weight loss, fatigue, and extraintestinal manifestations like arthritis or skin rashes. Differential diagnoses include irritable bowel syndrome, celiac disease, infections, and colorectal cancer. Diagnosis is based on clinical history, endoscopy with biopsy, imaging, and inflammatory markers (eg, CRP, fecal calprotectin). Management includes anti-inflammatory agents (5-ASA), immunosuppressants, biologics (eg, TNF inhibitors), dietary support, and sometimes surgery. Prognosis varies; while many achieve remission, complications may include strictures, fistulas, abscesses, malnutrition, and increased colorectal cancer risk, especially in longstanding ulcerative colitis.","steps":[{"agent":"Elimination Diet","dose":null,"why":"Eliminate gluten, dairy, alcohol, processed meats, and carrageenan for 6 weeks. Follow this with systematic food reintroduction. This helps reduce intestinal inflammation and symptom severity by identifying and removing dietary triggers. IgG food sensitivity testing may prove helpful in guiding individualized elimination diets in IBD patients by identifying delayed immune reactions that contribute to persistent gut inflammation and symptoms."},{"agent":"Omega-3 Fish Oil","dose":"10 g/day of combined EPA and DHA for 12 weeks.","why":"Provides anti-inflammatory support by altering eicosanoid synthesis and modulating cytokine activity."},{"agent":"High-Dose Probiotics","dose":"100 billion CFU/day of mixed Lactobacillus and Bifidobacterium strains for 12 weeks.","why":"Enhances gut barrier function and immune regulation, shown to induce or maintain remission particularly in ulcerative colitis. Supports microbial diversity often disrupted in IBD."},{"agent":"Curcumin (Turmeric Extract)","dose":"1500 mg BID for 8 weeks.","why":"Exhibits potent anti-inflammatory effects via NF-κB inhibition and cytokine modulation. Effective in reducing disease activity and maintaining remission, especially in ulcerative colitis."}],"notes":"Combining dietary precision with anti-inflammatory and microbiome-targeted therapies offers strong support for IBD management. Ensure regular lab monitoring for micronutrient deficiencies and disease activity. Collaborate with a gastroenterologist and dietitian to personalize care and adjust protocols based on clinical response.","flag":"The document heads this page “Irritable bowel disease”, but its own first sentence reads “Inflammatory bowel disease (IBD) is a chronic, relapsing-remitting inflammatory disorder”. It is filed here under inflammatory bowel disease; irritable bowel syndrome has its own protocol."},{"id":"celiac-disease","title":"Celiac Disease","condition":"Celiac disease","background":"Celiac disease is a chronic autoimmune disorder triggered by the ingestion of gluten - a protein found in wheat, barley, and rye - in genetically susceptible individuals, leading to small intestinal inflammation and villous atrophy. The condition is strongly associated with HLA-DQ2 and HLA-DQ8 genotypes. It affects about 1% of the global population, though many cases remain undiagnosed due to variable symptom presentation. Pathophysiologically, gluten exposure in affected individuals activates T cells, leading to mucosal damage in the small intestine and impaired nutrient absorption. Clinical presentation ranges from classic symptoms like chronic diarrhea, weight loss, bloating, and fatigue to non-GI manifestations such as anemia, dermatitis herpetiformis, osteoporosis, or infertility. Differential diagnoses include irritable bowel syndrome, inflammatory bowel disease, lactose intolerance, and small intestinal bacterial overgrowth. Diagnosis is based on positive serologic tests (eg, anti-tTG IgA), confirmed by duodenal biopsy showing villous atrophy. Management requires strict lifelong adherence to a gluten-free diet, which typically leads to symptom resolution and mucosal healing. Prognosis is excellent with dietary compliance, but complications of untreated disease include malnutrition, osteoporosis, infertility, and increased risk of intestinal lymphoma.","steps":[{"agent":"Strict Gluten-Free Diet","dose":null,"why":"100% lifelong elimination of gluten-containing grains (wheat, barley, rye, spelt, kamut, farro, triticale). Eliminating gluten halts autoimmune destruction of the small intestine and allows mucosal healing. Use certified gluten-free substitutes such as quinoa, rice, buckwheat, corn, and GF oats. Cross-contamination must be meticulously avoided, including during food prep and dining out, to ensure full symptom resolution and prevent long-term complications."},{"agent":"Multivitamin","dose":"Calcium 1000 mg + magnesium 300 mg + vitamin D 2000 IU + vitamin K2 (100 mcg)","why":"Aims to replenish commonly depleted nutrients due to any associated malabsorption."},{"agent":"Iron + B12","dose":"Iron bisglycinate 25 mg daily + methylcobalamin 1000 mcg sublingually 3x/week for 3 months","why":"Supports correction of iron-deficiency anemia and B12 deficiency, which are common due to villous atrophy and impaired absorption in the proximal small intestine. Repletion improves fatigue, cognition, and energy."},{"agent":"Whole-Food Low-Glycemic Gluten-Free Diet","dose":null,"why":"Emphasize whole gluten-free grains, legumes, fruits, vegetables, and healthy fats daily Limit gluten-free packaged and processed foods high in sugar and saturated fat. This helps balance blood sugar, reduce inflammation, and support gut healing, while avoiding the common pitfall of processed GF diets that can worsen metabolic health and nutrient density."}],"notes":"Managing celiac disease requires strict, lifelong dietary vigilance supported by targeted nutrient repletion and whole-food choices. Persistent symptoms despite adherence should prompt reevaluation for cross- contamination, coexisting intolerances, or microscopic colitis. Regular lab monitoring ensures recovery and helps detect deficiencies or complications early. Educate patients on label reading, gluten cross-contact, and meal planning to promote long-term success.","flag":null},{"id":"irritable-bowel-syndrome","title":"Irritable Bowel Syndrome","condition":"Irritable bowel syndrome","background":"Irritable bowel syndrome (IBS) is a functional gastrointestinal disorder characterized by chronic abdominal pain and altered bowel habits (diarrhea, constipation, or both) in the absence of identifiable structural or biochemical abnormalities. The etiology is multifactorial, involving altered gut-brain axis communication, visceral hypersensitivity, dysbiosis, and psychosocial stressors. IBS affects 10-15% of the global population, with a higher prevalence in women and individuals under 50. Pathophysiologically, IBS involves abnormal gastrointestinal motility, heightened pain perception, and often post-infectious or inflammatory changes in the gut. Clinical presentation includes recurrent abdominal pain associated with changes in stool frequency or form, bloating, and relief after defecation. Differential diagnoses include inflammatory bowel disease, celiac disease, lactose intolerance, and colorectal cancer. Diagnosis is clinical, based on Rome IV criteria, and supported by exclusion of red flags (eg, weight loss, anemia, GI bleeding). Management includes dietary modifications (eg, low FODMAP diet), fiber, antispasmodics, psychological therapies, and medications targeting predominant symptoms (eg, laxatives or antidiarrheals). Prognosis is generally good, with symptom control achievable in most patients, but quality of life may be significantly impacted. IBS does not increase the risk of colorectal cancer or inflammatory complications.","steps":[{"agent":"Low FODMAP Diet","dose":null,"why":"Eliminate high-FODMAP foods for 4 weeks, then gradually reintroduce under supervision. Reduces fermentation and gas production in the gut, improving bloating, pain, and stool irregularities. Intended as a short-term intervention to help identify triggers and restore digestive tolerance."},{"agent":"Psyllium Husk","dose":"10 grams daily for 8 weeks.","why":"Incorporating soluble fiber improves stool form and regularity, especially in IBS with constipation (IBS-C), by normalizing transit time and feeding beneficial gut bacteria. Better tolerated than insoluble fibers and effective across different IBS subtypes."},{"agent":"Enteric-Coated Peppermint Oil","dose":"500 mg BID for 4 weeks.","why":"Relaxes intestinal smooth muscle and modulates motility via calcium channel blockade, providing relief from abdominal pain and cramping. Particularly effective in IBS with predominant pain or urgency."},{"agent":"Probiotic Supplementation","dose":"100 billion CFU/day for 8 weeks.","why":"Probiotic supplementation supports microbial diversity and improves gut barrier function, reducing bloating, discomfort, and inconsistent stools. Most beneficial when high-dose and multi-strain."}],"notes":"IBS management requires a multifactorial approach combining dietary precision, targeted supplementation, and stress regulation. Emphasize sleep hygiene, regular physical activity, and avoidance of processed foods, caffeine, and alcohol. Reassess symptoms periodically and adjust interventions based on IBS subtype and individual response.","flag":null},{"id":"small-intestinal-bacterial-overgrowth","title":"Small Intestinal Bacterial Overgrowth","condition":"Small intestinal bacterial overgrowth","background":"Small intestinal bacterial overgrowth (SIBO) is a condition characterized by excessive or abnormal types of bacteria in the small intestine, leading to impaired digestion and nutrient absorption. Etiologies include impaired intestinal motility (eg, diabetes, scleroderma), structural abnormalities (eg, adhesions, strictures), and reduced gastric acid or pancreatic enzyme secretion. While the exact prevalence is uncertain, SIBO is more common in individuals with irritable bowel syndrome (IBS), older adults, and those with prior GI surgery. Pathophysiologically, bacterial overgrowth disrupts nutrient absorption, deconjugates bile salts, and ferments carbohydrates, producing gas and inflammation. Clinical features include bloating, abdominal discomfort, flatulence, diarrhea, and in chronic cases, weight loss or nutrient deficiencies (eg, B12, fat-soluble vitamins). Differential diagnoses include IBS, lactose intolerance, celiac disease, and inflammatory bowel disease. Diagnosis is commonly made using breath tests (glucose or lactulose hydrogen/methane testing) or, less commonly, small bowel aspirate cultures. Management involves treating underlying causes, dietary modification (eg, low FODMAP), and antibiotics such as rifaximin. Prognosis is generally favorable with appropriate treatment, though recurrence is common. Complications may include malnutrition, osteoporosis, or bacterial translocation in severe or untreated cases.","steps":[{"agent":"Antimicrobial Herbal Protocol","dose":"Berberine 500 mg TID + oregano oil (standardized to 55% carvacrol) 200 mg BID x 4 weeks.","why":"Broad-spectrum antimicrobial herbs reduce bacterial overgrowth in the small intestine with efficacy comparable to rifaximin. Especially useful for methane-dominant or hydrogen-dominant SIBO, often with fewer systemic side effects than antibiotics."},{"agent":"Elemental Diet","dose":null,"why":"Exclusive elemental diet providing 1200-1600 kcal/day for 14 days. This specific diet starves bacterial overgrowth by providing pre-digested nutrients that are absorbed early in the small intestine, minimizing substrate for fermentation. Highly effective in breath test normalization."},{"agent":"Motility Support + Meal Spacing","dose":"2-3 mL tincture of bitters (eg. gentian, artichoke, ginger) 15 minutes before meals.","why":"Space meals 4-5 hours apart. Reassess after 6 weeks. Supports activation of the migrating motor complex and bile flow, which clears residual bacteria and prevents stasis. Meal spacing avoids repeated MMC interruption and is crucial for long-term relapse prevention."},{"agent":"Nutrient Repletion","dose":"Methylcobalamin 1000 mcg/day + vitamin D3 2000 IU/day + magnesium citrate 300 mg/day + iron bisglycinate","why":""},{"agent":"25 mg/day for 8 weeks (or until lab values normalize).","dose":null,"why":"Malabsorption in SIBO can cause deficiencies in B12, iron, fat-soluble vitamins, and minerals. Restoring these deficiencies supports energy, gut repair, and immune function during recovery."}],"notes":"SIBO treatment requires a strategic combination of microbial reduction, motility regulation, and nutrient restoration. Avoid snacking between meals, manage stress, and reassess for underlying contributors like hypochlorhydria or previous antibiotic overuse. Consider follow-up breath testing and gradual diet liberalization after symptoms resolve to support sustainable gut health.","flag":null},{"id":"generalized-anxiety-disorder","title":"Generalized Anxiety Disorder","condition":"Anxiety","background":"Generalized anxiety disorder (GAD) is a chronic psychiatric condition characterized by excessive, uncontrollable worry about various aspects of daily life for at least six months, accompanied by physical symptoms such as restlessness, fatigue, muscle tension, irritability, and sleep disturbances. The etiology is multifactorial, involving genetic predisposition, neurotransmitter imbalances (notably GABA, serotonin, and norepinephrine), and environmental stressors. GAD affects approximately 3-6% of the population, with higher prevalence in women and often co-occurring with depression or other anxiety disorders. Pathophysiologically, GAD is associated with heightened amygdala activity and dysregulation of the hypothalamic-pituitary-adrenal (HPA) axis, leading to persistent hyperarousal and worry. Clinical presentation includes pervasive anxiety not limited to specific triggers, often impairing social or occupational functioning. Differential diagnoses include panic disorder, major depressive disorder, OCD, PTSD, and medical conditions such as hyperthyroidism. Diagnosis is clinical, based on DSM-5 criteria. Management involves cognitive behavioral therapy (CBT), selective serotonin reuptake inhibitors (SSRIs), serotonin-norepinephrine reuptake inhibitors (SNRIs), and lifestyle interventions such as exercise and stress reduction. Prognosis is variable; while many improve with treatment, chronic symptoms can lead to reduced quality of life and increased risk for substance use and physical health issues.","steps":[{"agent":"L-Theanine","dose":"100 mg twice daily for 8 weeks.","why":"Promotes alpha brainwave activity and enhances GABA signaling, leading to a calm, focused mental state without sedation. Safe with SSRIs and especially useful for worry, tension, and cognitive hyperarousal in GAD."},{"agent":"Omega-3 Fatty Acids (EPA-dominant)","dose":"2000 mg EPA daily for 12 weeks.","why":"Reduces neuroinflammation and modulates neurotransmitter function associated with mood regulation. Shown in clinical studies to significantly reduce anxiety symptoms in individuals with GAD."},{"agent":"Magnesium Glycinate","dose":"300 mg daily for 8 weeks.","why":"Calms the nervous system by regulating NMDA receptors and supporting parasympathetic tone. Supportive in easing anxiety with muscle tension, restlessness, or sleep disturbance. Especially indicated in patients with poor dietary intake or high stress burden."},{"agent":"Kava Root Extract (Piper methysticum)","dose":"250 mg standardized extract (30% kavalactones) BID for 4 weeks.","why":"Acts as a non-sedating anxiolytic by modulating GABA-A receptors and reducing excessive neural excitation. Effective for GAD with prominent worry and tension. Be sure to screen for liver conditions before using."}],"notes":"GAD responds best to a multimodal plan combining nutritional, botanical, and lifestyle therapies. Encourage regular physical activity, mindfulness-based practices, and consistent, balanced meals. Screen for caffeine overuse and food intolerances. Address underlying stressors and recommend psychotherapy (eg. CBT or ACT) to reinforce long-term resilience.","flag":"Filed under Anxiety."},{"id":"major-depressive-disorder","title":"Major Depressive Disorder","condition":"Depression","background":"Major depressive disorder (MDD) is a common mood disorder characterized by persistent feelings of sadness, hopelessness, and loss of interest or pleasure in daily activities, lasting at least two weeks and accompanied by symptoms such as changes in sleep, appetite, energy, concentration, and suicidal ideation. Etiology is multifactorial, involving genetic predisposition, neurotransmitter imbalances (eg, serotonin, dopamine, norepinephrine), psychosocial stressors, and medical conditions. MDD affects approximately 7% of adults annually in the U.S., with higher prevalence in women and individuals with a history of trauma or chronic illness. Pathophysiologically, MDD involves dysregulation of the hypothalamic-pituitary-adrenal (HPA) axis, impaired neuroplasticity, and functional changes in brain regions such as the prefrontal cortex and amygdala. Clinically, patients present with emotional, cognitive, and physical symptoms that impair functioning. Differential diagnoses include bipolar disorder, dysthymia, grief, hypothyroidism, and substance-induced mood disorder. Diagnosis is clinical, based on DSM-5 criteria. Management includes psychotherapy (especially cognitive behavioral therapy), pharmacotherapy with antidepressants (eg, SSRIs, SNRIs), and lifestyle interventions; electroconvulsive therapy (ECT) may be used in severe or treatment-resistant cases. Prognosis varies—many respond well to treatment, but recurrence is common. Complications include social withdrawal, impaired occupational functioning, substance abuse, and increased risk of suicide.","steps":[{"agent":"Omega-3 Fatty Acids (EPA-dominant)","dose":"4000 mg EPA daily for 12 weeks.","why":"Reduces neuroinflammation and enhances serotonin and dopamine signaling, particularly when combined with SSRIs. Clinical evidence supports its efficacy in cases of moderate to severe depression."},{"agent":"Vitamin D3","dose":"Vitamin D 2000 IU daily for 12 weeks.","why":"Supports mood regulation via modulation of inflammatory cytokines and neurotransmitter synthesis. Especially beneficial in individuals with low serum vitamin D or seasonal affective features."},{"agent":"SAMe (S-adenosylmethionine)","dose":"400 mg twice daily for 8 weeks.","why":"Enhances methylation and monoamine synthesis, improving mood and energy. Effective in cases of major depression, but avoid using in bipolar patients due to risk of inducing mania."},{"agent":"Mediterranean Diet","dose":null,"why":"Whole-food diet emphasizing vegetables, legumes, fish, olive oil, nuts, and seeds for 12 weeks. Improves depressive symptoms through anti-inflammatory effects, improved nutrient density, and microbiome balance. Supported by the SMILES and HELFIMED trials as a first-line dietary intervention in depression."}],"notes":"MDD treatment is most effective when combining lifestyle therapy, nutrient support, and counseling. Encourage structured exercise, therapy (CBT, ACT), and social engagement where possible. Screen for iron deficiency, especially in menstruating individuals. Consider incorporating adjunct botanicals such as St. John’s wort or rhodiola based on subtype and medication use.","flag":"Filed under Depression."},{"id":"eczema","title":"Eczema","condition":"Eczema","background":"Eczema, or atopic dermatitis, is a chronic, relapsing inflammatory skin condition characterized by dry, itchy, and inflamed skin. It typically begins in childhood and is associated with a personal or family history of atopy, including asthma and allergic rhinitis. Etiology is multifactorial, involving genetic mutations (notably filaggrin), immune dysregulation, and environmental triggers such as allergens, irritants, and climate. Eczema affects up to 20% of children and 10% of adults worldwide. Pathophysiologically, a defective skin barrier allows increased transepidermal water loss and allergen penetration, triggering Th2-mediated inflammation and cytokine release. Clinically, eczema presents with pruritic, erythematous patches, often with lichenification or excoriation, typically on the face and extensor surfaces in children and flexural areas in adults. Differential diagnoses include contact dermatitis, psoriasis, seborrheic dermatitis, and scabies. Diagnosis is clinical based on history and exam findings. Management includes emollients, topical corticosteroids or calcineurin inhibitors, antihistamines, and avoidance of triggers. Severe cases may require systemic immunomodulators or biologics (eg, dupilumab). Prognosis varies - many children improve with age, though relapses are common. Complications include secondary infections, sleep disturbance, and reduced quality of life.","steps":[{"agent":"Elimination Diet with IgE Guidance","dose":null,"why":"Eliminate eggs, dairy, and wheat for 4 weeks, guided by IgE serology. These aforementioned common food intolerances can trigger or worsen eczema through immune activation and increased gut permeability. This approach targets underlying inflammation while helping identify dietary triggers specific to the patient. Consider food reintroduction after symptom stabilization."},{"agent":"GLA-Rich Plant Oil","dose":"2000 mg daily GLA-containing oil (evening primrose or hempseed oil) for 8 weeks.","why":"γ-Linolenic acid bypasses dysfunctional delta-6-desaturase activity, reducing pro-inflammatory leukotriene formation and improving skin hydration, itch, and lesion severity. Clinically effective in many cases despite mixed evidence in trials."},{"agent":"Omega-3 Fatty Acids","dose":"4000 mg/day of combined EPA/DHA for 12 weeks.","why":"Modulates inflammatory pathways and enhances skin barrier integrity by shifting the omega-6:3 ratio May reduce lesion severity and is especially helpful in those with coexisting atopic conditions."},{"agent":"Vitamin D","dose":"2000 IU/day for 12 weeks. Reassess and adjust dosage based on lab results.","why":"Vitamin D supports immune regulation and skin barrier function, with supplementation shown to reduce eczema severity, especially during the winter or in patients with low baseline levels."}],"notes":"Eczema is a multifactorial condition involving immune dysregulation, skin barrier dysfunction, and environmental triggers. Combining dietary elimination, targeted fatty acid support, and nutrient repletion offers strong foundational care. Consider topical herbal applications (eg. calendula, aloe), hydrotherapy, and probiotics as adjuncts. Reassess nutritional status and reintroduce foods cautiously to monitor tolerance over time.","flag":null},{"id":"psoriasis","title":"Psoriasis","condition":"Psoriasis","background":"Psoriasis is a chronic, immune-mediated skin disorder characterized by hyperproliferation of keratinocytes and systemic inflammation, most commonly presenting as well-demarcated, scaly erythematous plaques. The etiology involves a combination of genetic predisposition and environmental triggers such as infections, trauma, stress, and certain medications. Psoriasis affects about 2-3% of the global population and can occur at any age, with peaks in young adulthood and mid-life. Pathophysiologically, psoriasis involves dysregulated T-cell activity - particularly Th1 and Th17 pathways - leading to cytokine release (eg, TNF-α, IL-17, IL-23) and accelerated skin cell turnover. Clinical presentation includes thick, silver-scaled plaques on extensor surfaces, scalp, and lower back, often with pruritus or burning; nail pitting and psoriatic arthritis may also occur. Differential diagnoses include eczema, tinea corporis, seborrheic dermatitis, and cutaneous lupus. Diagnosis is clinical but may be confirmed by skin biopsy. Management depends on severity and includes topical agents (corticosteroids, vitamin D analogs), phototherapy, and systemic therapies (methotrexate, biologics targeting TNF-α or IL-23). Prognosis is chronic but manageable; complications may include joint damage from psoriatic arthritis, metabolic syndrome, and psychosocial distress.","steps":[{"agent":"Mediterranean Diet + Weight Loss","dose":null,"why":"Adopt a Mediterranean-style whole foods diet incorporating ≥5 servings/day of vegetables/fruits, olive oil as primary fat"},{"agent":"source, and 5% body weight loss goal over the duration of 12 weeks.","dose":null,"why":"This dietary pattern reduces systemic inflammation and psoriasis severity by lowering oxidative stress and improving metabolic and immune function. Strong evidence supports improvement in PASI scores with dietary adherence and modest weight loss."},{"agent":"Omega-3 Fatty Acids (EPA/DHA)","dose":"4000 mg daily of combined EPA/DHA for 12 weeks.","why":"Functions to decrease pro-inflammatory eicosanoid production and shifts the omega-3:6 balance in favor of anti- inflammatory activity. Supports resolution of plaque and joint symptoms, with added cardiovascular benefit in psoriatic arthritis."},{"agent":"Vitamin D3","dose":"2000 IU/day for 12 weeks.","why":"Titrate as necessary to achieve serum 25(OH)D of ~45 ng/mL. Vitamin D regulates keratinocyte turnover and modulates immune function in psoriatic skin. Supplementation is effective for reducing lesion severity, especially in those with documented deficiency or limited sun exposure."},{"agent":"Topical Botanicals","dose":"Apply aloe vera gel or calendula cream twice daily to affected areas for 4 weeks.","why":"Soothes inflamed skin, reduces itching and scaling, and promotes epithelial healing. Clinically useful as an adjunct to dietary therapy or conventional topicals, especially in mild to moderate cases of plaque psoriasis."}],"notes":"Psoriasis management benefits from addressing systemic inflammation, nutrient status, and skin-level irritation. Combine dietary therapy, omega-3 supplementation, and vitamin D with gentle, anti-inflammatory topicals for a comprehensive approach. Consider testing for gliadin antibodies, minimizing alcohol, and supporting mental well-being to improve outcomes.","flag":null},{"id":"acne-vulgaris","title":"Acne Vulgaris","condition":"Acne","background":"Acne vulgaris is a common chronic inflammatory skin disorder affecting the pilosebaceous unit, primarily seen during adolescence but also present in adults. It is caused by a combination of excess sebum production, follicular hyperkeratinization, Cutibacterium acnes colonization, and inflammation. Contributing factors include hormonal changes (especially androgens), genetics, stress, and certain medications or cosmetics. Acne affects up to 85% of teenagers and may persist into adulthood, particularly in women. Pathophysiologically, blocked hair follicles become comedones, which may develop into inflammatory papules, pustules, nodules, or cysts. It typically presents on the face, chest, and back. Differential diagnoses include rosacea, folliculitis, perioral dermatitis, and keratosis pilaris. Diagnosis is clinical based on lesion morphology and distribution. Management depends on severity and may include topical agents (benzoyl peroxide, retinoids, antibiotics), oral antibiotics, hormonal therapy (eg, oral contraceptives), and isotretinoin for severe cases. Prognosis is favorable with treatment, though relapses are common. Complications include scarring, post-inflammatory hyperpigmentation, and psychosocial impact such as anxiety or low self-esteem.","steps":[{"agent":"Zinc Picolinate","dose":null,"why":"30 mg/day as zinc picolinate Zinc modulates sebum production, reduces inflammation, and inhibits growth of Cutibacterium acnes. Deficiency is linked to more severe acne, and supplementation improves lesion count and healing. Its picolinate form offers high bioavailability. Monitor copper with prolonged use"},{"agent":"Low Glycemic Diet","dose":null,"why":"Low glycemic index eating reduces insulin and IGF-1 signaling, key drivers of keratinocyte proliferation and sebaceous"},{"agent":"gland activity. Clinical trials show meaningful reductions in acne severity within 8-12 weeks.","dose":null,"why":"Focus on consuming more vegetables, legumes, and intact whole grains, while minimizing refined carbs."},{"agent":"Dairy Elimination Trial","dose":null,"why":"Remove all dairy for 4-6 weeks, then reintroduce dairy products. Dairy, especially skim milk, may worsen acne by increasing IGF-1 and androgen load. A structured elimination and"},{"agent":"reintroduction helps identify personal triggers without over-restricting long-term.","dose":null,"why":"If dairy is determined as triggering, consider alternatives like oat milk or almond milk."},{"agent":"Omega-3 and GLA","dose":"2000 mg EPA/DHA daily + 400 mg GLA daily for 12 weeks","why":"These essential fatty acids reduce leukotriene B4 and other inflammatory mediators implicated in acne pathogenesis. Supplementation improves inflammatory lesions and may benefit mood and skin texture."}],"notes":"Acne reflects a complex interplay of inflammation, hormones, diet, and gut microbiome imbalance. This plan addresses systemic drivers while supporting skin healing and barrier integrity. Consider adjunctive therapies like probiotics, liver-supportive herbs (eg. burdock, dandelion), and stress modulation to approach this comprehensively. Reassess every 6-8 weeks for clinical progress and adjust doses as needed.","flag":null},{"id":"warts","title":"Warts","condition":"Warts","background":"Warts are benign epidermal growths caused by human papillomavirus (HPV) infection, most commonly types 1, 2, 4, 6, and 11. Transmission occurs through direct skin-to-skin contact or contaminated surfaces, often facilitated by breaks in the skin. Warts are common worldwide, particularly in immunocompromised individuals and children, with varying presentations depending on the HPV type and location. Pathophysiologically, HPV infects basal keratinocytes, promoting uncontrolled cell proliferation and forming verrucous lesions. Clinical types include common warts (verruca vulgaris), plantar warts, flat warts, and anogenital warts. Differential diagnoses include seborrheic keratosis, calluses, molluscum contagiosum, and squamous cell carcinoma. Diagnosis is clinical based on lesion appearance; biopsy is rarely needed. Management includes cryotherapy, salicylic acid, laser therapy, or immunomodulatory treatments. Prognosis is generally good, as many warts resolve spontaneously, though recurrence is common. Complications may include pain (especially plantar warts), cosmetic concerns, and, rarely, malignant transformation in immunosuppressed patients or with high-risk HPV types.","steps":[{"agent":"Garlic (Allium sativum)","dose":"Apply sliced fresh garlic clove directly on the wart. Cover with bandage. Replace daily for 2 weeks.","why":"Garlic has potent antiviral, immune-stimulating, and keratolytic effects, contributing to wart regression."},{"agent":"Green Tea Polyphenols (Sinecatechins 15%)","dose":null,"why":"Apply a thin layer (~0.5 cm length strip per wart) of 15% sinecatechins ointment (eg. Veregen) directly to the wart three"},{"agent":"times daily, using a cotton swab. Do not wash the area after application. Continue up to 12 weeks.","dose":null,"why":"Sinecatechins are standardized green tea polyphenols shown to have antiviral and antioxidant effects, likely helpful in immune modulation against HPV ."},{"agent":"Duct Tape Occlusion Therapy","dose":null,"why":"Apply standard duct tape over the wart continuously, replacing the tape every 5 days for up to 6 weeks. The occlusive environment may stimulate local immune response and physically irritate the lesion, helping eliminate the wart. This low-cost method has modest supportive evidence."},{"agent":"Thuja occidentalis Tincture","dose":"Apply 2-3 drops of tincture to wart BID. Cover with a bandage. Continue for 4 weeks.","why":"Traditionally used for viral skin lesions and is thought to have immunomodulatory and antiviral actions."}],"notes":"Warts are caused by low-risk strains of HPV and often resolve spontaneously, but persistent cases benefit from combined approaches. Topical therapies aim to disrupt the lesion and stimulate local immune activity. For recurrent cases, consider dietary garlic, zinc supplementation, and evaluation of immune status. Educate patients on consistent application and the importance of skin monitoring for irritation.","flag":null},{"id":"burns","title":"Burns","condition":"Burns","background":"Burns are injuries to the skin and underlying tissues caused by heat, chemicals, electricity, radiation, or friction. Sunburns are a common type of superficial burn resulting from excessive ultraviolet (UV) radiation exposure. Burns are categorized by depth - first-degree (superficial), second-degree (partial-thickness), and third-degree (full-thickness) - and severity is assessed based on total body surface area (TBSA) affected. Etiologies include household accidents, fire exposure, industrial incidents, and prolonged sun exposure. Globally, burns are a significant cause of morbidity, particularly in children and low-income settings. Pathophysiologically, burns cause direct tissue injury, capillary leakage, inflammation, and in severe cases, systemic responses like hypovolemia or shock. Clinical presentation depends on severity and may include erythema, blistering, pain, edema, or eschar formation. Sunburn typically presents with redness, tenderness, and peeling. Differential diagnoses include contact dermatitis, cellulitis, and photosensitive eruptions. Diagnosis is clinical, based on history and burn characteristics. Management ranges from supportive care (cool compresses, hydration, analgesics, topical antimicrobials) to advanced wound care and fluid resuscitation for extensive burns. Prognosis depends on burn depth, size, and comorbidities; mild burns heal well, but severe burns may lead to infection, scarring, contractures, or systemic complications such as sepsis or organ failure.","steps":[{"agent":"Manuka Honey","dose":null,"why":"Apply a thin layer of Manuka honey directly to the burn, then cover with a sterile non-stick gauze pad and secure with"},{"agent":"breathable dressing. Change dressing daily for 7 days or until re-epithelialization is complete.","dose":null,"why":"Manuka honey provides broad-spectrum antimicrobial protection and maintains a moist wound environment that promotes tissue regeneration. It also helps debride necrotic tissue and reduce inflammation, making it ideal for superficial to partial-thickness burns."},{"agent":"Aloe Vera Gel","dose":null,"why":"Apply a generous layer of pure, inner leaf aloe vera gel to the affected area 2-3 times daily. Aloe functions to soothe pain, reduce local inflammation, and support epithelial cell migration. Aloe is particularly effective during the initial healing phase and may help prevent scarring if used consistently."},{"agent":"Topical Hyaluronic Acid Gel","dose":null,"why":"Once the wound is clean and free of active exudate, apply a thin layer of 0.2% hyaluronic acid gel topically twice daily"},{"agent":"for up to 2 weeks.","dose":null,"why":"Hyaluronic acid helps retain moisture at the wound site, reduces discomfort, and supports collagen synthesis and tissue remodeling. It is best used in the re-epithelialization stage when tissue is regenerating."},{"agent":"Vitamin C + Zinc","dose":"Vitamin C: 1000 mg TID for 2 weeks + Zinc picolinate 30 mg daily for 2 weeks","why":"Vitamin C enhances collagen synthesis and immune defense, while zinc plays a critical role in wound healing and inflammation regulation."}],"notes":"This plan is appropriate for minor outpatient burns and supports both infection control and tissue repair naturally; however, for severe burns or those covering large body areas, refer to emergency care.","flag":null},{"id":"scars","title":"Scars","condition":"Wound healing","background":"Scars are the fibrous tissue that replaces normal skin following injury, representing the end stage of wound healing. Etiologies include surgical incisions, trauma, burns, infections, or inflammatory skin conditions like acne. Nearly everyone develops scars at some point, but the severity and appearance vary based on genetic factors, wound depth, location, and healing response. Pathophysiologically, scars form as fibroblasts deposit collagen during the proliferative and remodeling phases of healing. While most scars are flat and pale, abnormal healing may lead to hypertrophic scars (raised but within the wound margins) or keloids (overgrowth beyond the original wound). Clinical presentation depends on type, size, and location. Differential diagnoses include dermatofibroma, epidermal inclusion cysts, or neoplastic lesions. Diagnosis is clinical. Management may include topical therapies (silicone gel, corticosteroids), laser treatment, pressure therapy, or surgical revision in severe cases. Prognosis is generally good for functional recovery, though cosmetic or psychosocial impact may persist. Complications include restricted movement (especially over joints), chronic pain, or recurrence of keloids.","steps":[{"agent":"Topical Vitamin E","dose":"Apply 20,000 IU vitamin E oil directly to the scar 3 times daily for 8-12 weeks","why":"Vitamin E has antioxidant and anti-inflammatory effects supporting tissue remodeling."},{"agent":"Centella asiatica (Gotu Kola)","dose":"Apply standardized topical creams or serums with Centella extract BID for 12 weeks.","why":"Centella promotes fibroblast activity and collagen remodeling, reducing hypertrophic scar formation."}],"notes":"Scarring is a normal part of wound healing, but early intervention may reduce hypertrophic or keloid formation. Encourage gentle scar massage and correct vitamin D deficiency in at-risk individuals.","flag":"Filed under Wound healing, the nearest condition in this index."}],"suffixes":[{"suffix":"-azole","cls":"Antifungals","example":"fluconazole","caution":"Monitor liver function — hepatotoxicity risk.","group":"Anti-infectives"},{"suffix":"-cillin","cls":"Penicillin antibiotics","example":"amoxicillin","caution":"Watch for allergic reactions, including anaphylaxis.","group":"Anti-infectives"},{"suffix":"-cycline","cls":"Tetracycline antibiotics","example":"doxycycline","caution":"Avoid in children and pregnancy — discolours teeth and inhibits bone growth.","group":"Anti-infectives"},{"suffix":"-mycin / -micin","cls":"Antibiotics","example":"erythromycin, gentamicin","caution":"Gentamicin can cause ototoxicity and nephrotoxicity.","group":"Anti-infectives"},{"suffix":"-oxacin","cls":"Broad-spectrum antibiotics (fluoroquinolones)","example":"ciprofloxacin","caution":"Risk of tendon rupture; avoid in children and pregnant women.","group":"Anti-infectives"},{"suffix":"-navir","cls":"Protease inhibitors","example":"ritonavir","caution":"Can cause hyperlipidaemia and metabolic disturbances.","group":"Anti-infectives"},{"suffix":"-vir","cls":"Antivirals","example":"acyclovir","caution":"Hydrate well to prevent nephrotoxicity.","group":"Anti-infectives"},{"suffix":"-statin","cls":"Antihyperlipidaemics","example":"atorvastatin","caution":"Monitor liver enzymes; watch for myopathy and rhabdomyolysis.","group":"Cardiovascular"},{"suffix":"-pril","cls":"ACE inhibitors","example":"enalapril","caution":"Dry cough from bradykinin build-up; monitor potassium for hyperkalaemia.","group":"Cardiovascular"},{"suffix":"-artan","cls":"ARBs","example":"losartan","caution":"Avoid in pregnancy — teratogenic.","group":"Cardiovascular"},{"suffix":"-olol","cls":"Beta blockers","example":"metoprolol","caution":"Taper off slowly to prevent rebound tachycardia or hypertension.","group":"Cardiovascular"},{"suffix":"-pine / -amil","cls":"Calcium channel blockers","example":"amlodipine, verapamil","caution":"Peripheral oedema, and constipation with verapamil.","group":"Cardiovascular"},{"suffix":"-zosin","cls":"Alpha-1 blockers","example":"prazosin","caution":"First-dose orthostatic hypotension is common — give at bedtime.","group":"Cardiovascular"},{"suffix":"-parin","cls":"Heparin derivatives","example":"enoxaparin","caution":"Monitor for heparin-induced thrombocytopenia (HIT).","group":"Cardiovascular"},{"suffix":"-xaban","cls":"Direct factor Xa inhibitors","example":"rivaroxaban","caution":"No routine coagulation monitoring, but watch for bleeding.","group":"Cardiovascular"},{"suffix":"-zide","cls":"Thiazide diuretics","example":"hydrochlorothiazide","caution":"Monitor electrolytes, especially potassium — hypokalaemia risk.","group":"Cardiovascular"},{"suffix":"-mide","cls":"Loop diuretics","example":"furosemide","caution":"Monitor for hypokalaemia and ototoxicity.","group":"Cardiovascular"},{"suffix":"-phylline","cls":"Methylxanthines","example":"theophylline","caution":"Narrow therapeutic index — monitor levels to prevent toxicity.","group":"Respiratory"},{"suffix":"-lukast","cls":"Leukotriene receptor antagonists","example":"montelukast","caution":"Can cause neuropsychiatric effects and mood changes.","group":"Respiratory"},{"suffix":"-tropium","cls":"Muscarinic antagonists","example":"tiotropium","caution":"Dry mouth is the common side effect.","group":"Respiratory"},{"suffix":"-terol","cls":"Beta-agonists","example":"albuterol","caution":"Overuse leads to tachycardia and hypokalaemia.","group":"Respiratory"},{"suffix":"-glitazone","cls":"Thiazolidinediones","example":"pioglitazone","caution":"Contraindicated in heart failure; causes fluid retention.","group":"Endocrine & metabolic"},{"suffix":"-sone","cls":"Steroids","example":"prednisone","caution":"Taper after prolonged use to prevent adrenal insufficiency.","group":"Endocrine & metabolic"},{"suffix":"-dronate","cls":"Bisphosphonates","example":"alendronate","caution":"Take on an empty stomach and stay upright 30 minutes to prevent oesophagitis.","group":"Endocrine & metabolic"},{"suffix":"-gliptin","cls":"DPP-4 inhibitors","example":"sitagliptin","caution":"Rare but serious: pancreatitis.","group":"Endocrine & metabolic"},{"suffix":"-ide","cls":"Oral hypoglycaemics","example":"glipizide","caution":"Risk of hypoglycaemia — administer with meals.","group":"Endocrine & metabolic"},{"suffix":"-lam / -pam","cls":"Benzodiazepines","example":"lorazepam, alprazolam","caution":"Risk of dependence and withdrawal; avoid long-term use.","group":"Neurology & psychiatry"},{"suffix":"-bital","cls":"Barbiturates","example":"phenobarbital","caution":"Risk of respiratory depression and dependence.","group":"Neurology & psychiatry"},{"suffix":"-stigmine","cls":"Acetylcholinesterase inhibitors","example":"neostigmine","caution":"Watch for cholinergic crisis — excessive muscarinic stimulation.","group":"Neurology & psychiatry"},{"suffix":"-triptan","cls":"Serotonin receptor agonists","example":"sumatriptan","caution":"Contraindicated in cardiovascular disease — vasospasm risk.","group":"Neurology & psychiatry"},{"suffix":"-dine","cls":"H2 blockers","example":"ranitidine","caution":"May mask the symptoms of gastric cancer.","group":"Gastrointestinal"},{"suffix":"-prazole","cls":"Proton pump inhibitors","example":"omeprazole","caution":"Long-term use raises the risk of fractures and C. difficile infection.","group":"Gastrointestinal"},{"suffix":"-pramide","cls":"Prokinetic agents","example":"metoclopramide","caution":"Extrapyramidal effects including tardive dyskinesia; contraindicated in bowel obstruction.","group":"Gastrointestinal"},{"suffix":"-setron","cls":"5-HT3 receptor antagonists","example":"ondansetron","caution":"Monitor for QT prolongation at high doses.","group":"Gastrointestinal"},{"suffix":"-mab","cls":"Monoclonal antibodies","example":"adalimumab","caution":"Increased risk of infection — immunosuppressive.","group":"Oncology & immunology"},{"suffix":"-zumab","cls":"Humanised monoclonal antibodies","example":"trastuzumab","caution":"Cardiotoxicity is a concern.","group":"Oncology & immunology"},{"suffix":"-cept","cls":"Fusion protein inhibitors","example":"etanercept","caution":"Screen for latent tuberculosis before starting therapy.","group":"Oncology & immunology"},{"suffix":"-mustine","cls":"Nitrosoureas","example":"carmustine","caution":"Delayed myelosuppression; crosses the blood-brain barrier.","group":"Oncology & immunology"},{"suffix":"-done","cls":"Opioid analgesics","example":"oxycodone, methadone","caution":"Monitor for respiratory depression, sedation, constipation and dependence.","group":"Pain & anaesthesia"},{"suffix":"-caine","cls":"Local anaesthetics","example":"lidocaine","caution":"CNS toxicity, including seizures, at high doses.","group":"Pain & anaesthesia"},{"suffix":"-curium / -onium","cls":"Neuromuscular blockers","example":"atracurium","caution":"Always provide respiratory support during use.","group":"Pain & anaesthesia"}],"suffixGroups":["Anti-infectives","Cardiovascular","Respiratory","Endocrine & metabolic","Neurology & psychiatry","Gastrointestinal","Oncology & immunology","Pain & anaesthesia"],"suffixFlag":"The card prints the neuromuscular blocker stem as “-nuim”. The actual stems are ‑curium and ‑onium, as in atracurium and rocuronium; it is corrected here."};
